import spidev

MIN_CHANNEL = 0
MAX_CHANNEL = 7
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1_000_000


def read_mcp3208_channel(channel: int) -> int:
    """Read a single-ended channel from the MCP3208 and return the raw 12-bit count (0-4095)."""
    if not MIN_CHANNEL <= channel <= MAX_CHANNEL:
        print(f"Error: channel must be between {MIN_CHANNEL} and {MAX_CHANNEL}, got {channel}")
        return -1

    spi = spidev.SpiDev()
    try:
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = 0
        spi.lsbfirst = False

        # MCP3208 single-ended read command: start bit, single/diff=1, channel bits
        cmd = 0b11000000 | ((channel & 0x07) << 3)
        tx = [0x01, cmd, 0x00]
        rx = spi.xfer2(tx)

        if rx is None or len(rx) < 3:
            print("Error: incomplete SPI response")
            return -1

        value = ((rx[1] & 0x0F) << 8) | rx[2]
        return value & 0x0FFF

    except FileNotFoundError:
        print(f"Error: SPI device /dev/spidev{SPI_BUS}.{SPI_DEVICE} not found")
        return -1
    except PermissionError:
        print(f"Error: permission denied opening /dev/spidev{SPI_BUS}.{SPI_DEVICE}")
        return -1
    except OSError as e:
        print(f"Error: SPI transfer failed: {e}")
        return -1
    finally:
        try:
            spi.close()
        except Exception:
            pass


def read_mcp3208_float(channel: int) -> float:
    """Read a single-ended channel from the MCP3208 and return a normalized float in [0.0, 1.0]."""
    raw = read_mcp3208_channel(channel)
    if raw < 0:
        return -1.0
    return raw / 4095.0


def read_mcp3208_raw(channel: int) -> int:
    """Read a single-ended channel from the MCP3208 and return the raw 12-bit count (0-4095)."""
    raw = read_mcp3208_channel(channel)
    if raw < 0:
        return -1
    return raw


