import spidev
import time
import datetime
import csv
import os
import signal
import sys
import logging

# --- Configuration ---
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1_000_000
DHT22_PIN = 4
CSV_FILE = 'gas_data.csv'
ERROR_LOG = 'error.log'
CALIBRATION_DURATION = 60
MOVING_AVERAGE_WINDOW = 5
READ_INTERVAL = 60
TEMP_MIN = -20.0
TEMP_MAX = 50.0
HUM_MIN = 0.0
HUM_MAX = 100.0

# --- Logging Setup ---
logging.basicConfig(
    filename=ERROR_LOG,
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# --- Global State for Signal Handling ---
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)

# --- Hardware Abstraction ---
class MCP3008:
    def __init__(self, bus=SPI_BUS, device=SPI_DEVICE, max_speed_hz=SPI_MAX_SPEED_HZ):
        self.spi = spidev.SpiDev()
        try:
            self.spi.open(bus, device)
            self.spi.max_speed_hz = max_speed_hz
            self.spi.mode = 0
        except Exception as e:
            logging.error(f"Failed to initialize SPI (bus={bus}, device={device}): {e}")
            raise

    def read_channel(self, channel):
        if not 0 <= channel <= 7:
            raise ValueError("Channel must be between 0 and 7")
        try:
            # MCP3008 single-ended read: start bit, config byte, dummy byte
            r = self.spi.xfer2([1, (8 + channel) << 4, 0])
            return ((r[1] & 3) << 8) + r[2]
        except Exception as e:
            logging.error(f"SPI read error on channel {channel}: {e}")
            raise

    def close(self):
        try:
            self.spi.close()
        except Exception as e:
            logging.error(f"Error closing SPI: {e}")

class DHT22:
    def __init__(self, pin):
        self.pin = pin
        try:
            import RPi.GPIO as GPIO
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        except Exception as e:
            logging.error(f"Failed to initialize GPIO pin {pin}: {e}")
            raise

    def read(self):
        try:
            import RPi.GPIO as GPIO
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.OUT)
            GPIO.output(self.pin, GPIO.LOW)
            time.sleep(0.018)
            GPIO.output(self.pin, GPIO.HIGH)
            time.sleep(0.00004)
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

            data = GPIO.input(self.pin)
            data <<= 7
            for _ in range(10):
                time.sleep(0.000001)
                data <<= 1
                data |= GPIO.input(self.pin)

            humidity = (data[0] << 5) | (data[1] >> 3)
            temp = (data[1] & 0x07) << 8 | data[2]
            checksum = data[3]

            if (humidity << 8 | temp) != 0:
                raise ValueError("DHT22 returned 0 for temperature/humidity")
            if (humidity << 8 | temp) & 0xFFFF != checksum:
                raise ValueError("DHT22 checksum mismatch")

            return temp / 10.0, humidity / 100.0
        except Exception as e:
            logging.error(f"DHT22 read error: {e}")
            raise

    def close(self):
        try:
            import RPi.GPIO as GPIO
            GPIO.cleanup()
        except Exception as e:
            logging.error(f"Error cleaning up GPIO: {e}")

# --- Data Validation ---
def validate_sensor_data(temperature, humidity):
    if not (TEMP_MIN <= temperature <= TEMP_MAX):
        logging.error(f"Invalid temperature: {temperature}")
        return False
    if not (HUM_MIN <= humidity <= HUM_MAX):
        logging.error(f"Invalid humidity: {humidity}")
        return False
    return True

# --- Moving Average ---
def moving_average(data, window_size):
    if not data:
        return 0.0
    if len(data) < window_size:
        return sum(data) / len(data)
    return sum(data[-window_size:]) / window_size

# --- CSV Logger ---
class CSVLogger:
    def __init__(self, filename):
        self.filename = filename
        self.fieldnames = ['timestamp', 'adc0', 'adc1', 'temperature', 'humidity', 'moving_avg_temp']
        self.file = None
        self._init_file()

    def _init_file(self):
        try:
            self.file = open(self.filename, 'a', newline='')
            writer = csv.DictWriter(self.file, fieldnames=self.fieldnames)
            if self.file.tell() == 0:
                writer.writeheader()
                self.file.flush()
        except Exception as e:
            logging.error(f"Failed to open CSV file {self.filename}: {e}")
            self.file = None

    def log(self, adc0, adc1, temperature, humidity, moving_avg_temp):
        if not self.file:
            return
        try:
            writer = csv.DictWriter(self.file, fieldnames=self.fieldnames)
            writer.writerow({
                'timestamp': datetime.datetime.now().isoformat(),
                'adc0': adc0,
                'adc1': adc1,
                'temperature': temperature,
                'humidity': humidity,
                'moving_avg_temp': moving_avg_temp
            })
            self.file.flush()
        except Exception as e:
            logging.error(f"Failed to write to CSV: {e}")

    def close(self):
        if self.file:
            try:
                self.file.close()
            except Exception as e:
                logging.error(f"Error closing CSV file: {e}")

# --- Main ---
def main():
    mcp = None
    dht = None
    csv_logger = None

    try:
        mcp = MCP3008()
        dht = DHT22(DHT22_PIN)
        csv_logger = CSVLogger(CSV_FILE)

        logging.info("Calibrating DHT22 for 60 seconds...")
        start_time = time.time()
        adc_readings = []
        temp_readings = []
        hum_readings = []

        while _running and (time.time() - start_time) < CALIBRATION_DURATION:
            try:
                adc0 = mcp.read_channel(0)
                adc1 = mcp.read_channel(1)
                temp, hum = dht.read()
                adc_readings.append(adc0)
                temp_readings.append(temp)
                hum_readings.append(hum)
            except Exception as e:
                logging.error(f"Error during calibration: {e}")
            time.sleep(1)

        if not _running:
            return

        logging.info("Calibration complete. Starting data logging.")

        while _running:
            try:
                adc0 = mcp.read_channel(0)
                adc1 = mcp.read_channel(1)
                temp, hum = dht.read()

                if validate_sensor_data(temp, hum):
                    adc_readings.append(adc0)
                    temp_readings.append(temp)
                    hum_readings.append(hum)

                    moving_avg_temp = moving_average(temp_readings, MOVING_AVERAGE_WINDOW)
                    csv_logger.log(adc0, adc1, temp, hum, moving_avg_temp)
                else:
                    logging.warning("Invalid sensor data discarded.")

            except Exception as e:
                logging.error(f"Error during main loop: {e}")

            time.sleep(READ_INTERVAL)

    except Exception as e:
        logging.error(f"Fatal error: {e}")
    finally:
        if csv_logger:
            csv_logger.close()
        if dht:
            dht.close()
        if mcp:
            mcp.close()
        logging.info("Program terminated gracefully.")

if __name__ == '__main__':
    main()

