import signal
import sys
import time
import math
import logging

import smbus2
from gpiozero import OutputDevice, PWMOutputDevice

try:
    from lsm303 import LSM303
    from adafruit_ads1x15.ads1015 import ADS1015
    from adafruit_ads1x15.analog_in import AnalogIn
except ImportError as e:
    print(f"Missing required library: {e}")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
MOTOR_DIR_PIN = 20
MOTOR_STEP_PIN = 21
MOTOR_MS0_PIN = 14
MOTOR_MS1_PIN = 15
MOTOR_CW = 1
MOTOR_CCW = 0
MOTOR_RESOLUTION = {
    'Full': (0, 0),
    'Half': (1, 0),
    '1/4': (0, 1),
    '1/8': (1, 1)
}
ADC_GAIN = 1
ADC_MAX_VALUE = 2047  # 12-bit ADC max value for gain=1
ADC_VOLTAGE_FACTOR = 3.3 / ADC_MAX_VALUE
PWM_FREQUENCY = 500

# Global state for signal handling
_running = True
_motor_pwm = None


def signal_handler(signum, frame):
    global _running
    logging.info(f"Signal {signum} received, shutting down...")
    _running = False


class MotorDriver:
    def __init__(self, dir_pin, step_pin, ms0_pin, ms1_pin):
        self.dir_pin = OutputDevice(dir_pin)
        self.step_pin = PWMOutputDevice(step_pin, frequency=PWM_FREQUENCY)
        self.ms0_pin = OutputDevice(ms0_pin)
        self.ms1_pin = OutputDevice(ms1_pin)
        self.set_resolution('Full')
        self.step(MOTOR_CCW)
        self.stop()

    def set_resolution(self, resolution_str):
        ms_values = MOTOR_RESOLUTION[resolution_str]
        self.ms0_pin.value = ms_values[0]
        self.ms1_pin.value = ms_values[1]

    def set_direction(self, direction):
        if direction == MOTOR_CW:
            self.dir_pin.on()
        else:
            self.dir_pin.off()

    def step(self, direction):
        self.set_direction(direction)
        self.step_pin.value = 0.5

    def stop(self):
        self.step_pin.value = 0

    def set_speed(self, duty_cycle):
        duty_cycle = max(0, min(255, int(duty_cycle)))
        self.step_pin.value = duty_cycle / 255.0

    def close(self):
        self.stop()
        for pin in (self.dir_pin, self.ms0_pin, self.ms1_pin, self.step_pin):
            try:
                pin.close()
            except Exception:
                pass


