import smbus
import time
import signal
import sys

# Constants
I2C_BUS = 1
ADS1115_ADDRESS = 0x5C
ADS1115_CONVERSION_REGISTER = 0x00
ADS1115_CONFIG_REGISTER = 0x01

# ADS1115 Config: Single-shot, AIN0, ±4.096V, 128 SPS, comparator disabled
ADS1115_CONFIG_BYTES = [0xC3, 0xE3]

# Voltage divider: 2.0V battery maps to 0V ADC, 4.2V battery maps to 3.3V ADC
VOLTAGE_DIVIDER_FACTOR = 3.3 / 2.0

# Global flag for graceful shutdown
_running = True


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


def initialize_i2c(bus_number):
    """Initialize the I2C bus with error handling."""
    try:
        return smbus.SMBus(bus_number)
    except FileNotFoundError:
        print(f"Error: I2C bus {bus_number} not found. Enable I2C via raspi-config.")
        return None
    except PermissionError:
        print(f"Error: Permission denied on I2C bus {bus_number}. Run as root or add user to i2c group.")
        return None
    except OSError as e:
        print(f"Error initializing I2C bus {bus_number}: {e}")
        return None


def configure_ads1115(i2c_bus, address):
    """Configure the ADS1115 for a single-shot conversion on channel A0."""
    try:
        i2c_bus.write_i2c_block_data(address, ADS1115_CONFIG_REGISTER, ADS1115_CONFIG_BYTES)
        return True
    except OSError as e:
        print(f"Error configuring ADS1115 at address 0x{address:02X}: {e}")
        return False


def read_raw_ads1115(i2c_bus, address):
    """Trigger a single-shot conversion and read the raw 16-bit result."""
    try:
        # Write config to start conversion
        i2c_bus.write_i2c_block_data(address, ADS1115_CONFIG_REGISTER, ADS1115_CONFIG_BYTES)
        # Wait for conversion to complete (128 SPS -> ~7.8ms, 10ms is safe)
        time.sleep(0.01)
        # Read 2 bytes from conversion register
        data = i2c_bus.read_i2c_block_data(address, ADS1115_CONVERSION_REGISTER, 2)
        raw_data = (data[0] << 8) | data[1]
        # Convert to signed 16-bit two's complement
        if raw_data >= 0x8000:
            raw_data -= 0x10000
        return raw_data
    except OSError as e:
        print(f"Error reading ADS1115: {e}")
        return None


def calculate_battery_voltage(raw_data):
    """Convert raw ADC value to battery voltage using voltage divider ratio."""
    if raw_data is None:
        return None
    # ADS1115 is 16-bit signed, full scale is ±3.3V (for ±4.096V range)
    # For ±4.096V range, full scale is 32767 counts
    # Voltage = (raw_data / 32767) * 4.096
    voltage = (raw_data / 32767.0) * 4.096
    return voltage * VOLTAGE_DIVIDER_FACTOR


def calculate_battery_percentage(voltage):
    """Calculate battery percentage from voltage, clamped to 0-100."""
    if voltage is None:
        return None
    percentage = (voltage / 4.2) * 100.0
    return max(0.0, min(100.0, percentage))


def main():
    """Main loop: read battery voltage and charge percentage every second."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c_bus = initialize_i2c(I2C_BUS)
    if i2c_bus is None:
        sys.exit(1)

    last_percentage = None

    try:
        while _running:
            if not configure_ads1115(i2c_bus, ADS1115_ADDRESS):
                time.sleep(1)
                continue

            raw_data = read_raw_ads1115(i2c_bus, ADS1115_ADDRESS)
            if raw_data is None:
                time.sleep(1)
                continue

            battery_voltage = calculate_battery_voltage(raw_data)
            percentage = calculate_battery_percentage(battery_voltage)

            if percentage is not None and last_percentage is None:
                last_percentage = percentage
            elif percentage is not None and last_percentage is not None:
                if abs(percentage - last_percentage) > 1.0:
                    last_percentage = percentage

            if last_percentage is not None:
                print(f"Battery Voltage: {battery_voltage:.2f} V | Charge: {last_percentage:.2f}%")
            else:
                print("Battery Voltage: {:.2f} V | Charge: N/A%")

            time.sleep(1)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if i2c_bus is not None:
            try:
                i2c_bus.close()
                print("I2C bus closed.")
            except Exception as e:
                print(f"Error closing I2C bus: {e}")
        print("Exiting program.")


if __name__ == "__main__":
    main()

