import spidev
import time
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

PUMP_RELAY_PIN = 18
MCP3008_CHANNEL = 0
DRY_THRESHOLD = 450
SPI_BUS = 0
SPI_DEVICE = 0
SPI_SPEED_HZ = 1350000


class SmartGardenController:
    def __init__(self, pump_pin, channel, dry_threshold, spi_bus=SPI_BUS, spi_device=SPI_DEVICE, spi_speed=SPI_SPEED_HZ):
        self.pump_pin = pump_pin
        self.channel = channel
        self.dry_threshold = dry_threshold
        self.spi = None
        self._spi_opened = False
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(spi_bus, spi_device)
            self.spi.max_speed_hz = spi_speed
            self.spi.mode = 0
            self._spi_opened = True
            logging.info("SPI bus %d, device %d opened at %d Hz", spi_bus, spi_device, spi_speed)
        except Exception as e:
            logging.error("Failed to open SPI bus: %s", e)
            raise

        try:
            self.pump_pin = self._setup_gpio(pump_pin)
        except Exception as e:
            logging.error("Failed to setup GPIO pin %d: %s", pump_pin, e)
            self.close()
            raise

    def _setup_gpio(self, pin):
        try:
            import RPi.GPIO as GPIO
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
            return pin
        except Exception as e:
            logging.error("Failed to setup GPIO pin %d: %s", pin, e)
            raise

    def _read_mcp3008(self, channel):
        if not self._spi_opened:
            raise RuntimeError("SPI bus is not open")
        if not 0 <= channel <= 7:
            raise ValueError("Channel must be 0-7")
        try:
            adc = self.spi.xfer2([1, (8 + channel) << 4, 0])
            data = ((adc[1] & 3) << 8) + adc[2]
            return data
        except Exception as e:
            logging.error("SPI read error on channel %d: %s", channel, e)
            raise

    def read_moisture(self):
        raw = self._read_mcp3008(self.channel)
        return raw

    def run_pump(self, seconds):
        try:
            self.pump_pin = self._setup_gpio(self.pump_pin)
        except Exception as e:
            logging.error("Failed to re-setup GPIO pin %d: %s", self.pump_pin, e)
            raise
        try:
            logging.info("Pump ON for %d seconds", seconds)
            time.sleep(seconds)
            logging.info("Pump OFF")
        except Exception as e:
            logging.error("Pump control error: %s", e)
            raise
        finally:
            try:
                self.pump_pin = self._cleanup_gpio(self.pump_pin)
            except Exception as e:
                logging.error("GPIO cleanup error: %s", e)

    def irrigation_cycle(self):
        try:
            moisture = self.read_moisture()
            logging.info("Soil moisture raw: %d", moisture)
            if moisture > self.dry_threshold:
                self.run_pump(2)
                return True
            logging.info("Soil moisture OK, no watering needed")
            return False
        except Exception as e:
            logging.error("Cycle error: %s", e)
            return False

    def close(self):
        if self.spi is not None:
            try:
                self.spi.close()
            except Exception as e:
                logging.error("Error closing SPI: %s", e)
            finally:
                self._spi_opened = False
                self.spi = None
        try:
            self._cleanup_gpio(self.pump_pin)
        except Exception as e:
            logging.error("GPIO cleanup error: %s", e)

    def _cleanup_gpio(self, pin):
        try:
            import RPi.GPIO as GPIO
            GPIO.output(pin, GPIO.LOW)
            GPIO.cleanup(pin)
            return pin
        except Exception as e:
            logging.error("GPIO cleanup error: %s", e)
            raise


def schedule_cycles(controller, cycle_count, interval_seconds):
    for i in range(cycle_count):
        logging.info("Cycle %d/%d", i + 1, cycle_count)
        controller.irrigation_cycle()
        if i < cycle_count - 1:
            time.sleep(interval_seconds)


def main():
    controller = None
    try:
        controller = SmartGardenController(PUMP_RELAY_PIN, MCP3008_CHANNEL, DRY_THRESHOLD)
        schedule_cycles(controller, 10, 3)
    except KeyboardInterrupt:
        logging.info("Interrupted by user")
    except Exception as e:
        logging.error("Fatal error: %s", e)
        sys.exit(1)
    finally:
        if controller is not None:
            controller.close()


if __name__ == "__main__":
    main()

