import spidev
import RPi.GPIO as GPIO
import time
import signal
import sys

# --- Configuration ---
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1000000

SENSOR1_CHANNEL = 0
SENSOR2_CHANNEL = 1

SENSOR1_MIN_ADC = 300
SENSOR1_MAX_ADC = 700
SENSOR2_MIN_ADC = 350
SENSOR2_MAX_ADC = 750

MOISTURE_THRESHOLD = 30

BUZZER_PIN = 17
BUZZER_FREQUENCY = 440
BUZZER_DURATION = 2
BUZZER_DUTY_CYCLE = 50

# --- Globals for cleanup ---
spi = None
buzzer_pwm = None
running = True

def signal_handler(sig, frame):
    global running
    running = False

def initialize_spi():
    global spi
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = 0
        return True
    except Exception as e:
        print(f"Error initializing SPI: {e}")
        return False

def initialize_gpio():
    global buzzer_pwm
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(BUZZER_PIN, GPIO.OUT)
        buzzer_pwm = GPIO.PWM(BUZZER_PIN, BUZZER_FREQUENCY)
        buzzer_pwm.start(0)
        return True
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        return False

def read_adc(channel):
    if spi is None:
        return None
    try:
        cmd = 0b11 << 6 | (channel & 0x07) << 3
        resp = spi.xfer2([cmd, 0x00, 0x00])
        return ((resp[1] & 0x0F) << 8) | resp[2]
    except Exception as e:
        print(f"Error reading ADC channel {channel}: {e}")
        return None

def calculate_moisture_percentage(adc_value, sensor_min, sensor_max):
    if sensor_max == sensor_min:
        return 0.0
    percentage = 100.0 - ((adc_value - sensor_min) / (sensor_max - sensor_min)) * 100.0
    return max(0.0, min(100.0, percentage))

def check_moisture_levels():
    s1 = read_adc(SENSOR1_CHANNEL)
    s2 = read_adc(SENSOR2_CHANNEL)
    if s1 is None or s2 is None:
        return
    p1 = calculate_moisture_percentage(s1, SENSOR1_MIN_ADC, SENSOR1_MAX_ADC)
    p2 = calculate_moisture_percentage(s2, SENSOR2_MIN_ADC, SENSOR2_MAX_ADC)
    print(f"Sensor 1: {p1:.2f}%  Sensor 2: {p2:.2f}%")
    if p1 < MOISTURE_THRESHOLD or p2 < MOISTURE_THRESHOLD:
        print("Moisture level low! Activating buzzer.")
        sound_buzzer()

def sound_buzzer():
    if buzzer_pwm is None:
        return
    try:
        buzzer_pwm.ChangeDutyCycle(BUZZER_DUTY_CYCLE)
        time.sleep(BUZZER_DURATION / 2)
        buzzer_pwm.ChangeFrequency(BUZZER_FREQUENCY)
        time.sleep(BUZZER_DURATION / 2)
        buzzer_pwm.ChangeDutyCycle(0)
    except Exception as e:
        print(f"Error sounding buzzer: {e}")

def cleanup():
    global spi, buzzer_pwm
    if buzzer_pwm is not None:
        try:
            buzzer_pwm.stop()
        except Exception:
            pass
    if spi is not None:
        try:
            spi.close()
        except Exception:
            pass
    try:
        GPIO.cleanup()
    except Exception:
        pass

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    if not initialize_gpio():
        sys.exit(1)
    if not initialize_spi():
        cleanup()
        sys.exit(1)
    try:
        while running:
            check_moisture_levels()
            time.sleep(5)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

