import time
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Constants
I2C_BUS = 1
ADS1115_ADDRESS = 0x5C
GAIN = 1
READ_INTERVAL_SECONDS = 0.5
NUM_CHANNELS = 4


def initialize_i2c():
    """Initialize the I2C bus; return the bus object or None on failure."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Error initializing I2C bus: {exc}")
        return None


def initialize_adc(i2c_bus):
    """Initialize the ADS1115 ADC; return the ADS object or None on failure."""
    try:
        ads = ADS.ADS1115(i2c_bus, address=ADS1115_ADDRESS)
        ads.gain = GAIN
        return ads
    except Exception as exc:
        print(f"Error initializing ADS1115 at 0x{ADS1115_ADDRESS:02X}: {exc}")
        return None


def read_all_channels(ads):
    """Read all four ADC channels; return a list of AnalogIn objects or None."""
    channels = []
    for ch in range(NUM_CHANNELS):
        try:
            channels.append(AnalogIn(ads, ch))
        except Exception as exc:
            print(f"Error reading channel {ch}: {exc}")
            return None
    return channels


def print_channel_values(channels):
    """Print a formatted table of ADC values."""
    if channels is None or len(channels) != NUM_CHANNELS:
        print("Error: could not read all channels.")
        return

    print("| {0:>6} | {1:>6} | {2:>6} | {3:>6} |".format(*range(NUM_CHANNELS)))
    print("-" * 37)

    for i, ch in enumerate(channels):
        try:
            value = ch.value
        except Exception as exc:
            print(f"  Channel {i}: read error ({exc})")
            continue
        print("| {0:>6} |".format(value))


def main():
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    ads = initialize_adc(i2c_bus)
    if ads is None:
        return

    try:
        while True:
            channel_values = read_all_channels(ads)
            print_channel_values(channel_values)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    finally:
        print("Exiting gracefully.")


if __name__ == "__main__":
    main()

