def read_sensor_voltage(spi, channel):
    try:
        # MCP3008 single-ended read: start bit + single/diff + channel[2:0]
        adc = spi.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        voltage = data * (REFERENCE_VOLTAGE / 1023.0)
        return voltage
    except IOError as e:
        print(f"SPI I/O error reading channel {channel}: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error reading channel {channel}: {e}")
        return None

def log_data(log_file, timestamp, mq2_voltage, mq7_voltage, mq135_voltage):
    try:
        log_entry = f"{timestamp},{mq2_voltage:.3f},{mq7_voltage:.3f},{mq135_voltage:.3f}\n"
        with open(log_file, "a") as f:
            f.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file: {e}")

def control_actuator(actuator_pin, mq2_critical, mq7_critical, mq135_critical, mq2_voltage, mq7_voltage, mq135_voltage):
    try:
        if mq2_critical and mq2_voltage is not None and mq2_voltage > mq2_critical:
            print("MQ-2 Critical Level! Activating actuator.")
            os.system(f"sudo gpio {actuator_pin} on")
        elif mq7_critical and mq7_voltage is not None and mq7_voltage > mq7_critical:
            print("MQ-7 Critical Level! Activating actuator.")
            os.system(f"sudo gpio {actuator_pin} on")
        elif mq135_critical and mq135_voltage is not None and mq135_voltage > mq135_critical:
            print("MQ-135 Critical Level! Activating actuator.")
            os.system(f"sudo gpio {actuator_pin} on")
        else:
            os.system(f"sudo gpio {actuator_pin} off")
    except Exception as e:
        print(f"Error controlling actuator: {e}")

def main():
    global spi
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config(CONFIG_FILE)

    mq2_channel = config.get("mq2_channel", 0)
    mq7_channel = config.get("mq7_channel", 1)
    mq135_channel = config.get("mq135_channel", 2)

    mq2_warning = config.get("mq2_warning", 0.5)
    mq2_critical = config.get("mq2_critical", 1.0)
    mq7_warning = config.get("mq7_warning", 0.5)
    mq7_critical = config.get("mq7_critical", 1.0)
    mq135_warning = config.get("mq135_warning", 0.5)
    mq135_critical = config.get("mq135_critical", 1.0)

    actuator_pin = config.get("actuator_pin", 17)

    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
    except IOError as e:
        print(f"Error initializing SPI: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing SPI: {e}")
        sys.exit(1)

    try:
        while running:
            timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")

            mq2_voltage = read_sensor_voltage(spi, mq2_channel)
            mq7_voltage = read_sensor_voltage(spi, mq7_channel)
            mq135_voltage = read_sensor_voltage(spi, mq135_channel)

            if mq2_voltage is not None:
                if mq2_voltage > mq2_critical:
                    print("MQ-2 Critical Level!")
                elif mq2_voltage > mq2_warning:
                    print("MQ-2 Warning Level!")

            if mq7_voltage is not None:
                if mq7_voltage > mq7_critical:
                    print("MQ-7 Critical Level!")
                elif mq7_voltage > mq7_warning:
                    print("MQ-7 Warning Level!")

            if mq135_voltage is not None:
                if mq135_voltage > mq135_critical:
                    print("MQ-135 Critical Level!")
                elif mq135_voltage > mq135_warning:
                    print("MQ-135 Warning Level!")

            log_data(LOG_FILE, timestamp, mq2_voltage, mq7_voltage, mq135_voltage)

            control_actuator(actuator_pin, mq2_critical, mq7_critical, mq135_critical, mq2_voltage, mq7_voltage, mq135_voltage)

            time.sleep(5)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if spi is not None:
            try:
                spi.close()
            except Exception:
                pass
        try:
            os.system(f"sudo gpio {actuator_pin} off")
        except Exception:
            pass
        print("Resources cleaned up. Exiting.")

if __name__ == "__main__":
    main()

