            if not ret:
                logging.error("Failed to grab frame.")
                time.sleep(0.1)
                continue

            try:
                processed_frame = preprocess_frame(frame)
            except Exception as e:
                logging.error(f"Error preprocessing frame: {e}")
                time.sleep(0.1)
                continue

            detections = run_detection(detection_model, processed_frame)

            if detections:
                logging.info(f"Detected {len(detections)} bird(s).")
                indicate_bird(led_pin)

                if door_control and door_device is not None:
                    control_door(door_device, "open")

            time.sleep(0.1)

    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        logging.info("Releasing resources...")
        if camera is not None:
            camera.release()
        if door_device is not None:
            door_device.close()
        GPIO.cleanup()
        logging.info("Cleanup complete.")


if __name__ == "__main__":
    main()

