import io
import time
import json
import signal
import sys
import threading
import queue
import logging
import argparse

try:
    from picamera2 import Picamera2
    from picamera2.encoders import MJPEGEncoder
    from picamera2.outputs import FileOutput
except ImportError:
    print("Error: picamera2 library is not installed. Install with: pip install picamera2")
    sys.exit(1)

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO library is not installed. Install with: pip install RPi.GPIO")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class CameraHandler:
    def __init__(self, config):
        self.config = config
        self.camera = None
        self.frame_queue = queue.Queue(maxsize=config.get('max_queue_size', 10))
        self.running = False
        self.motion_detected = False
        self.timer = None
        self.gpio_pin = config.get('gpio_pin', None)
        self.led_on = False
        self.led_duration = config.get('led_duration', 2)
        self.motion_threshold = config.get('motion_threshold', 25)

    def initialize_camera(self):
        try:
            self.camera = Picamera2()
            width = self.config.get('resolution_width', 640)
            height = self.config.get('resolution_height', 480)
            framerate = self.config.get('framerate', 30)
            self.camera.configure(self.camera.create_video_configuration(
                main={"size": (width, height)},
                controls={"FrameRate": framerate}
            ))
            self.camera.start()
            time.sleep(self.config.get('warmup_time', 2))
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            raise

    def capture_and_encode_frame(self):
        try:
            frame = self.camera.capture_array()
            if frame is None:
                logging.warning("Captured frame is None.")
                return None
            stream = io.BytesIO()
            from PIL import Image
            Image.fromarray(frame).save(stream, format='JPEG')
            stream.seek(0)
            return stream
        except Exception as e:
            logging.error(f"Error capturing or encoding frame: {e}")
            return None

    def detect_motion(self, frame_stream):
        try:
            from PIL import Image
            img = Image.open(frame_stream)
            width, height = img.size
            pixels = list(img.getdata())
            total_change = sum(sum(abs(p1 - p2) for p1, p2 in zip(row1, row2)) for row1, row2 in zip(pixels, pixels[width - 1:]))
            avg_change = total_change / (width * height)
            return avg_change > self.motion_threshold
        except Exception as e:
            logging.error(f"Error detecting motion: {e}")
            return False

    def trigger_alert(self):
        if self.gpio_pin is None:
            logging.info("No GPIO pin configured for alert.")
            return
        try:
            GPIO.output(self.gpio_pin, GPIO.HIGH)
            self.led_on = True
            logging.info("Alert triggered: LED activated.")
            if self.timer:
                self.timer.cancel()
            self.timer = threading.Timer(self.led_duration, self.deactivate_led)
            self.timer.daemon = True
            self.timer.start()
        except Exception as e:
            logging.error(f"Error triggering alert: {e}")

    def deactivate_led(self):
        if self.gpio_pin is None:
            return
        try:
            GPIO.output(self.gpio_pin, GPIO.LOW)
            self.led_on = False
            logging.info("Alert triggered: LED deactivated.")
        except Exception as e:
            logging.error(f"Error deactivating LED: {e}")

    def run(self):
        try:
            self.initialize_camera()
            self.running = True
            while self.running:
                frame_stream = self.capture_and_encode_frame()
                if frame_stream is None:
                    time.sleep(0.1)
                    continue
                if not self.frame_queue.full():
                    self.frame_queue.put(frame_stream)
                if not self.motion_detected:
                    if self.detect_motion(frame_stream):
                        self.motion_detected = True
                        self.trigger_alert()
                time.sleep(0.1)
        except Exception as e:
            logging.error(f"Error in main loop: {e}")
        finally:
            self.cleanup()

    def cleanup(self):
        self.running = False
        if self.timer:
            self.timer.cancel()
        if self.camera:
            try:
                self.camera.stop()
            except Exception as e:
                logging.error(f"Error stopping camera: {e}")
        if self.gpio_pin is not None:
            try:
                GPIO.cleanup(self.gpio_pin)
                logging.info("GPIO cleaned up.")
            except Exception as e:
                logging.error(f"Error cleaning up GPIO: {e}")

def signal_handler(sig, frame):
    logging.info("Interrupt received, shutting down...")
    if hasattr(signal_handler, 'camera_handler'):
        signal_handler.camera_handler.cleanup()
    sys.exit(0)

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Raspberry Pi Camera Motion Detection with LED Alert")
    parser.add_argument("--config", type=str, default="config.json", help="Path to the configuration file")
    args = parser.parse_args()

    try:
        with open(args.config, 'r') as f:
            config = json.load(f)
    except FileNotFoundError:
        print(f"Error: Configuration file not found: {args.config}")
        sys.exit(1)
    except json.JSONDecodeError:
        print(f"Error: Invalid JSON format in configuration file: {args.config}")
        sys.exit(1)

    signal_handler.camera_handler = CameraHandler(config)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    CameraHandler(config).run()

