import signal
import sys
import threading
import time
from pathlib import Path

import cv2
import numpy as np
import torch

try:
    from models.common import DetectMultiBackend
    from utils.dataloaders import LoadImages, LoadStreams
    from utils.general import (LOGGER, Profile, check_img_size, non_max_suppression, print_args, scale_boxes)
    from utils.plots import Annotator, colors
    from utils.torch_utils import select_device, smart_inference_mode
except ImportError as e:
    print(f"Error importing YOLOv5 modules: {e}", file=sys.stderr)
    sys.exit(1)

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("RPi.GPIO not found. Install with: pip install RPi.GPIO", file=sys.stderr)
    sys.exit(1)

try:
    import smbus2
except ImportError:
    print("smbus2 not found. Install with: pip install smbus2", file=sys.stderr)
    sys.exit(1)

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
LED_PINS = {
    0: 17,   # person
    2: 18,   # car
    3: 23,   # motorcycle
    5: 27,   # bus
    7: 22,   # truck
}

I2C_BUS = 1
LCD_ADDR = 0x3F
LCD_WIDTH = 16
LCD_CHR = 1
LCD_CMD = 0
LCD_LINE_1 = 0x80
LCD_LINE_2 = 0xC0
LCD_BACKLIGHT = 0x08
ENABLE = 0x04

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
_running = True
_lock = threading.Lock()
_lcd_bus = None
_lcd_display = False


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _lcd_bus, _lcd_display
    try:
        if _lcd_display:
            try:
                lcd_write_string("System Off", LCD_LINE_1)
            except Exception:
                pass
            _lcd_display = False
    except Exception:
        pass
    try:
        for pin in LED_PINS.values():
            GPIO.output(pin, GPIO.LOW)
    except Exception:
        pass
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if _lcd_bus is not None:
        try:
            _lcd_bus.close()
        except Exception:
            pass


def _lcd_init():
    global _lcd_bus, _lcd_display
    try:
        _lcd_bus = smbus2.SMBus(I2C_BUS)
    except Exception as e:
        LOGGER.error(f"Failed to open I2C bus {I2C_BUS}: {e}")
        return False
    try:
        _lcd_bus.write_byte(LCD_ADDR, 0x03 << 4)
        time.sleep(0.005)
        _lcd_bus.write_byte(LCD_ADDR, 0x03 << 4 | 0x01)
        time.sleep(0.0002)
        _lcd_bus.write_byte(LCD_ADDR, 0x03 << 4 | 0x02)
        time.sleep(0.0002)
        _lcd_bus.write_byte(LCD_ADDR, 0x28)  # 4-bit, 2-line, 5x8 font
        _lcd_bus.write_byte(LCD_ADDR, 0x0C)  # display on, cursor off
        _lcd_bus.write_byte(LCD_ADDR, 0x06)  # entry mode
        _lcd_bus.write_byte(LCD_ADDR, 0x01)  # clear
        time.sleep(0.002)
        _lcd_display = True
        return True
    except Exception as e:
        LOGGER.error(f"LCD init failed: {e}")
        _lcd_bus = None
        return False


def lcd_write_string(message, line):
    if not _lcd_bus or not _lcd_display:
        return
    try:
        _lcd_bus.write_byte(LCD_ADDR, line)
        msg = message.ljust(LCD_WIDTH, " ")[:LCD_WIDTH]
        for ch in msg:
            _lcd_bus.write_byte(LCD_ADDR, ord(ch) | LCD_BACKLIGHT)
            _lcd_bus.write_byte(LCD_ADDR, ord(ch) | LCD_BACKLIGHT | ENABLE)
            time.sleep(0.0001)
            _lcd_bus.write_byte(LCD_ADDR, ord(ch) | LCD_BACKLIGHT & ~ENABLE)
            time.sleep(0.0001)
    except Exception as e:
        LOGGER.error(f"LCD write failed: {e}")
        _lcd_display = False


def _set_led(cls_id):
    pin = LED_PINS.get(cls_id)
    if pin is None:
        return
    try:
        GPIO.output(pin, GPIO.HIGH)
    except Exception as e:
        LOGGER.error(f"Failed to set LED on pin {pin}: {e}")


def _clear_led(cls_id):
    pin = LED_PINS.get(cls_id)
    if pin is None:
        return
    try:
        GPIO.output(pin, GPIO.LOW)
    except Exception as e:
        LOGGER.error(f"Failed to clear LED on pin {pin}: {e}")


def _process_detections(det, names, im, im0, s, dt):
    for *xyxy, conf, cls in det:
        c = int(cls)
        label = names[c]
        annotator = Annotator(im0, line_width=3, example=str(names))
        if label in ("person", "bus", "truck", "car", "motorcycle"):
            _set_led(c)
        elif label == "person":
            time.sleep(1)
            _clear_led(0)
        elif label == "car":
            time.sleep(1)
            _clear_led(2)
        elif label == "motorcycle":
            time.sleep(1)
            _clear_led(3)
        elif label == "bus":
            time.sleep(1)
            _clear_led(5)
        elif label == "truck":
            time.sleep(1)
            _clear_led(7)
        annotator.box_label(xyxy, label, color=colors(c, True))
        im0.append(annotator.result())


def _lcd_loop():
    while _running:
        try:
            if _lcd_display:
                stats = {
                    "CPU": f"{round(s.cpu_time * 1000):.1f}ms",
                    "INFER": f"{round(s.inference_time * 1000):.1f}ms",
                    "FPS": round(s.get_fps(), 2),
                }
                lcd_write_string(f"FPS:{stats['FPS']:.1f}", LCD_LINE_1)
                lcd_write_string(f"CPU:{stats['CPU']} INFER:{stats['INFER']}", LCD_LINE_2)
            else:
                time.sleep(1)
        except Exception as e:
            LOGGER.error(f"LCD loop error: {e}")
            _lcd_display = False
            time.sleep(1)


@smart_inference_mode()
def run(weights, source, imgsz=(640, 640), conf_thres=0.25, iou_thres=0.45, max_det=1000, device=""):
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        GPIO.setwarnings(False)
        GPIO.setmode(GPIO.BCM)
        for pin in LED_PINS.values():
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        LOGGER.error(f"GPIO init failed: {e}")
        return

    if not _lcd_init():
        LOGGER.warning("LCD not available; continuing without LCD display.")

    try:
        device = select_device(device)
        model = DetectMultiBackend(weights, device=device)
        stride, names, pt = model.stride, model.names, model.pt
        imgsz = check_img_size(imgsz, s=stride)
    except Exception as e:
        LOGGER.error(f"Failed to load model: {e}")
        _cleanup()
        return

    dataset = LoadStreams(source, img_size=imgsz, stride=stride, auto=pt)
    bs = len(dataset)
    seen, windows, dt = 0, [], Profile()

    try:
        model.warmup(imgsz=(1 if pt else bs, 3, *imgsz))
        for path, im, im0s, vid_cap, s in dataset:
            with dt:
                im = torch.from_numpy(im).to(model.device)
                im = im.half() if model.fp16 else im.float()
                im /= 255
                if len(im.shape) == 3:
                    im = im[None]
                pred = model(im, augment=False, visualize=False)
                pred = non_max_suppression(pred, conf_thres, iou_thres, None, False, max_det=max_det)

                for det in pred:
                    seen += 1
                    _process_detections(det, names, im, im0s, s, dt)

    except KeyboardInterrupt:
        _running = False
    except Exception as e:
        LOGGER.error(f"Inference error: {e}")
    finally:
        _cleanup()


if __name__ == "__main__":
    weights = "yolov5s.pt"
    source = 0
    run(weights, source)

