#!/usr/bin/env python3
"""
Wildlife Tracking Sensor Data Logger

Reads BMP280, BME280, and MS8607 sensors on I2C bus 1, validates data,
stores it in SQLite, and logs errors to file.

Configuration file (config.txt):
    Sensor1_Type/Address/ID,Sensor2_Type/Address/ID,Sensor3_Type/Address/ID
    Sampling_Interval_Seconds (default 60, only applicable to MS8607 and used for BMP280/BME280)

Example:
    Sensor1_BMP280_0x76_1,Sensor2_BME280_0x77_2,Sensor3_MS8607_0x78_3
    Sampling_Interval_Seconds=30
"""

import os
import sys
import time
import signal
import sqlite3
import logging
from datetime import datetime

# --- Optional imports (graceful degradation if unavailable) ---
try:
    import smbus2 as smbus
except ImportError:
    smbus = None

try:
    from adafruit_bmp280 import BMP280
except ImportError:
    BMP280 = None

try:
    from adafruit_bme280 import basic as adafruit_bme280
except ImportError:
    adafruit_bme280 = None

try:
    from adafruit_ms8607 import MS8607
except ImportError:
    MS8607 = None

# --- Configuration ---
CONFIG_FILE = "config.txt"
DATABASE_FILE = "wildlife_data.db"
ERROR_LOG_FILE = "error.log"

# --- Logging setup ---
logging.basicConfig(
    filename=ERROR_LOG_FILE,
    level=logging.ERROR,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

# --- Global state for signal handling ---
_running = True
_db_connection = None


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _log_error(message):
    """Log an error message with timestamp."""
    logging.error(message)


def _create_database():
    """Create the SQLite database and sensor_data table if they don't exist."""
    global _db_connection
    try:
        _db_connection = sqlite3.connect(DATABASE_FILE)
        cursor = _db_connection.cursor()
        cursor.execute(
            """
            CREATE TABLE IF NOT EXISTS sensor_data (
                timestamp TEXT,
                sensor_type TEXT,
                sensor_id INTEGER,
                pressure_pa REAL,
                temperature_c REAL,
                humidity_percent REAL
            )
            """
        )
        _db_connection.commit()
    except sqlite3.Error as e:
        _log_error(f"Database creation error: {e}")
        raise


def _read_config():
    """Read configuration from config.txt and return a dict of sensor settings."""
    config = {}
    try:
        with open(CONFIG_FILE, "r") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if "=" not in line:
                    _log_error(f"Malformed line in config.txt: {line!r}")
                    continue
                key, value = line.split("=", 1)
                config[key.strip()] = value.strip()
    except FileNotFoundError:
        _log_error(f"Configuration file not found: {CONFIG_FILE}")
    except PermissionError:
        _log_error(f"Permission denied reading config file: {CONFIG_FILE}")
    except OSError as e:
        _log_error(f"Error reading config file: {e}")
    return config


def _initialize_sensors(config):
    """Initialize sensors based on config.

    Returns a dict mapping sensor_id to sensor object.
    """
    sensors = {}
    # BMP280
    if "BMP280" in config:
        parts = config["BMP280"].split(",")
        if len(parts) != 3:
            _log_error(f"BMP280 config must be 'Sensor_Type/Address/ID', got: {config['BMP280']}")
            return sensors
        sensor_type, address_hex, sensor_id = parts
        try:
            i2c_bus = smbus.SMBus(1)
            sensor = BMP280(i2c_bus, address=int(address_hex, 16))
            sensor.sea_level_pressure = 1013.25
            sensors[int(sensor_id)] = sensor
        except Exception as e:
            _log_error(f"BMP280 init failed for sensor {sensor_id}: {e}")
    # BME280
    if "BME280" in config:
        parts = config["BME280"].split(",")
        if len(parts) != 3:
            _log_error(f"BME280 config must be 'Sensor_Type/Address/ID', got: {config['BME280']}")
            return sensors
        sensor_type, address_hex, sensor_id = parts
        try:
            i2c_bus = smbus.SMBus(1)
            sensor = adafruit_bme280.Adafruit_BME280_I2C(i2c_bus, address=int(address_hex, 16))
            sensor.sea_level_pressure = 1013.25
            sensors[int(sensor_id)] = sensor
        except Exception as e:
            _log_error(f"BME280 init failed for sensor {sensor_id}: {e}")
    # MS8607
    if "MS8607" in config:
        parts = config["MS8607"].split(",")
        if len(parts) != 3:
            _log_error(f"MS8607 config must be 'Sensor_Type/Address/ID', got: {config['MS8607']}")
            return sensors
        sensor_type, address_hex, sensor_id = parts
        try:
            i2c_bus = smbus.SMBus(1)
            sensor = MS8607(i2c_bus, address=int(address_hex, 16))
            sensors[int(sensor_id)] = sensor
        except Exception as e:
            _log_error(f"MS8607 init failed for sensor {sensor_id}: {e}")
    return sensors


def _read_sensor_data(sensor_id, sensor_type, sensor_obj):
    """Read data from a sensor and return a dict with pressure, temperature, humidity."""
    data = {}
    try:
        if sensor_type == "BMP280":
            data["pressure_pa"] = sensor_obj.pressure
            data["temperature_c"] = sensor_obj.temperature
        elif sensor_type == "BME280":
            data["pressure_pa"] = sensor_obj.pressure
            data["temperature_c"] = sensor_obj.temperature
            data["humidity_percent"] = sensor_obj.humidity
        elif sensor_type == "MS8607":
            data["pressure_pa"] = sensor_obj.pressure
            data["temperature_c"] = sensor_obj.temperature
            data["humidity_percent"] = sensor_obj.relative_humidity
        else:
            _log_error(f"Unknown sensor type: {sensor_type}")
            return None
    except Exception as e:
        _log_error(f"Error reading sensor {sensor_id} ({sensor_type}): {e}")
        return None

    # Data validation
    if data["pressure_pa"] is None:
        _log_error(f"Invalid pressure reading from sensor {sensor_id}.")
        return None
    if not (70000 <= data["pressure_pa"] <= 110000):
        _log_error(f"Pressure out of range for sensor {sensor_id}: {data['pressure_pa']} Pa")
        return None
    if data["temperature_c"] is None:
        _log_error(f"Invalid temperature reading from sensor {sensor_id}.")
        return None
    if not (-20 <= data["temperature_c"] <= 50):
