import smbus
import time
import signal
import sys
import random

# Constants
I2C_BUS = 1
AMG8833_ADDR = 0x54
AMG8833_PIXEL_REG = 0x80
AMG8833_PCTL_REG = 0x00
AMG8833_TEMP_SCALE = 0.02

# GPIO pin for the buzzer
BUZZER_PIN = 17

# Global resources for cleanup
buzzer = None
i2c_bus = None
running = True


def cleanup(signum=None, frame=None):
    """Release resources and exit cleanly."""
    global running, buzzer, i2c_bus
    running = False
    if buzzer is not None:
        try:
            buzzer.close()
        except Exception:
            pass
        buzzer = None
    if i2c_bus is not None:
        try:
            i2c_bus.close()
        except Exception:
            pass
        i2c_bus = None
    if signum is not None:
        sys.exit(0)


def trigger_alert(buzz):
    """Activate the buzzer for 1 second."""
    try:
        buzz.on()
        time.sleep(1)
    except Exception as e:
        print(f"Error triggering alert: {e}")
    finally:
        try:
            buzz.off()
        except Exception:
            pass


def detect_human(thermal_data):
    """Return True if any pixel exceeds 30°C."""
    if thermal_data is None or len(thermal_data) != 64:
        return False
    for temp in thermal_data:
        if temp > 30:
            return True
    return False


def simulate_thermal_data():
    """Generate simulated 8x8 thermal data between 20°C and 45°C."""
    return [random.uniform(20, 45) for _ in range(64)]


def main():
    global buzzer, i2c_bus

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize buzzer
    try:
        buzzer = smbus.SMBus(BUZZER_PIN).get_device()
    except Exception as e:
        print(f"Failed to initialize buzzer on GPIO{BUZZER_PIN}: {e}")
        sys.exit(1)

    # Initialize I2C bus for AMG8833
    try:
        i2c_bus = smbus.SMBus(I2C_BUS)
    except Exception as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}")
        cleanup()
        sys.exit(1)

    # Configure AMG8833: set pixel clock to 100 kHz, disable shutter
    try:
        i2c_bus.write_byte_data(AMG8833_ADDR, AMG8833_PCTL_REG, 0x00)
    except Exception as e:
        print(f"Failed to configure AMG8833: {e}")
        cleanup()
        sys.exit(1)

    print("AMG8833 thermal camera monitoring started. Press Ctrl+C to exit.")

    while running:
        try:
            # Read 64 pixel temperatures from AMG8833
            raw_data = i2c_bus.read_i2c_block_data(AMG8833_ADDR, AMG8833_PIXEL_REG, 64)
            thermal_data = [(raw_data[i] << 8) | raw_data[i + 1] for i in range(0, 64, 2)]

            # Convert raw values to Celsius
            thermal_data_c = [(t * AMG8833_TEMP_SCALE) - 273.15 for t in thermal_data]

            # Check for human presence
            if detect_human(thermal_data_c):
                print("Human detected!")
                trigger_alert(buzzer)
            else:
                print("No human detected.")

        except OSError as e:
            # I2C communication error (sensor disconnected, bus error, etc.)
            print(f"I2C communication error: {e}. Switching to simulation mode.")
            thermal_data = simulate_thermal_data()
            # Still check for humans in the simulated data
            if detect_human(thermal_data):
                print("Simulated human detected!")
                trigger_alert(buzzer)
            else:
                print("No simulated human detected.")
        except Exception as e:
            print(f"Unexpected error reading sensor: {e}")
            thermal_data = simulate_thermal_data()
            if detect_human(thermal_data):
                print("Simulated human detected due to error!")
                trigger_alert(buzzer)
            else:
                print("No human detected due to error.")

        time.sleep(0.1)

    cleanup()


if __name__ == "__main__":
    main()

