try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO can only run on a Raspberry Pi.", file=sys.stderr)
    sys.exit(1)

I2C_BUS = 1
PCF8574_ADDR = 0x42
INT_PIN = 17
DEBOUNCE_MS = 50
POLL_INTERVAL_S = 1.0

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    GPIO.remove_event_detect(INT_PIN)
    GPIO.cleanup()


def _read_pcf8574():
    """Read a single byte from the PCF8574; return None on I2C error."""
    try:
        return GPIO.i2c_read_byte(I2C_BUS, PCF8574_ADDR)
    except Exception as exc:
        print(f"Error: I2C read from PCF8574 failed: {exc}", file=sys.stderr)
        return None


def _handle_interrupt(channel):
    """Falling-edge ISR: debounce then report any active-low sensor."""
    time.sleep(DEBOUNCE_MS / 1000.0)
    data = _read_pcf8574()
    if data is None:
        return
    for n in range(8):
        if (data >> n) & 0x01:
            print(f"Obstacle detected by sensor {n}")


def main():
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(INT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    GPIO.add_event_detect(INT_PIN, GPIO.FALLING, callback=_handle_interrupt)

    print("PCF8574 proximity sensor monitor started. Press Ctrl+C to exit.")

    try:
        while _running:
            time.sleep(POLL_INTERVAL_S)
    except KeyboardInterrupt:
        pass
    finally:
        _cleanup()
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

