import os
import time
import signal
import logging
import configparser
import datetime
import threading
from pathlib import Path

import numpy as np
import cv2

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

DEFAULT_CONFIG = {
    'storage_directory': '/home/pi/storage',
    'disk_space_threshold_mb': '1024',
    'log_file': './logs/motion_detection.log',
}


class MotionDetector:
    def __init__(self, pin=4):
        self.pin = pin
        if GPIO is not None:
            try:
                GPIO.setmode(GPIO.BCM)
                GPIO.setup(self.pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            except Exception as e:
                logging.error(f"GPIO setup failed: {e}")
                raise
        else:
            logging.warning("RPi.GPIO not available; running without GPIO-triggered capture.")

    def detect(self):
        if GPIO is not None:
            try:
                return GPIO.input(self.pin) == GPIO.HIGH
            except Exception as e:
                logging.error(f"PIR read error: {e}")
                return False
        return False


class CameraHandler:
    def __init__(self):
        self.camera = None
        self.picam2 = None
        if Picamera2 is None:
            logging.error("picamera2 module not available.")
            return
        try:
            self.picam2 = Picamera2()
            self.picam2.configure(
                self.picam2.create_video_configuration(
                    main={"size": (640, 480), "format": "RGB888"},
                    controls={"FrameRate": 20},
                )
            )
            self.picam2.start()
            logging.info("Picamera2 initialized successfully.")
        except Exception as e:
            logging.error(f"Picamera2 initialization failed: {e}")
            self.picam2 = None

    def capture_image(self, quality=85, bitrate=64):
        if self.camera is None and self.picam2 is None:
            logging.warning("Camera not available; skipping image capture.")
            return None
        try:
            if self.camera is not None:
                filename = self.camera.capture_image()
                if filename:
                    logging.info(f"Captured image: {filename}")
                    return filename
            if self.picam2 is not None:
                timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
                filename = f"{timestamp}.jpg"
                self.picam2.capture_file(filename, format="jpeg", quality=quality)
                logging.info(f"Captured image: {filename}")
                return filename
            return None
        except Exception as e:
            logging.error(f"Image capture failed: {e}")
            return None

    def capture_video(self, duration=5, bitrate=64):
        if self.camera is None and self.picam2 is None:
            logging.warning("Camera not available; skipping video capture.")
            return None
        try:
            if self.camera is not None:
                filename = self.camera.capture_video(duration=duration)
                if filename:
                    logging.info(f"Captured video: {filename}")
                    return filename
            if self.picam2 is not None:
                timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
                filename = f"{timestamp}.h264"
                self.picam2.start_recording(filename, format="h264", bitrate=bitrate)
                time.sleep(duration)
                self.picam2.stop_recording()
                logging.info(f"Captured video: {filename}")
                return filename
            return None
        except Exception as e:
            logging.error(f"Video capture failed: {e}")
            return None

    def close(self):
        if self.picam2 is not None:
            try:
                self.picam2.stop()
            except Exception:
                pass
            try:
                self.picam2.close()
            except Exception:
                pass
            self.picam2 = None
        if self.camera is not None:
            try:
                self.camera.close()
            except Exception:
                pass
            self.camera = None


class DiskSpaceManager:
    def __init__(self, threshold_mb, storage_directory):
        self.threshold_mb = threshold_mb
        self.storage_directory = storage_directory
        self.lock = threading.Lock()

    def get_available_space_mb(self):
        try:
            statvfs = os.statvfs(self.storage_directory)
            return (statvfs.f_bavail * statvfs.f_frsize) / (1024 * 1024)
        except Exception as e:
            logging.error(f"Error getting available space: {e}")
            return 0

    def manage_disk_space(self):
        try:
            with self.lock:
                available = self.get_available_space_mb()
                if available < self.threshold_mb:
                    logging.warning(f"Disk space low ({available:.1f} MB < {self.threshold_mb} MB). Deleting old files.")
                    files = self._list_files()
                    if not files:
                        logging.warning("No files found to delete.")
                        return
                    files.sort(key=lambda f: f.stat().st_mtime)
                    for f in files:
                        try:
                            f.remove()
                            logging.info(f"Deleted old file: {f}")
                            available = self.get_available_space_mb()
                            if available >= self.threshold_mb:
                                logging.info("Disk space managed.")
                                return
                        except Exception as e:
                            logging.error(f"Error deleting file {f}: {e}")
                    logging.error("Failed to free up disk space.")
        except Exception as e:
            logging.error(f"Disk space management error: {e}")

    def _list_files(self):
        try:
            return [Path(self.storage_directory) / f for f in os.listdir(self.storage_directory) if f.isfile()]
        except Exception as e:
            logging.error(f"Error listing files: {e}")
            return []


def setup_logging(log_file):
    log_dir = Path(log_file).parent
    try:
        os.makedirs(log_dir, exist_ok=True)
    except Exception as e:
        print(f"Warning: cannot create log directory {log_dir}: {e}. Falling back to ./logs.")
        log_dir = Path("./logs")
    try:
        handler = logging.FileHandler(log_file)
    except Exception as e:
        print(f"Warning: cannot open log file {log_file}: {e}. Falling back to ./logs.")
        handler = logging.FileHandler(str(log_dir / "motion_detection.log"))
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
        handlers=[handler],
    )
    logging.info("Logging initialized.")


def load_config(config_file):
    config = configparser.ConfigParser()
    if not config.read(config_file):
        logging.warning(f"Config file {config_file} not found. Creating with defaults.")
        config["DEFAULT"] = DEFAULT_CONFIG
        try:
            with open(config_file, "w") as f:
                config.write(f)
        except Exception as e:
            logging.error(f"Could not write default config: {e}")
    return config["DEFAULT"]


def main():
    config = load_config("config.ini")
    setup_logging(config.get("log_file", DEFAULT_CONFIG["log_file"]))
    logging.info("Motion detection system starting.")

    storage_directory = config.get("storage_directory", DEFAULT_CONFIG["storage_directory"])
    disk_space_threshold_mb = config.getint("disk_space_threshold_mb", DEFAULT_CONFIG["disk_space_threshold_mb"])

    try:
        motion_detector = MotionDetector(pin=4)
    except Exception as e:
        logging.error(f"Failed to initialize motion detector: {e}")
        return

    camera_handler = CameraHandler()
    disk_space_manager = DiskSpaceManager(disk_space_threshold_mb, storage_directory)

    def signal_handler(signum, frame):
        logging.info(f"Signal {signum} received. Shutting down.")
        camera_handler.close()
        if GPIO is not None:
            GPIO.cleanup()
        exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            if motion_detector.detect():
                logging.info("Motion detected!")
                time.sleep(2)
                for _ in range(3):
                    camera_handler.capture_image()
                    time.sleep(0.5)
                camera_handler.capture_video()
                disk_space_manager.manage_disk_space()
            else:
                time.sleep(0.1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        camera_handler.close()
        if GPIO is not None:
            GPIO.cleanup()
        logging.info("System shutdown complete.")


if __name__ == "__main__":
    main()

