      {% endfor %}
    </select><br>
    <label><b>Live Preview:</b></label>
    <select name="live_preview">
      <option value="true" {% if live_preview == true %}selected{% endif %}>True</option>
      <option value="false" {% if live_preview == false %}selected{% endif %}>False</option>
    </select><br>
    <label><b>Email Notifications:</b></label>
    <select name="email_notifications">
      <option value="true" {% if email_notifications == true %}selected{% endif %}>True</option>
      <option value="false" {% if email_notifications == false %}selected{% endif %}>False</option>
    </select><br>
    <label><b>Recipient:</b></label>
    <input type="text" name="recipient" value="{{ recipient }}" /><br>
    <label><b>Interval:</b></label>
    <input type="number" name="interval" value="{{ interval }}" /><br>
    <input type="submit" value="Submit" />
  </form>
</body>
</html>"""

_camera: Optional[Camera] = None
_classifier: Optional[Classifier] = None
_stop_event = threading.Event()


def init_camera() -> Camera:
    """Initialize the camera and return the wrapped Camera instance."""
    cam = Camera()
    try:
        cam.vs.start()
    except Exception as exc:
        logger.error("Failed to start camera video stream: %s", exc)
        raise
    return cam


def init_classifier(classifier_name: str) -> Classifier:
    """Initialize the chosen classifier."""
    if classifier_name == "motion_detector":
        return Classifier("motion_detector")
    return Classifier(classifier_name)


def detect_object(found_obj: bool, frame: np.ndarray, last_epoch: float, camera_id: str = "Cam1") -> float:
    """Detect an object and return the updated last_epoch timestamp."""
    if found_obj and (time.time() - last_epoch) > 3:
        logger.info("Detected object: %s", camera_id)
        return time.time()
    return last_epoch


def check_for_objects(cam: Camera, classifier: Classifier, recipient: str, interval: float, last_epoch: float) -> None:
    """Continuously check for objects and send email notifications."""
    logger.info("Starting background object detection loop...")
    while not _stop_event.is_set():
        if classifier.name == "motion_detector":
            found, frame = cam.get_object_with_basic_motion_detection()
        else:
            found, frame = cam.get_object(classifier)

        if found:
            last_epoch = detect_object(found, frame, last_epoch, camera_id="Cam1")
            if classifier.name == "mail_sender" and recipient and interval > 0:
                try:
                    send_email(frame, recipient)
                    logger.info("Email sent to %s", recipient)
                except Exception as exc:
                    logger.error("Failed to send email: %s", exc)
        else:
            logger.debug("No object detected.")

        # Sleep in small increments so we can exit promptly if a stop is requested
        _stop_event.wait(timeout=interval)

    logger.info("Object detection loop stopped.")


def gen(cam: Camera) -> None:
    """Generate frames for the video feed."""
    while not _stop_event.is_set():
        try:
            if _classifier and _classifier.name == "motion_detector":
                found, frame = cam.get_object_with_basic_motion_detection()
            else:
                found, frame = cam.get_object(_classifier)

            if found:
                logger.info("Frame acquired with detection: %s", type(frame))
            else:
                logger.debug("Frame acquired without detection: %s", type(frame))

            yield (b'--frame\r\n'
                   b'Content-Type: image/jpeg\r\n\r\n' + frame + b'\r\n\r\n')
        except Exception as exc:
            logger.error("Error generating frame: %s", exc)
            time.sleep(0.1)


@app.route('/', methods=['GET', 'POST'])
def index() -> str:
    """Handle the main web page and form submissions."""
    if request.method == 'POST':
        classifiers = {c.name for c in Classifier.classifiers}
        required_fields = {'classifier': 'Motion Detector', 'live_preview': True,
                           'email_notifications': True, 'recipient': 'user@example.com',
                           'interval': '10'}
        for field, default_val in required_fields.items():
            if field not in request.values:
                request.values[field] = default_val

        classifier_name = request.values.get('classifier', 'dummy')
        if classifier_name not in classifiers:
            logger.warning("Invalid classifier selected: %s", classifier_name)
            classifier_name = 'dummy'

        global _classifier, _camera
        try:
            _classifier = init_classifier(classifier_name)
            _camera = init_camera()
        except Exception as exc:
            logger.error("Failed to initialize camera/classifier: %s", exc)
            return "Error initializing camera. Check logs."

        if _classifier.name == "mail_sender":
            _classifier.send_email_periodically(_classifier.interval, _classifier.recipient)

        t = threading.Thread(target=check_for_objects,
                             args=(_camera, _classifier,
                                   request.values.get('recipient', ''),
                                   request.values.get('interval', 10),
                                   time.time()),
                             daemon=True)
        t.start()

    classifiers = {c.name for c in Classifier.classifiers}
    return render_template_string(PAGE, classifiers=classifiers)


@app.route('/video_feed')
def video_feed() -> Response:
    """Return the video feed as a multipart stream."""
    return Response(gen(_camera), mimetype='multipart/x-mixed-replace; boundary=frame')


def cleanup() -> None:
    """Release camera resources on exit."""
    global _camera
    if _camera is not None:
        try:
            _camera.stop()
        except Exception as exc:
            logger.error("Error stopping camera: %s", exc)
        _camera = None


def signal_handler(signum, frame) -> None:
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    logger.info("Received signal %s, shutting down...", signum)
    _stop_event.set()
    cleanup()
    sys.exit(0)


if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    atexit.register(cleanup)

    try:
        _camera = init_camera()
    except Exception:
        logger.error("Camera initialization failed. Exiting.")
        sys.exit(1)

    try:
        app.run(host='0.0.0.0', debug=False, threaded=True)
    finally:
        cleanup()

