import cv2
import numpy as np
import serial
import serial.tools.list_ports
import signal
import sys

running = True

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def get_hsv_range(roi):
    h_min = roi[:, :, 0].min()
    h_max = roi[:, :, 0].max()
    s_min = roi[:, :, 1].min()
    s_max = roi[:, :, 1].max()
    v_min = roi[:, :, 2].min()
    v_max = roi[:, :, 2].max()
    return (int(h_min), int(h_max), int(s_min), int(s_max), int(v_min), int(v_max))

def main():
    global running

    cap = cv2.VideoCapture(0)
    if not cap.isOpened():
        print("Error: Could not open camera.", file=sys.stderr)
        sys.exit(1)

    try:
        available_ports = [p.device for p in serial.tools.list_ports.comports()]
    except Exception as e:
        print(f"Warning: Could not list serial ports: {e}", file=sys.stderr)
        available_ports = []

    ser = None
    try:
        if '/dev/ttyACM0' in available_ports:
            try:
                ser = serial.Serial('/dev/ttyACM0', 9600, timeout=1)
                print("Serial port /dev/ttyACM0 opened at 9600 baud.")
            except Exception as e:
                print(f"Warning: Could not open /dev/ttyACM0: {e}", file=sys.stderr)
                ser = None
        if ser is None:
            try:
                ser = serial.Serial(available_ports[0], 9600, timeout=1)
                print(f"Serial port {available_ports[0]} opened at 9600 baud.")
            except Exception as e:
                print(f"Warning: Could not open any available serial port: {e}", file=sys.stderr)
                ser = None
    except Exception as e:
        print(f"Warning: Could not open serial port: {e}", file=sys.stderr)
        ser = None

    tracking = False
    ball_x = 0
    ball_y = 0

    try:
        while running:
            ret, frame = cap.read()
            if not ret or frame is None:
                print("Warning: Frame read failed or camera disconnected.", file=sys.stderr)
                break

            h_frame, w_frame, _ = frame.shape
            cx, cy = w_frame // 2, h_frame // 2
            roi = frame[cy - 5:cy + 5, cx - 5:cx + 5, :]

            hsv_range = get_hsv_range(roi)
            lower_bound = np.array([hsv_range[0], hsv_range[1], hsv_range[2]], dtype=np.uint8)
            upper_bound = np.array([hsv_range[3], hsv_range[4], hsv_range[5]], dtype=np.uint8)

            if tracking:
                frame = cv2.GaussianBlur(frame, (11, 11), 0)
                hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
                mask = cv2.inRange(hsv, lower_bound, upper_bound)
                mask = cv2.erode(mask, None, iterations=2)
                mask = cv2.dilate(mask, None, iterations=2)

                contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

                for cnt in contours:
                    if cv2.contourArea(cnt) > 500:
                        x, y, w, h = cv2.boundingRect(cnt)
                        cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)

                        bx = x + w // 2
                        by = y + h // 2

                        if abs(bx - cx) < 50 and abs(by - cy) < 50:
                            if abs(bx - cx) < 25 and abs(by - cy) < 25:
                                if ball_x == 0 and ball_y == 0:
                                    print("Center")
                                    if ser and ser.is_open:
                                        try:
                                            ser.write(b'5')
                                        except Exception as e:
                                            print(f"Warning: Serial write failed: {e}", file=sys.stderr)
                                    ball_x = bx
                                    ball_y = by
                        elif bx > cx + 50 and by > cy + 50:
                            print("1 - Bottom Right")
                            if ser and ser.is_open:
                                try:
                                    ser.write(b'1')
                                except Exception as e:
                                    print(f"Warning: Serial write failed: {e}", file=sys.stderr)
                        elif bx > cx + 50 and by < cy - 50:
                            print("3 - Bottom Left")
                            if ser and ser.is_open:
                                try:
                                    ser.write(b'3')
                                except Exception as e:
                                    print(f"Warning: Serial write failed: {e}", file=sys.stderr)
                        elif bx < cx - 50 and by > cy + 50:
                            print("2 - Top Right")
                            if ser and ser.is_open:
                                try:
                                    ser.write(b'2')
                                except Exception as e:
                                    print(f"Warning: Serial write failed: {e}", file=sys.stderr)
                        elif bx < cx - 50 and by < cy - 50:
                            print("4 - Top Left")
                            if ser and ser.is_open:
                                try:
                                    ser.write(b'4')
                                except Exception as e:
                                    print(f"Warning: Serial write failed: {e}", file=sys.stderr)

                cv2.imshow("Mask", mask)

            cv2.imshow("Frame", frame)
            cv2.imshow("Mask", mask)

            k = cv2.waitKey(1) & 0xFF
            if k == ord('s'):
                tracking = True
            elif k == ord('o'):
                tracking = False
                ball_x = 0
                ball_y = 0
            elif k == 27:
                running = False

    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        cap.release()
        if ser is not None and ser.is_open:
            try:
                ser.close()
            except Exception:
                pass
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

