import cv2
import face_recognition
import numpy as np
import os
import time
import signal
import sys

BUTTON_PIN = 23
DEBOUNCE_DELAY = 0.2
DATASET_DIR = "Dataset"
TOLERANCE = 0.6
DEDUP_WINDOW = 5.0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def load_known_faces(dataset_dir):
    known_encodings = []
    known_names = []
    if not os.path.isdir(dataset_dir):
        print(f"Error: dataset directory '{dataset_dir}' not found.")
        return None, None
    for filename in os.listdir(dataset_dir):
        if not filename.lower().endswith((".jpg", ".jpeg", ".png")):
            continue
        path = os.path.join(dataset_dir, filename)
        try:
            image = face_recognition.load_image_file(path)
            encodings = face_recognition.face_encodings(image)
            if encodings:
                known_encodings.append(encodings[0])
                known_names.append(os.path.splitext(filename)[0])
            else:
                print(f"Warning: no face found in '{filename}'.")
        except Exception as e:
            print(f"Warning: could not process '{filename}': {e}")
    if not known_encodings:
        print("Error: no valid face encodings found in the dataset.")
        return None, None
    return known_encodings, known_names

def recognize_face(frame, known_encodings, known_names, tolerance):
    rgb_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
    face_locations = face_recognition.face_locations(rgb_frame)
    face_encodings = face_recognition.face_encodings(rgb_frame, face_locations)
    names = []
    for encoding in face_encodings:
        matches = face_recognition.compare_faces(known_encodings, encoding, tolerance=tolerance)
        name = "Unknown"
        if True in matches:
            matched_idxs = [i for (i, b) in enumerate(matches) if b]
            counts = {}
            for i in matched_idxs:
                label = known_names[i]
                counts[label] = counts.get(label, 0) + 1
            name = max(counts, key=counts.get)
        names.append(name)
    return face_locations, names

def print_name(name):
    print(f"{name} was here")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    known_encodings, known_names = load_known_faces(DATASET_DIR)
    if known_encodings is None or known_names is None:
        sys.exit(1)
    cap = cv2.VideoCapture(0)
    if not cap.isOpened():
        print("Error: could not open camera.")
        sys.exit(1)
    last_seen = {}
    try:
        while running:
            ret, frame = cap.read()
            if not ret:
                print("Error: could not read frame from camera.")
                break
            face_locations, names = recognize_face(frame, known_encodings, known_names, TOLERANCE)
            for (top, right, bottom, left), name in zip(face_locations, names):
                cv2.rectangle(frame, (left, top), (right, bottom), (0, 255, 0), 2)
                if name != "Unknown":
                    if name not in last_seen or time.time() - last_seen[name] > DEDUP_WINDOW:
                        print_name(name)
                        last_seen[name] = time.time()
            cv2.imshow("Video", frame)
            if cv2.waitKey(1) & 0xFF == ord('q'):
                break
    finally:
        cap.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

