import time
import json
import logging
import signal
import sys
import statistics
from datetime import datetime

try:
    import RPi.GPIO as GPIO
except Exception:
    GPIO = None

DEFAULT_CONFIG = {
    "sensor_offsets": [0.0, 0.0, 0.0],
    "max_distance": 200.0,
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file="config.json"):
    cfg = dict(DEFAULT_CONFIG)
    try:
        with open(config_file, "r") as f:
            user_cfg = json.load(f)
        cfg.update(user_cfg)
    except FileNotFoundError:
        logging.warning("Config file '%s' not found; using defaults.", config_file)
    except json.JSONDecodeError as exc:
        logging.error("Config file '%s' is invalid (%s); using defaults.", config_file, exc)
    except OSError as exc:
        logging.error("Cannot read config file '%s' (%s); using defaults.", config_file, exc)
    return cfg


def initialize_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    logging.info("Water level monitoring system started.")


def initialize_gpio(trigger_pins, echo_pins):
    if GPIO is None:
        logging.warning("RPi.GPIO not available; running in mock mode.")
        return None, None
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    pins = dict(zip(trigger_pins, echo_pins))
    for name, pin in pins.items():
        GPIO.setup(pin, GPIO.IN)
        GPIO.setup(pins[name], GPIO.OUT)
        GPIO.output(pins[name], GPIO.LOW)
    logging.info("GPIO initialized: triggers=%s, echoes=%s", trigger_pins, echo_pins)
    return trigger_pins, echo_pins


def cleanup_gpio(trigger_pins, echo_pins):
    if GPIO is None:
        return
    try:
        for pin in echo_pins:
            GPIO.cleanup(pin)
    except Exception:
        pass
    try:
        for pin in trigger_pins:
            GPIO.cleanup(pin)
    except Exception:
        pass
    GPIO.cleanup()
    logging.info("GPIO cleaned up.")


def measure_distance(trigger_pin, echo_pin, timeout=0.05):
    if GPIO is None:
        return None
    try:
        GPIO.output(trigger_pin, GPIO.LOW)
        time.sleep(0.000002)
        GPIO.output(trigger_pin, GPIO.HIGH)
        time.sleep(0.00001)
        GPIO.output(trigger_pin, GPIO.LOW)

        start = time.time()
        while GPIO.input(echo_pin) == GPIO.LOW:
            if time.time() - start > timeout:
                return None
        pulse_start = time.time()

        while GPIO.input(echo_pin) == GPIO.HIGH:
            if time.time() - pulse_start > timeout:
                return None
        pulse_end = time.time()

        pulse_duration = pulse_end - pulse_start
        distance = pulse_duration * 17150.0
        return round(distance, 2)
    except Exception as exc:
        logging.error("Error measuring distance on trigger=%s echo=%s: %s", trigger_pin, echo_pin, exc)
        return None


def get_median_distance(trigger_pins, echo_pins, sensor_offsets, max_distance):
    distances = []
    for i, (trigger, echo) in enumerate(zip(trigger_pins, echo_pins)):
        dist = measure_distance(trigger, echo)
        if dist is not None:
            dist += sensor_offsets[i]
            if 0 < dist < max_distance:
                distances.append(dist)
    if not distances:
        return None
    return round(statistics.median(distances), 2)


def check_alerts(distance, low, high, repeat_delay, last_alert):
    now = time.time()
    if distance is not None and (low < distance < high):
        if (now - last_alert) >= repeat_delay:
            logging.warning(
                "Water level alert: %.2f cm (low=%.1f high=%.1f)", distance, low, high
            )
            return now
    return last_alert


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = load_config()
    initialize_logging(config["log_file"])

    trigger_pins = [17, 22, 24]
    echo_pins = [18, 23, 25]
    trigger_pins, echo_pins = initialize_gpio(trigger_pins, echo_pins)

    sensor_offsets = config["sensor_offsets"]
    max_distance = config["max_distance"]
    low = config["alert_threshold_low"]
    high = config["alert_threshold_high"]
    repeat_delay = config["alert_repeat_delay"]
    last_alert = 0.0

    sensor_errors = [0, 0, 0]
    MAX_SENSOR_ERRORS = 5

    try:
        while _running:
            distance = get_median_distance(trigger_pins, echo_pins, sensor_offsets, max_distance)

            if distance is None:
                logging.error("Failed to get valid reading from any sensor.")
            else:
                logging.info("Water level: %.2f cm", distance)
                last_alert = check_alerts(distance, low, high, repeat_delay, last_alert)

                for i in range(len(sensor_errors)):
                    if sensor_errors[i] < MAX_SENSOR_ERRORS:
                        if distance is not None:
                            sensor_errors[i] = 0
                        else:
                            sensor_errors[i] += 1
                            if sensor_errors[i] >= MAX_SENSOR_ERRORS:
                                logging.error("Excluding sensor %d due to consecutive errors.", i + 1)

                if all(err >= MAX_SENSOR_ERRORS for err in sensor_errors):
                    logging.error("All sensors have been excluded due to errors.")

            time.sleep(5)
    except Exception as exc:
        logging.error("Unexpected error in main loop: %s", exc)
    finally:
        cleanup_gpio(trigger_pins, echo_pins)
        logging.info("Water level monitoring system stopped.")
        sys.exit(0)


if __name__ == "__main__":
    main()

