import signal
import sys
import time

from gpiozero import PWMOutputDevice

PWM_PIN = 17
TEMP_FILE = "/sys/class/thermal/thermal_zone0/temp"
POLL_INTERVAL = 5
DEFAULT_PWM = 1.0


def read_cpu_temp():
    """Read CPU temperature in degrees Celsius from the sysfs thermal zone."""
    try:
        with open(TEMP_FILE, "r") as f:
            raw = f.read().strip()
        return float(raw) / 1000.0
    except (OSError, ValueError) as exc:
        raise RuntimeError(f"Failed to read CPU temperature: {exc}") from exc


def get_target_pwm(cpu_temp, thresholds, pwm_values):
    """Map CPU temperature to a PWM duty cycle using linear interpolation."""
    if len(thresholds) != len(pwm_values):
        raise ValueError("Thresholds and PWM values must have equal length.")
    for pwm in pwm_values:
        if not 0.0 <= pwm <= 1.0:
            raise ValueError(f"PWM value must be between 0.0 and 1.0, got {pwm}.")
    for i in range(len(thresholds) - 1):
        if thresholds[i] <= cpu_temp < thresholds[i + 1]:
            return pwm_values[i] + (pwm_values[i + 1] - pwm_values[i]) / (thresholds[i + 1] - thresholds[i]) * (cpu_temp - thresholds[i])
    return pwm_values[-1]


def main():
    thresholds = [65.0, 55.0, 50.0, 45.0]
    pwm_values = [1.0, 0.8, 0.6, 0.4]

    if len(thresholds) != len(pwm_values):
        print("Error: Thresholds and PWM values must have equal length.", file=sys.stderr)
        sys.exit(1)

    fan = None
    running = True

    def shutdown(signum, frame):
        nonlocal running
        running = False

    signal.signal(signal.SIGINT, shutdown)
    signal.signal(signal.SIGTERM, shutdown)

    try:
        fan = PWMOutputDevice(PWM_PIN)
        fan.value = DEFAULT_PWM
        print(f"Fan control started on BCM pin {PWM_PIN}. Default PWM {DEFAULT_PWM}.")
    except Exception as exc:
        print(f"Error: Failed to initialize PWM on pin {PWM_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            try:
                cpu_temp = read_cpu_temp()
                target_pwm = get_target_pwm(cpu_temp, thresholds, pwm_values)
                fan.value = target_pwm
                print(f"CPU: {cpu_temp:.1f}°C -> PWM: {target_pwm:.2f}")
            except RuntimeError as exc:
                print(f"Warning: {exc}. Setting fan to default PWM {DEFAULT_PWM}.", file=sys.stderr)
                try:
                    fan.value = DEFAULT_PWM
                except Exception as write_exc:
                    print(f"Error: Failed to set default PWM: {write_exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Error: Unexpected error in control loop: {exc}", file=sys.stderr)

            for _ in range(POLL_INTERVAL):
                if not running:
                    break
                time.sleep(1)
    finally:
        if fan is not None:
            try:
                fan.value = DEFAULT_PWM
                fan.close()
                print("Fan set to default PWM and closed.")
            except Exception as exc:
                print(f"Error during cleanup: {exc}", file=sys.stderr)


if __name__ == "__main__":
    main()

