import cv2
import numpy as np
import logging
import signal
import sys
import time

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

OUTPUT_PIN = 17
FRAME_WIDTH = 320
FRAME_HEIGHT = 240
FRAMERATE = 10
ROI = (slice(10, 150), slice(40, 280))

_running = True

def _signal_handler(signum, frame):
    global _running
    logging.info(f"Signal {signum} received; shutting down.")
    _running = False

def initialize_camera(width=FRAME_WIDTH, height=FRAME_HEIGHT, framerate=FRAMERATE):
    try:
        cap = cv2.VideoCapture(0, cv2.CAP_V4L2)
        if not cap.isOpened():
            raise IOError("Cannot open camera (index 0). Check that the CSI bus is enabled and the camera is connected.")

        cap.set(cv2.CAP_PROP_FRAME_WIDTH, width)
        cap.set(cv2.CAP_PROP_FRAME_HEIGHT, height)
        cap.set(cv2.CAP_PROP_FPS, framerate)

        actual_w = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))
        actual_h = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))
        actual_fps = cap.get(cv2.CAP_PROP_FPS)
        logging.info(f"Camera initialized: {actual_w}x{actual_h} @ {actual_fps:.1f} fps")
        return cap
    except Exception as e:
        logging.error(f"Camera initialization failed: {e}")
        return None

def process_frame(frame):
    try:
        x1, y1, x2, y2 = map(int, ROI)
        return frame[y1:y2, x1:x2]
    except Exception as e:
        logging.error(f"Frame processing failed: {e}")
        return None

def display_images(image, window_name="Output Image"):
    try:
        cv2.imshow(window_name, image)
        return True
    except Exception as e:
        logging.error(f"Display error: {e}")
        return False

def cleanup(cap):
    if cap is not None:
        try:
            cap.release()
        except Exception as e:
            logging.error(f"Error releasing camera: {e}")
    cv2.destroyAllWindows()

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    cap = initialize_camera()
    if cap is None:
        sys.exit(1)

    try:
        cv2.namedWindow("Output Image")
        cv2.setMouseCallback("Output Image", lambda event, window_name, cap: _on_mouse_event(event, window_name, cap))

        logging.info("Press Enter to exit...")
        while _running:
            ret, frame = cap.read()
            if not ret:
                logging.error("Failed to grab frame from camera.")
                break

            processed = process_frame(frame)
            if processed is None:
                continue

            if display_images(processed):
                break

        logging.info("Exiting via Enter key press.")
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received.")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        cleanup(cap)

def _on_mouse_event(event, window_name, cap):
    if event.code == 10:
        logging.info("Enter key pressed; exiting.")
        _running = False

if __name__ == "__main__":
    main()

