import os
import time
import signal
import logging
import argparse
import datetime
import threading
import queue
import shutil
import subprocess
from typing import Optional, List, Tuple

import numpy as np
from PIL import Image
import cv2

try:
    from picamera2 import Picamera2
    from picamera2.encoders import H264Encoder
    from picamera2.outputs import FfmpegOutput
except ImportError:
    Picamera2 = None
    H264Encoder = None
    FfmpegOutput = None

try:
    from general import Configuration, parse_arguments
except ImportError:
    Configuration = None
    parse_arguments = None

try:
    from server import HttpServer
except ImportError:
    HttpServer = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

DEFAULT_CONFIG = {
    'motion_threshold': 20,
    'min_motion_vectors': 10,
    'pre_record_time': 5,
    'post_record_time': 10,
    'resolution': (640, 480),
    'recording_duration': 10,
    'max_disk_space': 1.0,
    'storage_path': 'recordings',
    'port': 8000,
    'http_endpoint': '/stream.m3u8'
}


class CameraHandler:
    def __init__(self, config: Configuration):
        self.config = config
        self.picam2: Optional[Picamera2] = None
        self.encoder: Optional[H264Encoder] = None
        self.output: Optional[FfmpegOutput] = None
        self.pre_buffer: queue.Queue = queue.Queue(maxsize=int(config['pre_record_time'] * config['resolution'][1]))
        self.post_buffer: queue.Queue = queue.Queue(maxsize=int(config['post_record_time'] * config['resolution'][1]))
        self.recording = False
        self.recording_lock = threading.Lock()
        self.motion_detected = False
        self.motion_lock = threading.Lock()
        self.running = True
        self.stream_thread: Optional[threading.Thread] = None
        self.http_thread: Optional[threading.Thread] = None

    def initialize_camera(self) -> bool:
        if Picamera2 is None:
            logger.error("picamera2 library not found.")
            return False
        try:
            self.picam2 = Picamera2()
            video_config = self.picam2.create_video_configuration(
                main={"size": tuple(self.config['resolution']), "format": "RGB888"},
                lores={"size": tuple(self.config['resolution']), "format": "YUV420"}
            )
            self.picam2.configure(video_config)
            self.encoder = H264Encoder(bitrate=1000000)
            self.output = FfmpegOutput(os.path.join(self.config['storage_path'], 'temp.h264'))
            self.picam2.start_recording(self.encoder, self.output)
            time.sleep(2)
            logger.info("Camera initialized successfully.")
            return True
        except Exception as e:
            logger.error(f"Error initializing camera: {e}")
            return False

    def start_streaming(self):
        if not self.initialize_camera():
            return
        self.stream_thread = threading.Thread(target=self._stream_loop, daemon=True)
        self.stream_thread.start()

    def _stream_loop(self):
        try:
            while self.running:
                frame = self.picam2.capture_array()
                if frame is None:
                    continue
                self.pre_buffer.put(frame.copy())
                time.sleep(1 / 15)
        except Exception as e:
            logger.error(f"Error in streaming loop: {e}")
        finally:
            self.stop_streaming()

    def start_http_streaming(self):
        if HttpServer is None:
            logger.error("HttpServer module not found.")
            return
        if not self.initialize_camera():
            return
        self.http_thread = threading.Thread(target=self._http_loop, daemon=True)
        self.http_thread.start()

    def _http_loop(self):
        if HttpServer is None:
            logger.error("HttpServer module not found.")
            return
        try:
            server = HttpServer()
            server.start(self.config['port'], self._handle_request)
        except Exception as e:
            logger.error(f"Error starting HTTP server: {e}")
        finally:
            self.stop_streaming()

    def _handle_request(self, request):
        try:
            if request.method == 'GET' and request.path == self.config['http_endpoint']:
                self.create_m3u8_file()
                return 'index.m3u8'
            return '404 Not Found'
        except Exception as e:
            logger.error(f"Error handling HTTP request: {e}")
            return '500 Internal Server Error'

    def create_m3u8_file(self):
        os.makedirs(self.config['storage_path'], exist_ok=True)
        temp_path = os.path.join(self.config['storage_path'], 'temp.m3u8')
        with open(temp_path, 'w') as f:
            f.write('#EXTM3U\n')
            f.write(f'#EXT-X-STREAM-INF:TYPE=HLS/LOWRES\n')
            f.write(f'{self.config["resolution"][0]}x{self.config["resolution"][1]} Low Resolution\n')
            f.write(f'{temp_path}\n')

        self.move_temp_file()

    def move_temp_file(self):
        try:
            if os.path.exists(temp_path):
                os.rename(temp_path, os.path.join(self.config['storage_path'], 'index.m3u8'))
        except Exception as e:
            logger.error(f"Error moving temp file: {e}")

    def record_event(self):
        if not self.recording_lock.acquire(blocking=False):
            logger.warning("Recording already in progress, skipping.")
            return
        try:
            logger.info("Motion detected, starting recording.")
            self.recording = True
            self.motion_detected = True
            timestamp = datetime.datetime.now().strftime('%Y%m%d_%H%M%S')
            filename = os.path.join(self.config['storage_path'], f'{timestamp}.h264')
            self.encoder.output = FfmpegOutput(filename)
            self.output = None
            self.picam2.start_recording(self.encoder, self.encoder.output)
            time.sleep(self.config['recording_duration'])
            self.picam2.stop_recording()
            logger.info(f"Recording saved: {filename}")
        except Exception as e:
            logger.error(f"Error during recording: {e}")
        finally:
            self.recording = False
            self.recording_lock.release()

    def manage_disk_space(self):
        try:
            total, used, free = shutil.disk_usage(self.config['storage_path'])
            max_bytes = self.config['max_disk_space'] * 1024 * 1024 * 1024
            if used > max_bytes:
                logger.warning("Disk space exceeded. Deleting old files.")
                files = sorted([f for f in os.listdir(self.config['storage_path']) if os.path.isfile(os.path.join(self.config['storage_path'], f))],
                               key=lambda x: os.path.getmtime(os.path.join(self.config['storage_path'], x)))
                for file_name in files:
                    file_path = os.path.join(self.config['storage_path'], file_name)
                    try:
                        os.remove(file_path)
                        used -= os.path.getsize(file_path)
                        logger.info(f"Deleted old file: {file_name}")
                        if used <= max_bytes:
                            break
                    except Exception as e:
                        logger.error(f"Error deleting file {file_name}: {e}")
        except Exception as e:
            logger.error(f"Error managing disk space: {e}")

    def stop_streaming(self):
        self.running = False
        if self.picam2:
            try:
                self.picam2.stop_recording()
            except Exception:
                pass
            try:
                self.picam2.close()
            except Exception:
                pass
            self.picam2 = None
        if self.encoder:
            self.encoder = None
        if self.output:
            try:
                self.output.close()
            except Exception:
                pass
            self.output = None

    def run(self):
