class CameraHandler:
    def __init__(self, config: Configuration):
        self.config = config
        self.picam2: Optional[Picamera2] = None
        self.encoder: Optional[H264Encoder] = None
        self.output: Optional[FfmpegOutput] = None
        self.pre_buffer: queue.Queue = queue.Queue(maxsize=int(config['pre_record_time'] * config['resolution'][1]))
        self.post_buffer: queue.Queue = queue.Queue(maxsize=int(config['post_record_time'] * config['resolution'][1]))
        self.recording = False
