import time
import signal

from gpiozero import LED
from picamera2 import Picamera2

LED_PIN = 17
IMAGE_DIR = "static/images"
BLINK_COUNT = 5
BLINK_ON = 0.2
BLINK_OFF = 0.2
COUNTDOWN_SECONDS = 2

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_led(pin):
    try:
        return LED(pin)
    except Exception as e:
        print(f"Error setting up LED on GPIO {pin}: {e}", file=sys.stderr)
        sys.exit(1)

def setup_camera():
    try:
        cam = Picamera2()
        cam.configure("still")
        cam.start()
        return cam
    except Exception as e:
        print(f"Error setting up camera: {e}", file=sys.stderr)
        sys.exit(1)

def ensure_directory(path):
    try:
        os.makedirs(path, exist_ok=True)
    except OSError as e:
        print(f"Error creating directory '{path}': {e}", file=sys.stderr)
        sys.exit(1)

def blink_led(led, count):
    for _ in range(count):
        if not _running:
            break
        led.on()
        time.sleep(BLINK_ON)
        led.off()
        time.sleep(BLINK_OFF)

def capture_image(cam, led, image_dir):
    timestamp = time.strftime("%Y%m%d-%H%M%S")
    image_path = os.path.join(image_dir, f"{timestamp}.jpg")
    try:
        led.on()
        cam.capture_file(image_path)
        print(f"Image captured: {image_path}")
        return image_path
    except Exception as e:
        print(f"Error capturing image: {e}", file=sys.stderr)
        return None
    finally:
        led.off()

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    led = setup_led(LED_PIN)
    cam = setup_camera()
    ensure_directory(IMAGE_DIR)

    blink_led(led, BLINK_COUNT)
    if not _running:
        return

    print("Counting down...")
    for i in range(COUNTDOWN_SECONDS, 0, -1):
        if not _running:
            break
        print(i)
        time.sleep(1)

    if not _running:
        return

    print("Capture!")
    image_path = capture_image(cam, led, IMAGE_DIR)
    if image_path:
        print("Image saved successfully.")
    else:
        print("Failed to capture image.", file=sys.stderr)
        sys.exit(1)

    try:
        cam.stop()
    except Exception:
        pass
    try:
        led.close()
    except Exception:
        pass

if __name__ == "__main__":
    main()

