import sys
import os
import time
import signal
import threading

import cv2
import numpy as np
import pygame.mixer

import config
import face

try:
    from hardware import camera, lock, button
except ImportError as e:
    print(f"Error: required hardware module not available: {e}", file=sys.stderr)
    sys.exit(1)


class DoorController:
    """Door controller that unlocks on face recognition and locks via Ctrl+l."""

    def __init__(self):
        self.lock_active = False
        self.welcome_played = False
        self.is_running = True
        self.camera = None
        self.lock_device = None
        self.button = None
        self.sound_channel = None
        self.welcome_sound = None
        self.later_sound = None
        self.wait_sound = None
        self.welcome_lock_event = threading.Event()

    # ---- audio setup -------------------------------------------------

    def initialize_audio(self):
        """Initialise the pygame audio system and load sounds."""
        try:
            pygame.mixer.init(frequency=48000, size=-16, channels=1, buffer=1024)
        except pygame.error as e:
            print(f"Error initializing audio: {e}", file=sys.stderr)
            raise

        try:
            self.welcome_sound = pygame.mixer.Sound(config.WELCOME_SOUND_PATH)
            self.later_sound = pygame.mixer.Sound(config.LATER_SOUND_PATH)
            self.wait_sound = pygame.mixer.Sound(config.WAIT_SOUND_PATH)
        except (pygame.error, FileNotFoundError) as e:
            print(f"Error loading audio files: {e}", file=sys.stderr)
            raise

        self.sound_channel = pygame.mixer.Channel(0)

    # ---- model load --------------------------------------------------

    def load_model(self):
        """Load the face recognition model and verify the file exists."""
        model_path = config.TRAINING_FILE
        if not os.path.isfile(model_path):
            print(f"Error: training file not found: {model_path}", file=sys.stderr)
            raise FileNotFoundError(model_path)
        try:
            self.model = cv2.face.EigenFaceRecognizer_create()
            self.model.read(model_path)
        except cv2.error as e:
            print(f"Error loading training data: {e}", file=sys.stderr)
            raise

    # ---- recognition -------------------------------------------------

    def recognize_face(self):
        """Capture an image, detect a face, and attempt recognition."""
        try:
            image = self.camera.read()
        except Exception as e:
            print(f"Error capturing image: {e}", file=sys.stderr)
            return False

        if image is None:
            print("Error: camera returned None.", file=sys.stderr)
            return False

        try:
            gray_image = cv2.cvtColor(image, cv2.COLOR_RGB2GRAY)
            face_coords = face.detect_single(gray_image)

            if face_coords is None:
                print("Could not detect single face!")
                return False

            x, y, w, h = face_coords
            cropped_face = face.crop(gray_image, x, y, w, h)
            resized_face = face.resize(cropped_face)

            label, confidence = self.model.predict(resized_face)
            print(
                "Predicted {0} face with confidence {1} (lower is more confident).".format(
                    "POSITIVE" if label == config.POSITIVE_LABEL else "NEGATIVE",
                    confidence,
                )
            )

            return (
                label == config.POSITIVE_LABEL
                and confidence < config.POSITIVE_THRESHOLD
            )

        except Exception as e:
            print(f"Error during face recognition: {e}", file=sys.stderr)
            return False

    # ---- lock control ------------------------------------------------

    def unlock_door(self):
        """Unlock the door and schedule the welcome sound."""
        if not self.lock_active:
            return
        try:
            self.lock_device.unlock()
            self.lock_active = False
            print("Door unlocked!")
            self.welcome_lock_event.set()
        except Exception as e:
            print(f"Error unlocking door: {e}", file=sys.stderr)

    def lock_door(self):
        """Lock the door immediately."""
        try:
            self.lock_device.lock()
            self.lock_active = True
            print("Door locked.")
        except Exception as e:
            print(f"Error locking door: {e}", file=sys.stderr)

    # ---- audio playback ----------------------------------------------

    def play_sound(self, sound):
        """Play a sound on the specified channel, blocking until it finishes."""
        if self.sound_channel is None:
            return
        try:
            self.sound_channel.play(sound)
            while self.sound_channel.get_busy():
                time.sleep(0.05)
        except pygame.error as e:
            print(f"Error playing sound: {e}", file=sys.stderr)

    # ---- main loop ---------------------------------------------------

    def run(self):
        """Main polling loop: listen for button presses and face recognition."""
        print("Running door controller...")
        print("Press button to lock (if unlocked), or unlock if the correct face is detected.")
        print("Press Ctrl+l to forcibly lock the door.")
        print("Press Ctrl+c to quit.")

        try:
            self.load_model()
            self.initialize_audio()

            self.camera.start()
            self.lock_device.start()
            self.button.start()

            while self.is_running:
                try:
                    if self.button.is_pressed():
                        if not self.lock_active:
                            print("Button pressed, looking for face...")
                            self.lock_door()
                        else:
                            print("Button pressed, looking for face...")
                            if self.recognize_face():
                                self.unlock_door()
                                self.welcome_played = True
                            else:
                                print("Recognition failed.")
                                self.play_sound(self.later_sound)
                                self.play_sound(self.wait_sound)
                        time.sleep(0.1)
                        continue
                except Exception as e:
                    print(f"Error in button polling: {e}", file=sys.stderr)
                    time.sleep(0.1)
                    continue

                time.sleep(0.1)

                if self.welcome_lock_event.wait(timeout=1.0):
                    self.welcome_lock_event.clear()
                    if not self.lock_active:
                        self.play_sound(self.welcome_sound)

        except Exception as e:
            print(f"Fatal error in main loop: {e}", file=sys.stderr)
        finally:
            self.cleanup()

    # ---- cleanup -----------------------------------------------------

    def cleanup(self):
        """Release all hardware resources and quit the audio system."""
        print("Cleaning up...")
        self.is_running = False

        try:
            if self.sound_channel is not None:
                self.sound_channel.stop()
        except Exception:
            pass

        try:
            pygame.mixer.quit()
        except Exception:
            pass

        try:
            if self.camera is not None:
                self.camera.stop()
        except Exception:
            pass

        try:
            if self.lock_device is not None:
                self.lock_device.stop()
        except Exception:
            pass

        try:
            if self.button is not None:
                self.button.stop()
        except Exception:
            pass

        print("Cleanup complete.")


def main():
    controller = DoorController()

    def signal_handler(signum, frame):
        print(f"\nSignal {signum} received, shutting down...")
        controller.is_running = False

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    controller.run()


