import argparse
import json
import logging
import signal
import sys
import time
from datetime import datetime

import cv2
import face_recognition
import numpy as np

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None

DOOR_RELAY_PIN = 17
DEFAULT_ENCODINGS_FILE = "encodings.json"
DEFAULT_MOTION_THRESHOLD = 500
DEFAULT_CONFIDENCE_THRESHOLD = 0.6
DEFAULT_DEBOUNCE_INTERVAL = 2.0
DEFAULT_DOOR_OPEN_DURATION = 5.0
DEFAULT_LOG_LEVEL = "INFO"

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_encodings(encodings_file):
    encodings = []
    try:
        with open(encodings_file, "r") as f:
            data = json.load(f)
            if "encodings" in data:
                encodings = data["encodings"]
            else:
                logging.warning("encodings.json missing 'encodings' key; starting empty.")
    except FileNotFoundError:
        logging.warning("encodings.json not found; starting with empty encodings.")
    except json.JSONDecodeError as e:
        logging.error(f"Failed to parse encodings.json: {e}")
    except OSError as e:
        logging.error(f"Error reading encodings.json: {e}")
    return encodings


def save_encodings(encodings_file, encodings):
    try:
        data = {"encodings": encodings}
        with open(encodings_file, "w") as f:
            json.dump(data, f, indent=4)
    except OSError as e:
        logging.error(f"Error saving encodings.json: {e}")


def activate_relay(relay_pin, duration):
    if GPIO is None:
        logging.warning("RPi.GPIO not available; relay activation simulated.")
        time.sleep(duration)
        return
    try:
        GPIO.output(relay_pin, GPIO.HIGH)
        logging.info(f"Relay activated on GPIO{relay_pin} for {duration:.1f}s.")
        time.sleep(duration)
    except Exception as e:
        logging.error(f"Error activating relay: {e}")
    finally:
        try:
            GPIO.output(relay_pin, GPIO.LOW)
            logging.info(f"Relay deactivated on GPIO{relay_pin}.")
        except Exception as e:
            logging.error(f"Error deactivating relay: {e}")


def process_frame(frame, known_encodings, confidence_threshold):
    rgb_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)
    face_locations = face_recognition.face_locations(rgb_frame)
    face_encodings = face_recognition.face_encodings(rgb_frame, face_locations)

    for face_encoding in face_encodings:
        distances = face_recognition.face_distance(known_encodings, face_encoding)
        if len(distances) == 0:
            logging.warning("No known face encodings available.")
            continue
        best_match_index = int(np.argmin(distances))
        confidence = 1 - distances[best_match_index]
        if confidence > confidence_threshold:
            logging.info(f"Face recognized (confidence={confidence:.2f}).")
            return True
        else:
            logging.info(f"Face not recognized (confidence={confidence:.2f}).")
    return False


def main():
    global _running

    parser = argparse.ArgumentParser(description="Raspberry Pi Face Recognition Door System")
    parser.add_argument("--encodings_file", type=str, default=DEFAULT_ENCODINGS_FILE)
    parser.add_argument("--motion_threshold", type=int, default=DEFAULT_MOTION_THRESHOLD)
    parser.add_argument("--confidence_threshold", type=float, default=DEFAULT_CONFIDENCE_THRESHOLD)
    parser.add_argument("--debounce_interval", type=float, default=DEFAULT_DEBOUNCE_INTERVAL)
    parser.add_argument("--door_open_duration", type=float, default=DEFAULT_DOOR_OPEN_DURATION)
    parser.add_argument("--log_level", type=str, default=DEFAULT_LOG_LEVEL, choices=["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"])
    args = parser.parse_args()

    logging.basicConfig(level=getattr(logging, args.log_level.upper()),
                        format="%(asctime)s - %(levelname)s - %(message)s")

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    known_encodings = load_encodings(args.encodings_file)
    if not known_encodings:
        logging.warning("No known face encodings loaded. All triggers will be logged as skipped.")

    if GPIO is not None:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(DOOR_RELAY_PIN, GPIO.OUT, initial=GPIO.LOW)

    camera = None
    try:
        camera = cv2.VideoCapture(0)
        if not camera.isOpened():
            raise IOError("Cannot open camera")
        logging.info("Camera opened successfully.")
    except Exception as e:
        logging.critical(f"Failed to initialize camera: {e}")
        if GPIO is not None:
            GPIO.cleanup()
        return

    last_trigger_time = 0.0

    try:
        while _running:
            ret, frame = camera.read()
            if not ret:
                logging.error("Failed to capture frame.")
                time.sleep(0.1)
                continue

            gray_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            if len(known_encodings) > 0:
                previous_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            else:
                previous_frame = None

            motion_pixels = 0
            if previous_frame is not None:
                frame_delta = cv2.absdiff(previous_frame, gray_frame)
                thresh = cv2.threshold(frame_delta, 10, 255, cv2.THRESH_BINARY)[1]
                thresh = cv2.dilate(thresh, None, iterations=2)
                motion_pixels = cv2.countNonZero(thresh)
                if motion_pixels > args.motion_threshold:
                    logging.info(f"Motion detected ({motion_pixels} pixels changed).")
                    if process_frame(frame, known_encodings, args.confidence_threshold):
                        now = time.time()
                        if now - last_trigger_time > args.debounce_interval:
                            logging.info("Face recognized; activating relay.")
                            activate_relay(DOOR_RELAY_PIN, args.door_open_duration)
                            last_trigger_time = now
                        else:
                            logging.info("Debounce skipped.")
            else:
                logging.info("No previous frame available; skipping motion detection.")

            time.sleep(0.1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        if camera is not None:
            camera.release()
        if GPIO is not None:
            GPIO.cleanup()
        logging.info("Program terminated cleanly.")


if __name__ == "__main__":
    main()

