import boto3
import time
import signal
import sys
import os
from botocore.exceptions import ClientError, BotoCoreError

try:
    from PIL import Image
except ImportError:
    print("Error: Pillow is required. Install with: pip install Pillow")
    sys.exit(1)

try:
    from picamera2 import Picamera2
except ImportError:
    print("Error: picamera2 is required. Install with: pip install picamera2")
    sys.exit(1)


class RekognitionError(Exception):
    """Custom exception for Rekognition service errors."""
    pass


class CameraError(Exception):
    """Custom exception for camera-related errors."""
    pass


class ImageCaptureError(Exception):
    """Custom exception for image capture errors."""
    pass


class RekognitionClient:
    """Handles AWS Rekognition API calls."""

    def __init__(self, region_name=None, endpoint_url=None):
        try:
            self.client = boto3.client('rekognition',
                                       region_name=region_name,
                                       endpoint_url=endpoint_url)
        except (BotoCoreError, Exception) as e:
            raise RekognitionError(f"Failed to initialize Rekognition client: {e}")

    def search_faces(self, image, collection_id, similarity_threshold=85):
        """Searches for faces in the given image using Rekognition."""
        try:
            response = self.client.search_faces_by_image(
                CollectionId=collection_id,
                Image={'Bytes': image.tobytes()},
                MaxFaces=1,
                FaceMatchThreshold=similarity_threshold
            )
            return response
        except ClientError as e:
            raise RekognitionError(f"Rekognition API error: {e}")
        except Exception as e:
            raise RekognitionError(f"Unexpected error during search: {e}")


class CameraManager:
    """Manages the Raspberry Pi camera using picamera2."""

    def __init__(self):
        self.camera = None
        try:
            self.camera = Picamera2()
            self.camera.configure(self.camera.create_still_configuration())
            self.camera.start()
        except Exception as e:
            raise CameraError(f"Failed to initialize camera: {e}")

    def capture_image(self):
        """Captures an image and returns it as a PIL Image object."""
        try:
            image = self.camera.capture_image()
            return image
        except Exception as e:
            raise ImageCaptureError(f"Image capture failed: {e}")

    def close(self):
        """Releases the camera resource."""
        if self.camera:
            try:
                self.camera.stop()
                self.camera.close()
            except Exception:
                pass
            self.camera = None


class ImageSaver:
    """Saves images to the filesystem."""

    def __init__(self, image_path="image.jpg"):
        self.image_path = image_path

    def save_image(self, image):
        """Saves the image to the specified path."""
        try:
            image.save(self.image_path)
            return True
        except OSError as e:
            raise IOError(f"Failed to save image to {self.image_path}: {e}")
        except Exception as e:
            raise IOError(f"Unexpected error saving image: {e}")


