import asyncio
import signal
import threading
import logging
import numpy as np
import cv2
import pyaotc
from pyaotc.web_socket import WebSocketHandler

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)


class MotionCamera:
    """Threaded camera driver that streams low-res JPEG and RGB888 for motion detection."""

    def __init__(self, detect_motion_function, camera_index=0):
        if not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable")
        self.detect_motion_function = detect_motion_function
        self.camera_index = camera_index
        self._lock = threading.Lock()
        self._streaming = False
        self._camera = None
        self._frame = None
        self._prev_frame = None
        self._broadcast_queue = asyncio.Queue()
        self._stop_event = threading.Event()

    def _init_camera(self):
        """Initialize the camera with error handling."""
        try:
            self._camera = cv2.VideoCapture(self.camera_index)
            if not self._camera.isOpened():
                raise IOError(f"Cannot open camera index {self.camera_index}")
            # Set a low resolution for motion detection (must match the signature of detect_motion_function)
            self._camera.set(cv2.CAP_PROP_FRAME_WIDTH, 320)
            self._camera.set(cv2.CAP_PROP_FRAME_HEIGHT, 240)
            # Set a higher resolution for streaming (must match the signature of detect_motion_function)
            self._stream_camera = cv2.VideoCapture(self.camera_index)
            if not self._stream_camera.isOpened():
                raise IOError(f"Cannot open stream camera index {self.camera_index}")
            self._stream_camera.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
            self._stream_camera.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)
            logger.info("Camera initialized successfully.")
        except Exception as e:
            logger.error(f"Error initializing camera: {e}")
            self._cleanup_camera()
            raise

    def _cleanup_camera(self):
        """Release camera resources."""
        if self._camera is not None:
            self._camera.release()
            self._camera = None
        if self._stream_camera is not None:
            self._stream_camera.release()
            self._stream_camera = None

    def _capture_frame(self):
        """Capture a frame from the camera with error handling."""
        try:
            ret, frame = self._camera.read()
            if not ret or frame is None:
                logger.warning("Failed to capture frame from camera.")
                return None
            return frame
        except Exception as e:
            logger.error(f"Error capturing frame: {e}")
            return None

    def _convert_to_jpeg(self, frame):
        """Convert an RGB888 NumPy frame to JPEG bytes using pyaotc imencode."""
        try:
            success, encoded = cv2.imencode('.jpg', frame)
            if not success:
                logger.warning("Failed to encode frame to JPEG.")
                return None
            return encoded.tobytes()
        except Exception as e:
            logger.error(f"Error converting frame to JPEG: {e}")
            return None

    def _motion_detection_loop(self):
        """Continuously capture frames and run motion detection."""
        while not self._stop_event.is_set():
            frame = self._capture_frame()
            if frame is None:
                self._stop_event.wait(timeout=0.1)
                continue

            # Run motion detection on the low-resolution frame
            try:
                motion = self.detect_motion_function(self._prev_frame, frame)
            except Exception as e:
                logger.error(f"Error in motion detection function: {e}")
                motion = False

            if motion:
                logger.info("Motion detected!")

            with self._lock:
                self._prev_frame = frame.copy()

            self._broadcast_queue.put((frame, True))
            self._broadcast_queue.put((None, False))  # Signal to broadcast

    def _stream_loop(self):
        """Continuously capture high-resolution frames and broadcast JPEG streams."""
        while not self._stop_event.is_set():
            try:
                ret, frame = self._stream_camera.read()
                if not ret or frame is None:
                    logger.warning("Failed to capture stream frame.")
                    self._stop_event.wait(timeout=0.1)
                    continue

                jpeg_data = self._convert_to_jpeg(frame)
                if jpeg_data is None:
                    continue

                self._broadcast_queue.put((jpeg_data, True))
                self._broadcast_queue.put((None, False))  # Signal to broadcast
            except Exception as e:
                logger.error(f"Error in streaming loop: {e}")
                self._stop_event.wait(timeout=0.1)

    def _broadcast_loop(self):
        """Broadcast frames and motion events to WebSocket clients."""
        while not self._stop_event.is_set():
            try:
                frame, is_jpeg = self._broadcast_queue.get(timeout=0.5)
                if is_jpeg:
                    if WebSocketHandler.has_connections():
                        try:
                            WebSocketHandler.broadcast(frame)
                        except Exception as e:
                            logger.error(f"Error broadcasting frame: {e}")
                    else:
                        logger.debug("No WebSocket connections, skipping broadcast.")
                self._broadcast_queue.task_done()
            except asyncio.TimeoutError:
                continue
            except Exception as e:
                logger.error(f"Error in broadcast loop: {e}")

    def start(self):
        """Start the camera, motion detection, and broadcast threads."""
        self._init_camera()
        self._streaming = True

        self.motion_thread = threading.Thread(target=self._motion_detection_loop, daemon=True)
        self.stream_thread = threading.Thread(target=self._stream_loop, daemon=True)
        self.broadcast_thread = threading.Thread(target=self._broadcast_loop, daemon=True)

        self.motion_thread.start()
        self.stream_thread.start()
        self.broadcast_thread.start()

        logger.info("Camera started successfully.")

    def stop(self):
        """Stop the camera and release resources."""
        if not self._streaming:
            return
        self._stop_event.set()

        for thread in (self.motion_thread, self.stream_thread, self.broadcast_thread):
            thread.join(timeout=2.0)

        self._cleanup_camera()
        logger.info("Camera stopped and resources released.")


async def main():
    """Main entry point: start the camera and wait for shutdown signal."""
    camera = MotionCamera(detect_motion_function=None, camera_index=0)

    def _shutdown(signum, frame):
        logger.info(f"Received signal {signum}, shutting down...")
        camera.stop()

    signal.signal(signal.SIGINT, _shutdown)
    signal.signal(signal.SIGTERM, _shutdown)

    try:
        camera.start()
        await asyncio.gather(
            asyncio.create_task(camera._broadcast_thread.join()),
            asyncio.create_task(asyncio.get_event_loop().run_forever())
        )
    except asyncio.CancelledError:
        pass
    finally:
        camera.stop()


if __name__ == "__main__":
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        pass

