import signal
import sys
import time

try:
    import smbus2 as smbus
except ImportError:
    import smbus

I2C_BUS = 1

_running = True


def _handle_sigint(signum, frame):
    global _running
    _running = False


def _read_sensor(bus):
    try:
        data = bus.read_i2c_block_data(0x88, 0xAC, 4)
        raw_h = (data[1] << 12) | (data[2] << 4) | (data[3] >> 4)
        raw_t = ((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]
        humidity = (raw_h / 2**20) * 100.0
        temperature = (raw_t / 2**20) * 200.0 - 50.0
        return temperature, humidity
    except OSError as exc:
        print(f"Error reading sensor: {exc}")
        return None, None
    except Exception as exc:
        print(f"Error reading sensor: {exc}")
        return None, None


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_sigint)

    try:
        bus = smbus.SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error initializing sensor: {exc}")
        sys.exit(1)

    try:
        while _running:
            temperature, humidity = _read_sensor(bus)
            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
            time.sleep(5)
    finally:
        print("Exiting...")
        sys.exit(0)


if __name__ == "__main__":
    main()

