import signal
import sys
import time
import threading

import cv2
import numpy as np
import sounddevice as sd
from scipy.io.wavfile import read as read_wav

import config
import face

# ---------------------------------------------------------------------------
# Pin assignments (BCM numbering)
# ---------------------------------------------------------------------------
DOOR_PIN = 18          # Active-high door actuator (relay / MOSFET gate)
BUTTON_PIN = 17        # Active-low push-button to GND with internal pull-up

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_lock = threading.Lock()


def _signal_handler(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _cleanup():
    """Release all driver resources."""
    try:
        if hasattr(face, 'camera'):
            face.camera.release()
    except Exception:
        pass
    try:
        if hasattr(face, 'mixer'):
            face.mixer.stop()
            face.mixer.close()
    except Exception:
        pass


def _load_sounds():
    """Pre-load WAV files as numpy arrays (16-bit PCM)."""
    sounds = {}
    for name, path in (
        ("welcome", config.WELCOME_SOUND_PATH),
        ("wait", config.WAIT_SOUND_PATH),
        ("later", config.LATER_SOUND_PATH),
    ):
        try:
            sr, data = read_wav(path)
            sounds[name] = data.astype(np.int16)
        except Exception as exc:
            print(f"[ERROR] Failed to load {name} from {path}: {exc}", file=sys.stderr)
    return sounds


def _play_sound(sound_name, volume=0.5):
    """Play a pre-loaded sound at 48 kHz mono using the mixer driver."""
    with _lock:
        if not _running:
            return
        if sound_name not in sounds:
            print(f"[WARN] Unknown sound: {sound_name}", file=sys.stderr)
            return
        sound = sounds[sound_name]
        try:
            face.mixer.fill(sound, 0, 0, 0, 0)
