import time
import signal
import threading
import smbus2
import RPi.GPIO as GPIO

# --- Configuration ---
I2C_BUS = 1
LCD_ADDR = 0x27
LED_PINS = [17, 18, 23, 27, 22]  # BCM pin numbers for LEDs 0-4

# LCD commands
LCD_CLEAR = 0x01
LCD_HOME = 0x02
LCD_ENTRY_MODE = 0x06
LCD_DISPLAY_ON = 0x0C
LCD_FUNCTION_4BIT_2LINE = 0x28
LCD_BACKLIGHT = 0x08

# --- LCD Driver ---
class LCD:
    def __init__(self, bus_num, addr):
        self.bus = smbus2.SMBus(bus_num)
        self.addr = addr
        self.backlight = LCD_BACKLIGHT
        self._init_lcd()

    def _write_byte(self, byte):
        self.bus.write_byte(self.addr, byte)

    def _pulse_enable(self, data):
        self._write_byte(data | self.backlight)
        time.sleep(0.0005)
        self._write_byte(data | self.backlight | 0x04)
        time.sleep(0.0005)

    def _send_nibble(self, nibble, mode):
        self._write_byte(nibble | mode)
        time.sleep(0.0001)

    def _send_byte(self, byte, mode):
        self._send_nibble(byte & 0xF0, mode)
        self._send_nibble((byte << 4) & 0xF0, mode)

    def _init_lcd(self):
        time.sleep(0.05)
        self._write_byte(0x33)
        self._write_byte(0x32)
        self._write_byte(0x06)
        self._write_byte(0x0C)
        self._write_byte(0x28)
        self._write_byte(0x01)
        time.sleep(0.002)

    def clear(self):
        self._send_byte(LCD_CLEAR, 0x00)
        time.sleep(0.002)

    def set_cursor(self, row, col):
        addr = 0x80 + col
        if row == 1:
            addr += 0x40
        self._send_byte(addr, 0x00)

    def write_string(self, text):
        for char in text:
            self._send_byte(ord(char), 0x01)

    def display_on(self):
        self._send_byte(LCD_DISPLAY_ON, 0x00)

    def close(self):
        try:
            self.clear()
            self.display_on()
        except Exception:
            pass
        try:
            self.bus.close()
        except Exception:
            pass

# --- CPU Stats ---
class CPUStats:
    def __init__(self):
        self.cpu_temp = 0.0
        self.cpu_usage = 0.0
        self.running = True
        self.thread = None

    def get_cpu_temp(self):
        try:
            with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
                return float(f.read().strip()) / 1000.0
        except Exception as e:
            print(f"Error reading CPU temperature: {e}")
            return 0.0

    def get_cpu_usage(self):
        try:
            import psutil
            return psutil.cpu_percent(interval=None)
        except Exception as e:
            print(f"Error reading CPU usage: {e}")
            return 0.0

    def update_lcd(self, lcd):
        try:
            lcd.clear()
            lcd.set_cursor(1, 0)
            temp_str = f"Temp: {self.cpu_temp:.1f}C"
            lcd.write_string(temp_str)
            lcd.set_cursor(2, 0)
            usage_str = f"Usage: {self.cpu_usage:.1f}%"
            lcd.write_string(usage_str)
        except Exception as e:
            print(f"Error updating LCD: {e}")

    def run(self):
        while self.running:
            self.cpu_temp = self.get_cpu_temp()
            self.cpu_usage = self.get_cpu_usage()
            if self.lcd:
                self.update_lcd(self.lcd)
            time.sleep(1)

    def stop(self):
        self.running = False
        if self.thread and self.thread.is_alive():
            self.thread.join(timeout=2)

# --- LED Controller ---
class LEDController:
    def __init__(self, pins):
        self.pins = pins
        self.leds = {}
        self._setup_gpio()

    def _setup_gpio(self):
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for pin in self.pins:
            try:
                GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
                self.leds[pin] = pin
            except Exception as e:
                print(f"Error setting up GPIO pin {pin}: {e}")

    def activate_led(self, cls):
        if not 0 <= cls <= 4:
            print(f"Invalid class index {cls}. Must be 0-4.")
            return
        pin = self.leds.get(LED_PINS[cls])
        if pin is None:
            print(f"LED pin for class {cls} not available.")
            return
        try:
            GPIO.output(pin, GPIO.HIGH)
            time.sleep(1)
            GPIO.output(pin, GPIO.LOW)
        except Exception as e:
            print(f"Error controlling LED for class {cls}: {e}")

    def cleanup(self):
        for pin in self.leds.values():
            try:
                GPIO.output(pin, GPIO.LOW)
            except Exception:
                pass
        GPIO.cleanup()

# --- Main ---
class CPUClassIndicator:
    def __init__(self):
        self.lcd = None
        self.led_ctrl = None
        self.cpu_stats = None
        self.running = True
        self.lcd_thread = None

        try:
            self.lcd = LCD(I2C_BUS, LCD_ADDR)
            self.led_ctrl = LEDController(LED_PINS)
            self.cpu_stats = CPUStats()
            self.cpu_stats.lcd = self.lcd
            self.lcd_thread = threading.Thread(target=self.cpu_stats.run, daemon=True)
            self.lcd_thread.start()
        except Exception as e:
            print(f"Initialization error: {e}")
            self.cleanup()
            raise

    def indicate_class(self, cls):
        self.led_ctrl.activate_led(cls)

    def run(self):
        while self.running:
            time.sleep(0.1)

    def stop(self):
        self.running = False
        if self.lcd_thread and self.lcd_thread.is_alive():
            self.cpu_stats.stop()
        if self.lcd:
            self.lcd.close()
        if self.led_ctrl:
            self.led_ctrl.cleanup()

def signal_handler(sig, frame):
    print("\nExiting...")
    if hasattr(signal_handler, 'indicator'):
        signal_handler.indicator.stop()

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    indicator = CPUClassIndicator()
    signal_handler.indicator = indicator
    try:
        indicator.run()
    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        indicator.stop()

