running = True

def signal_handler(signum, frame):
    global running
    running = False

def init_i2c():
    try:
        return smbus.SMBus(1)
    except FileNotFoundError:
        print("Error: I2C bus 1 not found. Enable I2C with 'sudo raspi-config'.")
        return None
    except PermissionError:
        print("Error: Permission denied accessing I2C bus. Run with sudo or add user to i2c group.")
        return None
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def read_temperature():
    try:
        with open(THERMAL_FILE, 'r') as f:
            return float(f.read().strip()) / 1000.0
    except FileNotFoundError:
        print(f"Error: Thermal zone file not found at {THERMAL_FILE}")
        return None
    except PermissionError:
        print(f"Error: Permission denied reading {THERMAL_FILE}")
        return None
    except (ValueError, OSError) as e:
        print(f"Error reading temperature: {e}")
        return None

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c = init_i2c()
    if i2c is None:
        sys.exit(1)

    try:
        while running:
            temp = read_temperature()
            if temp is not None:
                print(f"Temperature: {temp:.2f} C")
            time.sleep(2)
    finally:
        if i2c is not None:
            try:
                i2c.close()
            except Exception:
                pass

if __name__ == '__main__':
