import signal
import sys
import time

try:
    import smbus2 as smbus
except ImportError:
    import smbus

try:
    from luma.core.interface.serial import i2c
    from luma.oled.device import ssd1306
    from luma.core.render import canvas
except ImportError:
    print("Missing dependency: install with 'pip install luma.oled luma.core smbus2'")
    sys.exit(1)

I2C_BUS = 1
BH1750_ADDR = 0x23
BH1750_POWER_ON = 0x01
BH1750_CONTINUOUS_HIGH_RES_MODE = 0x10

running = True


def handle_signal(signum, frame):
    global running
    running = False


signal.signal(signal.SIGINT, handle_signal)
signal.signal(signal.SIGTERM, handle_signal)


def read_light_level(bus):
    bus.write_byte(BH1750_ADDR, BH1750_POWER_ON)
    time.sleep(0.01)
    bus.write_byte(BH1750_ADDR, BH1750_CONTINUOUS_HIGH_RES_MODE)
    time.sleep(0.12)
    data = bus.read_i2c_block_data(BH1750_ADDR, 0x00, 2)
    raw = (data[0] << 8) | data[1]
    lux = raw / 1.2
    return max(0.0, min(lux, 65535.0))


def lux_to_contrast(lux):
    return int(max(0.0, min(lux, 65535.0)) / 65535.0 * 255)


def main():
    global running

    try:
        serial = i2c(port=I2C_BUS, address=0)
        device = ssd1306(serial)
    except Exception as e:
        print(f"Display init failed: {e}")
