import signal
import sys
import time
import logging

import spidev
from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("mcp3008_oled")

SPI_BUS = 0
SPI_CS = 0
SPI_SPEED_HZ = 50000
I2C_PORT = 1
OLED_ADDR = 0x3C
SAMPLE_INTERVAL_S = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    log.info("Signal %s received – shutting down.", signum)
    _running = False


def init_spi():
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_CS)
        spi.max_speed_hz = SPI_SPEED_HZ
        spi.mode = 0
        spi.bits_per_word = 8
        log.info("SPI bus %d CS %d opened at %d Hz.", SPI_BUS, SPI_CS, SPI_SPEED_HZ)
        return spi
    except PermissionError:
        log.error("Permission denied opening /dev/spidev%d.%d – add user to the 'spi' group or run with appropriate privileges.", SPI_BUS, SPI_CS)
        return None
    except FileNotFoundError:
        log.error("SPI device /dev/spidev%d.%d not found – enable SPI with 'sudo raspi-config' or 'dtparam=spi=on'.", SPI_BUS, SPI_CS)
        return None
    except OSError as exc:
        log.error("Failed to initialize SPI: %s", exc)
        return None
    except Exception as exc:
        log.error("Unexpected SPI init error: %s", exc)
        return None


def init_oled():
    try:
        serial = i2c(port=I2C_PORT, address=OLED_ADDR)
        device = ssd1306(serial)
        log.info("SSD1306 OLED initialized on I2C bus %d at address 0x%02X.", I2C_PORT, OLED_ADDR)
        return device
    except OSError as exc:
        log.error("I2C/OLED init error (bus %d, addr 0x%02X): %s", I2C_PORT, OLED_ADDR, exc)
        return None
    except Exception as exc:
        log.error("Unexpected OLED init error: %s", exc)
        return None


def read_mcp3008_channel(spi, channel):
    if not 0 <= channel <= 7:
        raise ValueError("Channel must be 0-7")
    try:
        cmd = 0x18 | (channel << 4)
        rx = spi.xfer2([0x01, cmd, 0x00])
        value = ((rx[1] & 0x03) << 8) | rx[2]
        return value
    except OSError as exc:
        log.error("SPI read error on channel %d: %s", channel, exc)
        return None
    except Exception as exc:
        log.error("Unexpected SPI read error on channel %d: %s", channel, exc)
        return None


def channel_to_voltage(value, vref=3.3):
    if value is None:
        return None
    return (value / 1023.0) * vref


def update_display(device, voltages):
    if device is None:
        return
    try:
        with canvas(device) as draw:
            for i, v in enumerate(voltages):
                text = f"CH{i}: {v:.2f}V" if v is not None else f"CH{i}: ERR"
                draw.text((0, i * 10), text, fill="white")
    except OSError as exc:
        log.error("I2C/OLED write error: %s", exc)
    except Exception as exc:
        log.error("Unexpected display update error: %s", exc)


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    spi = init_spi()
    if spi is None:
        log.error("Cannot continue without SPI – aborting.")
        sys.exit(1)

    device = init_oled()
    if device is None:
        log.error("Cannot continue without OLED – aborting.")
        try:
            spi.close()
        except Exception:
            pass
        sys.exit(1)

    try:
        while _running:
            voltages = []
            for ch in range(4):
                val = read_mcp3008_channel(spi, ch)
                voltages.append(channel_to_voltage(val))

            update_display(device, voltages)
            time.sleep(SAMPLE_INTERVAL_S)
    finally:
        try:
            spi.close()
            log.info("SPI closed.")
        except Exception as exc:
            log.warning("Error closing SPI: %s", exc)
        try:
            device.cleanup()
            log.info("OLED cleaned up.")
        except Exception as exc:
            log.warning("Error cleaning up OLED: %s", exc)


if __name__ == "__main__":
    main()

