import os
import signal
import sys
import time
from PIL import Image, ImageOps

try:
    import lib.oled.oled_driver as oled_driver
except ImportError:
    print("Error: Could not import the OLED driver library.")
    sys.exit(1)


class GifPlayer:
    """
    Manages the playback of GIF animations on a Raspberry Pi connected to an ST7789 display.
    """

    def __init__(self, width=240, height=240, folder=None):
        """
        Initializes the GifPlayer.

        Args:
            width (int): The width of the display in pixels.
            height (int): The height of the display in pixels.
            folder (str): The path to the folder containing the GIF files.
        """
        self.width = width
        self.height = height
        self.folder = folder
        self.images = []
        self.display = None

        if self.folder is None:
            raise ValueError("Folder path must not be None.")

        if not os.path.isdir(self.folder):
            raise FileNotFoundError(f"Folder not found: {self.folder}")

        try:
            self.display = oled_driver.oled(width, height)
        except Exception as e:
            raise RuntimeError(f"Failed to initialize display: {e}")

        self._load_images()

    def _load_images(self):
        """Loads images from the specified folder, respecting file permissions."""
        try:
            files = [f for f in os.listdir(self.folder) if f.lower().endswith('.gif')]
            if not files:
                raise FileNotFoundError(f"No GIF files found in folder: {self.folder}")

            for filename in files:
                filepath = os.path.join(self.folder, filename)
                try:
                    img = Image.open(filepath)
                    img.verify()  # Verify it's a valid image
                    self.images.append((filename, img))
                except (IOError, OSError, ValueError) as e:
                    print(f"Warning: Could not read image {filepath}: {e}")
        except Exception as e:
            raise RuntimeError(f"Error loading images: {e}")

    def play(self):
        """
        Plays a single GIF, converting it to RGB and padding it to 24-bit color.
        """
        if not self.images:
            print("Error: No images loaded.")
            return

        try:
            img = self.images[0][1]  # Use the first image
            frame_count = img.n_frames
            if frame_count == 0:
                print("Error: Invalid GIF frame count.")
                return

            for frame_index in range(frame_count):
                img.seek(frame_index)
                rgb_img = ImageOps.colorize(img.convert('RGB'), (0, 0, 0))
                # Pad to 24-bit color (65K colors)
                padded_img = rgb_img.resize((self.width, self.height), Image.LANCZOS)
                self.display.ShowImage(padded_img, 0, 0)
                time.sleep(0.1)  # Default duration in milliseconds
        except Exception as e:
            print(f"Error playing GIF: {e}")

    def run(self):
        """
        Runs the GifPlayer in an infinite loop, cycling through all loaded GIFs.
        """
        running = True

        def signal_handler(signum, frame):
            nonlocal running
            print(f"\nReceived signal {signum}, shutting down...")
            running = False

        signal.signal(signal.SIGINT, signal_handler)
        signal.signal(signal.SIGTERM, signal_handler)

        try:
            while running:
                for image_name, image in self.images:
                    if not running:
                        break
                    print(f"Playing: {image_name}")
                    self.play()
        except Exception as e:
            print(f"Error in run loop: {e}")
        finally:
            self.cleanup()

    def cleanup(self):
        """Cleans up resources before exiting."""
        if self.display:
            try:
                self.display.clear()
            except Exception:
                pass


if __name__ == "__main__":
    gif_player = None
    try:
        gif_player = GifPlayer(folder="/home/pi/gifs")
        gif_player.run()
    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        if gif_player:
            gif_player.cleanup()

