    import smbus

I2C_BUS = 1
PCF8574_ADDR = 0x23
SENSOR_PINS = [0x00, 0x02, 0x04, 0x06, 0x08, 0x0A, 0x0C, 0x0E]
POLL_INTERVAL = 0.1
RETRY_DELAY = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _read_port(bus, port):
    try:
        return bus.read_byte_data(PCF8574_ADDR, port)
    except OSError as e:
        raise RuntimeError(f"I2C read error on port {port}: {e}")


def _check_sensors(bus):
    for idx, port in enumerate(SENSOR_PINS):
        try:
            val = _read_port(bus, port)
            if val == 0:
                print(f"Obstacle detected by sensor {idx}")
        except RuntimeError as e:
            print(f"Error reading sensor {idx}: {e}")


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = smbus.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    try:
        while _running:
            try:
                _check_sensors(bus)
            except RuntimeError as e:
                print(f"I2C communication error: {e}")
                time.sleep(RETRY_DELAY)
                continue
            time.sleep(POLL_INTERVAL)
    finally:
        if bus is not None:
            bus.close()
        print("Program terminated.")


if __name__ == "__main__":
    main()

