import signal
import sys
import time

try:
    import serial
    from serial import SerialException
except ImportError:
    print("Error: pyserial is required. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)

PORT = '/dev/ttyUSB0'
BAUD = 115200
TIMEOUT = 1.0
READ_INTERVAL = 0.5

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_temperature(ser):
    """Read one line from the serial port and return the first float, or None on error/timeout."""
    try:
        raw = ser.readline()
    except SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None

    if not raw:
        return None

    line = raw.decode('ascii', errors='replace').strip()
    if not line:
        return None

    try:
        return float(line)
    except ValueError:
        print(f"Invalid data received (not a float): {line!r}", file=sys.stderr)
        return None

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        ser = serial.Serial(
            port=PORT,
            baudrate=BAUD,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
    except SerialException as exc:
        print(f"Failed to open {PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    print(f"Listening on {PORT} @ {BAUD} baud (timeout {TIMEOUT}s). Press Ctrl+C to stop.")

    try:
        while _running:
            temp = read_temperature(ser)
            if temp is not None:
                print(f"Temperature: {temp:.1f} C")
            time.sleep(READ_INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        print("Serial port closed. Exiting.")

if __name__ == '__main__':
    main()

