import time
import logging
import signal
import smbus2

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

DHT20_I2C_ADDRESS = 0x28
DHT20_STATUS_REG = 0x00
DHT20_MEASURE_REG = 0xAC
DHT20_DATA_REG = 0xAE
DHT20_STATUS_MASK = 0x80
DHT20_TIMEOUT = 0.1
DHT20_RETRY_DELAY = 2.0
DHT20_MAX_RETRIES = 5


class DHT20:
    def __init__(self, bus_number=1, address=DHT20_I2C_ADDRESS):
        self.address = address
        self._bus = None
        self._closed = False
        try:
            self._bus = smbus2.SMBus(bus_number)
        except FileNotFoundError:
            logging.error(f"I2C bus {bus_number} not found. Enable I2C in raspi-config.")
            return
        except PermissionError:
            logging.error(f"Permission denied on I2C bus {bus_number}. Run as root or add user to i2c group.")
            return
        except OSError as e:
            logging.error(f"Failed to open I2C bus {bus_number}: {e}")
            return

        time.sleep(0.5)
        try:
            status = self._read_register(DHT20_STATUS_REG, 1)[0]
            if status & DHT20_STATUS_MASK != DHT20_STATUS_MASK:
                logging.error(f"DHT20 status check failed: got 0x{status:02X}, expected 0x{DHT20_STATUS_MASK:02X}")
                self.close()
                return
        except OSError as e:
            logging.error(f"Failed to read DHT20 status: {e}")
            self.close()
            return

        logging.info("DHT20 initialized successfully.")

    def _read_register(self, register, length):
        try:
            return self._bus.read_i2c_block_data(self.address, register, length)
        except OSError as e:
            logging.error(f"I2C read error at register 0x{register:02X}: {e}")
            raise

    def read(self):
        for attempt in range(1, DHT20_MAX_RETRIES + 1):
            try:
                data = self._read_register(DHT20_MEASURE_REG, 7)
                if len(data) < 7:
                    logging.error(f"Incomplete data read: {len(data)} bytes")
                    time.sleep(DHT20_RETRY_DELAY)
                    continue

                humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
                temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF
                temperature = (temperature_raw / 20.0) - 50.0
                humidity = (humidity_raw / 20.0) * 100.0

                crc_error = False
                calc_crc = (
                    (data[0] << 8) | data[6]
                ) ^ ((data[0] << 8) | data[6]) >> 8
                if calc_crc != data[6]:
                    logging.warning(f"CRC mismatch: calculated 0x{calc_crc:02X}, received 0x{data[6]:02X}")
                    crc_error = True

                logging.info(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %, CRC Error: {crc_error}")
                return temperature, humidity, crc_error

            except OSError as e:
                logging.error(f"I2C bus error during read: {e}")
                time.sleep(DHT20_RETRY_DELAY)

        logging.error(f"Failed to read from DHT20 after {DHT20_MAX_RETRIES} retries.")
        return None, None, True

    def close(self):
        if self._bus is not None and not self._closed:
            try:
                self._bus.close()
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")
            finally:
                self._closed = True

    def __del__(self):
        self.close()


def _signal_handler(signum, frame):
    logging.info(f"Signal {signum} received, exiting.")
    raise SystemExit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    sensor = DHT20()
    if sensor is not None:
        temp, hum, crc_err = sensor.read()
        if crc_err:
            logging.warning("CRC error detected; sensor data may be corrupt.")
        if temp is not None and hum is not None:
            print(f"Temperature: {temp:.2f} C")
            print(f"Humidity: {hum:.2f} %")
        else:
            print("Failed to read sensor data.")
    else:
        print("Sensor initialization failed.")

