import asyncio
import json
import logging
import logging.handlers
import signal
import sys
from pathlib import Path

import RPi.GPIO as GPIO

DEFAULT_CONFIG = {
    "gpio_transmitter_pin": 17,
    "gpio_dht22_pin": 4,
    "dht22_read_interval": 60,
    "log_file": "greenhouse.log",
    "outlet_configurations": [
        {"name": "fan", "system_code": "10101", "unit_code": "1"},
        {"name": "light", "system_code": "10101", "unit_code": "2"},
        {"name": "heater", "system_code": "10101", "unit_code": "3"},
    ],
}


class GreenhouseController:
    def __init__(self, config_file="greenhouse_config.json"):
        self.config_file = config_file
        self.config = self._load_config()
        self._setup_logging()
        self.outlet_configurations = self.config.get("outlet_configurations", [])
        self.dht22_read_interval = self.config.get("dht22_read_interval", 60)
        self.gpio_transmitter_pin = self.config.get("gpio_transmitter_pin", 17)
        self.gpio_dht22_pin = self.config.get("gpio_dht22_pin", 4)
        self.logger.info("GreenhouseController initialized.")

    def _load_config(self):
        try:
            with open(self.config_file, "r") as f:
                cfg = json.load(f)
            required = ["gpio_transmitter_pin", "gpio_dht22_pin", "dht22_read_interval", "log_file"]
            for key in required:
                if key not in cfg:
                    raise KeyError(f"Missing required config key: {key}")
            return cfg
        except FileNotFoundError:
            print(f"Config file not found: {self.config_file}. Using defaults.")
            return DEFAULT_CONFIG.copy()
        except (json.JSONDecodeError, KeyError) as e:
            print(f"Error loading config: {e}. Using defaults.")
            return DEFAULT_CONFIG.copy()

    def _setup_logging(self):
        log_file = self.config.get("log_file", "greenhouse.log")
        log_level = getattr(logging, self.config.get("log_level", "INFO").upper(), logging.INFO)
        handler = logging.handlers.RotatingFileHandler(
            log_file, maxBytes=1024 * 1024, backupCount=5
        )
        formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
        handler.setFormatter(formatter)
        logger = logging.getLogger()
        logger.setLevel(log_level)
        logger.addHandler(handler)
        self.logger = logger
        self.logger.info("Logging initialized.")

    def _transmit_code(self, code, retries=3, delay=0.1):
        for attempt in range(retries):
            try:
                for bit in code:
                    if bit == "1":
                        GPIO.output(self.gpio_transmitter_pin, GPIO.HIGH)
                        time.sleep(0.0003)
                        GPIO.output(self.gpio_transmitter_pin, GPIO.LOW)
                        time.sleep(0.0001)
                    elif bit == "0":
                        GPIO.output(self.gpio_transmitter_pin, GPIO.LOW)
                        time.sleep(0.0003)
                        GPIO.output(self.gpio_transmitter_pin, GPIO.HIGH)
                        time.sleep(0.0001)
                time.sleep(delay)
                return True
            except Exception as e:
                self.logger.error(f"Transmit error on code {code}: {e}")
                time.sleep(delay)
        self.logger.error(f"Failed to transmit code {code} after {retries} retries.")
        return False

    def _send_command(self, outlet_name, state):
        if outlet_name not in self.outlet_configurations:
            self.logger.error(f"Unknown outlet: {outlet_name}")
            return False
        system_code = self.outlet_configurations[outlet_name]["system_code"]
        unit_code = self.outlet_configurations[outlet_name]["unit_code"]
        code = f"{system_code}{unit_code}{'1' if state else '0'}"
        self.logger.info(f"Sending command to {outlet_name}: {code}")
        return self._transmit_code(code)

    def _read_dht22(self):
        try:
            import adafruit_dht
            import board
            dht_device = adafruit_dht.DHT22(board.D4)
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is None or humidity is None:
                raise RuntimeError("DHT22 returned None")
            return temperature, humidity
        except Exception as e:
            self.logger.error(f"DHT22 read error: {e}")
            return None, None

    async def _sensor_loop(self):
        while True:
            temperature, humidity = self._read_dht22()
            if temperature is not None and humidity is not None:
                self.logger.info(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
            else:
                self.logger.warning("Skipping sensor reading due to error.")
            try:
                await asyncio.wait_for(asyncio.sleep(self.dht22_read_interval), timeout=self.dht22_read_interval)
            except asyncio.TimeoutError:
                pass

    async def run(self):
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(self.gpio_transmitter_pin, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(self.gpio_dht22_pin, GPIO.OUT, initial=GPIO.LOW)
        self.logger.info("GPIO initialized.")
        sensor_task = asyncio.create_task(self._sensor_loop())
        try:
            while True:
                cmd = input("Enter command (on/off/status <outlet>): ").strip().lower()
                if cmd.startswith("on"):
                    outlet = cmd.split()[1]
                    if outlet in self.outlet_configurations:
                        if self._send_command(outlet, True):
                            self.logger.info(f"Turned on {outlet}.")
                        else:
                            self.logger.error(f"Failed to turn on {outlet}.")
                    else:
                        self.logger.error(f"Unknown outlet: {outlet}")
                elif cmd.startswith("off"):
                    outlet = cmd.split()[1]
                    if outlet in self.outlet_configurations:
                        if self._send_command(outlet, False):
                            self.logger.info(f"Turned off {outlet}.")
                        else:
                            self.logger.error(f"Failed to turn off {outlet}.")
                    else:
                        self.logger.error(f"Unknown outlet: {outlet}")
                elif cmd.startswith("status"):
                    outlet = cmd.split()[1]
                    if outlet in self.outlet_configurations:
                        self.logger.info(f"Status of {outlet}: {'ON' if self.outlet_configurations[outlet]['state'] else 'OFF'}")
                    else:
                        self.logger.error(f"Unknown outlet: {outlet}")
                else:
                    print("Invalid command. Use: on <outlet> | off <outlet> | status <outlet>")
