import signal
import sys
import time
import logging

try:
    import smbus2 as smbus
except ImportError:
    import smbus

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)

I2C_BUS = 1
DHT20_ADDR = 0x2c

_running = True


def _signal_handler(signum, frame):
    global _running
    logger.info('Received signal %s, shutting down...', signum)
    _running = False


class DHT20:
    def __init__(self, bus_id=I2C_BUS, address=DHT20_ADDR):
        self.address = address
        self.bus = None
        try:
            self.bus = smbus.SMBus(bus_id)
        except OSError as e:
            logger.error('Failed to open I2C bus %d: %s', bus_id, e)
            self.bus = None
            return

        try:
            status = self.bus.read_byte_data(self.address, 0x00)
        except OSError as e:
            logger.error('No DHT20 detected at 0x%02X on bus %d: %s', self.address, bus_id, e)
            self._close_bus()
            self.bus = None
            return

        if status != 0x00:
            logger.error('DHT20 status byte 0x%02X != 0x00 at 0x%02X', status, self.address)
            self._close_bus()
            self.bus = None
            return

        logger.info('DHT20 initialized at 0x%02X on bus %d', self.address, bus_id)

    def _close_bus(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except OSError:
                pass
            self.bus = None

    def _read_register(self, reg, length=1):
        if self.bus is None:
            return None
        try:
            return self.bus.read_i2c_block_data(self.address, reg, length)
        except OSError as e:
            logger.warning('I2C read error at reg 0x%02X: %s', reg, e)
            return None

    def measure(self):
        if self.bus is None:
            return None, None, True

        data = self._read_register(0xac, 7)
        if data is None or len(data) < 7:
            logger.warning('Incomplete data from DHT20')
            return None, None, True

        if (data[0] & 0x18) != 0x18:
            logger.warning('DHT20 not ready (status 0x%02X)', data[0])
            return None, None, True

        humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
        temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF

        crc_error = False
        calc_crc = (data[0] & 0x07) ^ ((data[1] + data[2] + data[3] + data[4] + data[5]) & 0xFF)
        if calc_crc != (data[6] & 0xFF):
            logger.warning('CRC mismatch: calc=0x%02X, recv=0x%02X', calc_crc, data[6])
            crc_error = True

        humidity = humidity_raw / 2**20 * 100.0
        temperature = temperature_raw / 2**20 * 200.0 - 50.0

        return temperature, humidity, crc_error

    def close(self):
        self._close_bus()


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    sensor = DHT20()
    if sensor.bus is None:
        logger.error('Sensor initialization failed; exiting.')
        sys.exit(1)

    try:
        if not _running:
            return
        temperature, humidity, crc_error = sensor.measure()
        if crc_error or temperature is None or humidity is None:
            logger.error('Measurement failed: %s', 'CRC error' if crc_error else 'sensor not ready')
        else:
            logger.info('Temperature: %.2f C  Humidity: %.2f %%', temperature, humidity)
    finally:
        sensor.close()


if __name__ == '__main__':
    main()

