import time
import signal
import sys
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_i2c():
    """Initialize the I2C bus on board.SCL (GPIO3) and board.SDA (GPIO2)."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        # Probe the bus to verify it is actually functional
        while not i2c_bus.try_lock():
            pass
        try:
            devices = i2c_bus.scan()
        finally:
            i2c_bus.unlock()
        if not devices:
            print("Error: No I2C devices detected on the bus.")
            i2c_bus.deinit()
            return None
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_multiplexer(i2c_bus):
    """Initialize the TCA9548A I2C multiplexer."""
    try:
        return adafruit_tca9548a.TCA9548A(i2c_bus)
    except Exception as e:
        print(f"Error initializing TCA9548A multiplexer: {e}")
        return None

def initialize_sensors(multiplexer):
    """Initialize BME280 and TSL2591 sensors via the multiplexer."""
    sensors = {}
    try:
        sensors['bme280'] = adafruit_bme280.Adafruit_BME280_I2C(multiplexer[0], address=0x76)
    except Exception as e:
        print(f"Error initializing BME280 sensor: {e}")
    try:
        sensors['tsl2591'] = adafruit_tsl2591.TSL2591(multiplexer[1], address=0x29)
    except Exception as e:
        print(f"Error initializing TSL2591 sensor: {e}")
    return sensors

def read_sensor_data(sensors):
    """Read temperature, humidity, and light intensity from the sensors."""
    temp = None
    humidity = None
    light = None
    try:
        temp = sensors['bme280'].temperature
        humidity = sensors['bme280'].humidity
    except Exception as e:
        print(f"Error reading BME280 data: {e}")
    try:
        light = sensors['tsl2591'].lux
    except Exception as e:
        print(f"Error reading TSL2591 data: {e}")
    return temp, humidity, light

def display_sensor_data(temperature, humidity, light):
    """Print the sensor readings to the console."""
    print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %, Light: {light:.2f} lux")

def main():
    """Main function to read and display sensor data."""
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        i2c_bus.deinit()
        sys.exit(1)

    sensors = initialize_sensors(multiplexer)
    if not sensors:
        print("Error: No sensors initialized. Exiting.")
        i2c_bus.deinit()
        sys.exit(1)

    print("Starting sensor readings. Press Ctrl+C to exit.")
    try:
        while _running:
            temperature, humidity, light = read_sensor_data(sensors)
            if temperature is not None and humidity is not None and light is not None:
                display_sensor_data(temperature, humidity, light)
            time.sleep(2)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        print("\nExiting program.")
        i2c_bus.deinit()

if __name__ == "__main__":
    main()

