import time
import logging
import random
import signal
import sys

try:
    from gpiozero import Servo
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero")
    sys.exit(1)

# Configure logging to a file named greenhouse_vent.log at INFO level
logging.basicConfig(
    filename='greenhouse_vent.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

SERVO_PIN_1 = 17
SERVO_PIN_2 = 18

# Global references for cleanup
servo1 = None
servo2 = None


def cleanup():
    """Stop PWM and release GPIO resources."""
    global servo1, servo2
    try:
        if servo1 is not None:
            servo1.close()
            logging.info("Servo 1 closed.")
    except Exception as e:
        logging.error(f"Error closing servo 1: {e}")
    try:
        if servo2 is not None:
            servo2.close()
            logging.info("Servo 2 closed.")
    except Exception as e:
        logging.error(f"Error closing servo 2: {e}")


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    logging.info(f"Received signal {signum}, shutting down.")
    cleanup()
    sys.exit(0)


def get_temperature():
    """Simulate a temperature reading between 15 and 35 degrees Celsius."""
    base_temp = random.uniform(15, 35)
    fluctuation = random.uniform(-2, 2)
    return base_temp + fluctuation


def map_temperature_to_angle(temperature):
    """Map temperature to servo angle: <20°C→0°, 20-25°→45°, 25-30°→90°, 30-35°→135°, ≥35°→180°."""
    if temperature < 20:
        return 0
    elif temperature < 25:
        return 45
    elif temperature < 30:
        return 90
    elif temperature < 35:
        return 135
    else:
        return 180


def move_servo(servo, angle, delay=0.1):
    """Move servo to specified angle in 5-degree steps with 0.1s delay between steps."""
    try:
        current_angle = servo.angle or 0
        step = 5 if angle > current_angle else -5
        for i in range(int(abs(angle - current_angle)) // 5 + 1):
            new_angle = current_angle + (step * i)
            servo.angle = new_angle
            time.sleep(delay)
