import time
import json
import urllib.request
import urllib.error
import signal
import sys
import random
import os

try:
    import adafruit_dht
    import board
except ImportError:
    print("Missing dependencies. Install with:")
    print("  pip install adafruit-circuitpython-dht")
    print("  sudo apt-get install libgpiod2")
    sys.exit(1)

CONFIG_FILE = "config.json"

running = True

def signal_handler(signum, frame):
    global running
    running = False

def load_config(path):
    try:
        with open(path, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Config file not found: {path}. Using defaults.")
    except json.JSONDecodeError as e:
        print(f"Error decoding JSON from {path}: {e}. Using defaults.")
    return {}

def read_sensor(dht_device):
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None")
        return temperature, humidity
    except RuntimeError as e:
        print(f"Sensor read error: {e}. Simulating data.")
        temperature = round(random.uniform(20, 30), 1)
        humidity = round(random.uniform(60, 80), 1)
        return temperature, humidity
    except Exception as e:
        print(f"Unexpected sensor error: {e}. Simulating data.")
        temperature = round(random.uniform(20, 30), 1)
        humidity = round(random.uniform(60, 80), 1)
        return temperature, humidity

def validate_data(temperature, humidity):
    if not (-40 <= temperature <= 80):
        print(f"Invalid temperature: {temperature}°C. Simulating data.")
        temperature = round(random.uniform(20, 30), 1)
    if not (0 <= humidity <= 100):
        print(f"Invalid humidity: {humidity}%. Simulating data.")
        humidity = round(random.uniform(60, 80), 1)
    return temperature, humidity

def send_webhook(url, data):
    try:
        data_bytes = data.encode("utf-8")
        req = urllib.request.Request(url, data=data_bytes, headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=10) as response:
            if 200 <= response.status < 300:
                print("Webhook sent successfully.")
                return True
            else:
                print(f"Webhook failed with status code: {response.status}")
                return False
    except urllib.error.URLError as e:
        print(f"Webhook URL error: {e}")
        return False
    except Exception as e:
        print(f"Webhook error: {e}")
        return False

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config(CONFIG_FILE)
    webhook_url = config.get("webhook_url", "")
    if not webhook_url:
        print("Error: webhook_url is not configured in config.json.")
        sys.exit(1)

    pin = board.D4
    dht_device = None
    try:
        dht_device = adafruit_dht.DHT22(pin, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT22 on pin 4: {e}")
        sys.exit(1)

    moving_average_window = 5
    sensor_data = []
    max_consecutive_failures = 3
    backoff_intervals = [1, 3, 9]

    try:
        while running:
            temperature, humidity = read_sensor(dht_device)
            temperature, humidity = validate_data(temperature, humidity)

            sensor_data.append((temperature, humidity))
            if len(sensor_data) > moving_average_window:
                sensor_data.pop(0)

            moving_average_temperature = sum(t for t, _ in sensor_data) / len(sensor_data)
            moving_average_humidity = sum(h for _, h in sensor_data) / len(sensor_data)

            data = {
                "temperature": round(moving_average_temperature, 1),
                "humidity": round(moving_average_humidity, 1),
                "timestamp": time.strftime("%Y-%m-%dT%H:%M:%SZ")
            }

            if webhook_url:
                send_webhook(webhook_url, json.dumps(data))

            if not send_webhook(webhook_url, json.dumps(data)):
                consecutive_failures = sum(1 for _ in backoff_intervals)
                if consecutive_failures > max_consecutive_failures:
                    print("Too many webhook failures. Pausing sensor acquisition for 300 seconds.")
                    time.sleep(300)
                    consecutive_failures = 0
                    backoff_intervals = [1, 3, 9]
                else:
                    print(f"Webhook failed. Retrying in {backoff_intervals[consecutive_failures]} seconds...")
                    time.sleep(backoff_intervals[consecutive_failures])
                    consecutive_failures += 1

            time.sleep(60)

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if dht_device:
            try:
                dht_device.exit()
            except Exception:
                pass
        print("Program terminated gracefully.")

if __name__ == "__main__":
    main()

