import sys
import time
import threading
import numpy as np
import matplotlib.pyplot as plt
import matplotlib.animation as animation

try:
    import thermal_reader as tr
except ImportError:
    print("Error: thermal_reader.py not found. Please install or create it.", file=sys.stderr)
    sys.exit(1)


class ThermalCamera:
    """
    Reads thermal data from a UART-connected thermal camera and displays a live heatmap.
    """

    def __init__(self, port='/dev/ttyS0', baudrate=9600, timeout=1.0, frame_width=32, frame_height=24):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.frame_width = frame_width
        self.frame_height = frame_height
        self.data_queue = None
        self.sensor = None
        self.fig = None
        self.ax = None
        self.im = None
        self.cbar = None
        self.ani = None
        self.stop_event = threading.Event()
        self.read_thread = None

    def initialize_sensor(self):
        """Initializes the thermal camera sensor object."""
        try:
            self.sensor = tr.ThermalReader(self.port, self.baudrate, self.timeout)
        except Exception as e:
            print(f"Error initializing thermal camera: {e}", file=sys.stderr)
            self.sensor = None
            return False
        return True

    def start_sensor_reading(self):
        """Starts the thermal camera reading in a separate thread."""
        if self.sensor is None:
            print("Error: Cannot start reading without an initialized sensor.", file=sys.stderr)
            return False
        self.stop_event.clear()
        self.read_thread = threading.Thread(target=self._sensor_reading_loop, daemon=True)
        self.read_thread.start()
        return True

    def stop_sensor_reading(self):
        """Stops the thermal camera reading."""
        self.stop_event.set()
        if self.read_thread is not None and self.read_thread.is_alive():
            self.read_thread.join(timeout=2.0)

    def _sensor_reading_loop(self):
        """Continuously reads thermal data from the sensor and puts it in the queue."""
        while not self.stop_event.is_set():
            try:
                data = self.sensor.read()
                if data is not None:
                    try:
                        self.data_queue.put(data, timeout=1.0)
                    except Exception as e:
                        print(f"Error putting data into queue: {e}", file=sys.stderr)
            except Exception as e:
                print(f"Error reading from thermal camera: {e}", file=sys.stderr)
                self.stop_event.set()
                break
            time.sleep(0.1)

    def initialize_display(self):
        """Initializes the Matplotlib figure and animation."""
        self.fig, self.ax = plt.subplots()
        self.im = self.ax.imshow(np.zeros((self.frame_height, self.frame_width)), cmap='inferno', interpolation='nearest', vmin=20, vmax=40)
        self.cbar = self.fig.colorbar(self.im, ax=self.ax, label='Temperature')
        self.fig.canvas.draw()
        self.fig.canvas.flush_events()
        self.ani = animation.FuncAnimation(
            self.fig,
            self._update_callback,
            interval=100,
            blit=False,
            cache_frame_data=False
        )

    def _update_callback(self, frame):
        """Callback for the animation loop."""
        if self.data_queue.empty():
            return self.im,
        try:
            data = self.data_queue.get(timeout=1.0)
            if data is None:
                return self.im,
            if len(data) != (self.frame_height * self.frame_width):
                print(f"Warning: Malformed data frame (expected {self.frame_height * self.frame_width}, got {len(data)}). Skipping.", file=sys.stderr)
                self.data_queue.task_done()
                return self.im,
            self.im.set_data(np.array(data).reshape((self.frame_height, self.frame_width)))
            self.cbar.set_label('Temperature')
            self.fig.canvas.draw_idle()
            self.fig.canvas.flush_events()
            return self.im,
        except Exception as e:
            print(f"Error updating display: {e}", file=sys.stderr)
            return self.im,

    def run(self):
        """Runs the thermal camera application."""
        if not self.initialize_sensor():
            return
        self.data_queue = mp.Queue()
        if not self.start_sensor_reading():
            self.stop_sensor_reading()
            return
        self.initialize_display()
        try:
            plt.show()
        except KeyboardInterrupt:
            print("\nExiting program.")
        finally:
            self.stop_sensor_reading()
            if self.fig is not None:
                plt.close(self.fig)


if __name__ == "__main__":
    app = ThermalCamera()
    app.run()

