import time
import signal
import sys
import board
import adafruit_dht

# Global sensor handle so the signal handler can release it.
_sensor = None

def _cleanup():
    """Release the sensor if it was created."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None

def _handle_signal(signum, frame):
    """Handle SIGTERM/SIGINT for clean shutdown."""
    print(f"\nReceived signal {signum}, exiting.")
    _cleanup()
    sys.exit(0)

def main():
    global _sensor

    # Register signal handlers for graceful termination.
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize the DHT11 sensor on board.D4 (BCM pin 4, physical pin 7).
    try:
        _sensor = adafruit_dht.DHT11(board.D4, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT11 sensor on board.D4: {e}")
        _cleanup()
        sys.exit(1)

    try:
        while True:
            try:
                temperature = _sensor.temperature
                humidity = _sensor.humidity

                if temperature is not None and humidity is not None:
                    print(f"Temperature: {temperature:.1f} C  Humidity: {humidity:.1f} %")
                else:
                    print("Sensor returned None for temperature or humidity.")

            except RuntimeError as e:
                # Common DHT11 transient errors: checksum, timeout, or read failure.
                print(f"Sensor read error: {e}")

            time.sleep(5)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        _cleanup()

if __name__ == "__main__":
    main()

