try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

HEATER_PIN = 17
ITERATIONS = 5
DELAY_SECONDS = 2

heater = None

def cleanup():
    """Ensure the heater is turned off and resources are released."""
    global heater
    if heater is not None:
        try:
            heater.off()
            heater.close()
        except Exception:
            pass
        heater = None

def signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for clean shutdown."""
    print(f"\nReceived signal {signum}. Cleaning up...")
    cleanup()
    sys.exit(0)

def read_temp():
    """Simulate a temperature reading between 10 and 29 degrees Celsius."""
    return random.randint(10, 29)

def main():
    global heater

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize the heater pin as a digital output
    try:
        heater = OutputDevice(HEATER_PIN)
    except GPIOZeroError as e:
        print(f"Error: Failed to initialize GPIO pin {HEATER_PIN}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing GPIO pin {HEATER_PIN}: {e}")
        sys.exit(1)

    try:
        for i in range(ITERATIONS):
            temperature = read_temp()
            print(f"[{i + 1}/{ITERATIONS}] Temperature: {temperature}°C")

            if temperature < 20:
                heater.on()
                print("Heater ON")
            else:
                heater.off()
                print("Heater OFF")

            if i < ITERATIONS - 1:
                time.sleep(DELAY_SECONDS)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"Unexpected error during execution: {e}")
    finally:
        cleanup()
        print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

