import time
import signal
import sys
import logging
from datetime import datetime

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

DHT_PIN = 17
FAN_PIN = 18
LOG_FILE = 'urban_data_log.txt'
TEMP_THRESHOLD = 30.0
HUM_THRESHOLD = 70.0
READ_INTERVAL = 2.0
NUM_READINGS = 5

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_logging():
    logging.basicConfig(
        filename=LOG_FILE,
        level=logging.INFO,
        format='%(asctime)s - %(message)s',
        datefmt='%Y-%m-%dT%H:%M:%S'
    )

def read_dht11(pin):
    if GPIO is None:
        return None, None
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.IN)
    time.sleep(0.2)
    try:
        GPIO.setup(pin, GPIO.OUT)
        GPIO.output(pin, GPIO.LOW)
        time.sleep(0.018)
        GPIO.output(pin, GPIO.HIGH)
        time.sleep(0.00004)
        GPIO.setup(pin, GPIO.IN)
        value = GPIO.input(pin)
        if value not in (48, 49, 50, 51):
            return None, None
        time.sleep(0.08)
        value = GPIO.input(pin)
        if value not in (48, 49, 50, 51):
            return None, None
        humidity = GPIO.input(pin)
        if humidity not in (48, 49, 50, 51):
            return None, None
        temp = GPIO.input(pin)
        if temp not in (48, 49, 50, 51):
            return None, None
        humidity = (humidity - 48) * 100.0 / 10.0
        temp = (temp - 48) * 100.0 / 10.0
        return temp, humidity
    except Exception:
        return None, None

def log_data(temp, humidity):
    if temp is not None and humidity is not None:
        logging.info(f'Temperature: {temp:.1f}C, Humidity: {humidity:.1f}%')
    else:
        logging.error('Sensor read failed.')

def control_fan(pin, temp, humidity):
    if GPIO is None:
        return
    GPIO.setup(pin, GPIO.OUT)
    fan_on = GPIO.input(pin)
    if temp is not None and temp > TEMP_THRESHOLD or humidity is not None and humidity > HUM_THRESHOLD:
        GPIO.output(pin, GPIO.HIGH)
    else:
        GPIO.output(pin, GPIO.LOW)
    return fan_on

def cleanup():
    if GPIO is not None:
        try:
            GPIO.cleanup()
        except Exception:
            pass

def main():
    setup_logging()
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    fan_on = False
    try:
        for i in range(NUM_READINGS):
            if not _running:
                break
            temp, humidity = read_dht11(DHT_PIN)
            log_data(temp, humidity)
            fan_on = control_fan(FAN_PIN, temp, humidity)
            status = 'Fan ON' if fan_on else 'Fan OFF'
            print(f'Reading {i + 1}/{NUM_READINGS} - Temp: {temp if temp is not None else "N/A"}C, Humidity: {humidity if humidity is not None else "N/A"}%, {status}')
            if i < NUM_READINGS - 1 and _running:
                time.sleep(READ_INTERVAL)
    except Exception as e:
        logging.error(f'Unexpected error: {e}')
    finally:
        cleanup()
        print('Program finished.')

if __name__ == '__main__':
    main()

