#!/usr/bin/env python3
"""
BMP280 altitude logger for Raspberry Pi 3/4/5.

Wiring:
  BMP280 SDA -> GPIO2 (pin 3)
  BMP280 SCL -> GPIO3 (pin 5)
  BMP280 VCC -> 3.3 V
  BMP280 GND -> GND

Reads pressure (hPa) and altitude (m) every second, logs to
altitude_log.txt, and prints to stdout.  Uses time.monotonic()
for the loop so drift does not accumulate.
"""

import sys
import time
import signal

try:
    import board
    import busio
    import adafruit_bmp280
except ImportError as exc:
    print(f"Missing dependency: {exc}", file=sys.stderr)
    print("Install with: pip install adafruit-circuitpython-bmp280", file=sys.stderr)
    sys.exit(1)

LOG_FILE = "altitude_log.txt"
SEA_LEVEL_PRESSURE_HPA = 1013.25
READ_INTERVAL_S = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _print_values(pressure_hpa, altitude_m):
    print(f"Pressure: {pressure_hpa:.2f} hPa, Altitude: {altitude_m:.2f} meters")


def _log_entry(pressure_hpa, altitude_m):
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    line = f"{timestamp} – Pressure: {pressure_hpa:.2f} hPa, Altitude: {altitude_m:.2f} meters\n"
    try:
        with open(LOG_FILE, "a", encoding="utf-8") as fh:
            fh.write(line)
    except OSError as exc:
        print(f"Warning: could not write to {LOG_FILE}: {exc}", file=sys.stderr)


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Error: failed to initialize I2C bus: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        bmp = adafruit_bmp280.Adafruit_BMP280_I2C(i2c, address=0x76)
    except Exception as exc:
        print(f"Error: BMP280 not found on I2C bus (address 0x76): {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        bmp.sea_level_pressure = SEA_LEVEL_PRESSURE_HPA
    except Exception as exc:
        print(f"Warning: could not set sea_level_pressure: {exc}", file=sys.stderr)

    print("BMP280 altitude logger started. Press Ctrl+C to stop.")

    try:
        while _running:
            try:
                pressure_hpa = bmp.pressure
                altitude_m = bmp.altitude

                if pressure_hpa is None or altitude_m is None:
                    print("Warning: sensor returned None for pressure or altitude.", file=sys.stderr)
                else:
                    _print_values(pressure_hpa, altitude_m)
                    _log_entry(pressure_hpa, altitude_m)

            except OSError as exc:
                print(f"Warning: I2C read error: {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Warning: unexpected sensor error: {exc}", file=sys.stderr)

            time.sleep(READ_INTERVAL_S)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        print("Exiting cleanly.")


if __name__ == "__main__":
    main()

