import time
import logging
import signal
import sys
from typing import Optional, Tuple

try:
    import smbus2 as _smbus2
except ImportError:
    _smbus2 = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    """Driver for the Aosong DHT20 I2C temperature/humidity sensor."""

    DHT20_ADDRESS = 0x50
    STATUS_REG = 0x00
    MEASURE_REG = 0xAC
    DATA_REG = 0xAD

    def __init__(self, bus_number: int = 1, device_address: int = DHT20_ADDRESS):
        if _smbus2 is None:
            raise RuntimeError("smbus2 library is required. Install with: pip install smbus2")
        self._i2c_bus_number = bus_number
        self._device_address = device_address
        self._bus: Optional[_smbus2.SMBus] = None
        self._running = True
        self._last_read_time: float = 0.0
        self._min_interval = 2.0
        self._init_bus()

    def _init_bus(self) -> None:
        try:
            self._bus = _smbus2.SMBus(self._i2c_bus_number)
            logger.info("DHT20 initialized on I2C bus %d at address 0x%02X", self._i2c_bus_number, self._device_address)
        except OSError as e:
            logger.error("Failed to open I2C bus %d: %s", self._i2c_bus_number, e)
            self._bus = None
            raise

    def _read_register(self, register: int, length: int) -> Optional[bytes]:
        if self._bus is None:
            logger.error("I2C bus is not initialized")
            return None
        try:
            return self._bus.read_i2c_block_data(self._device_address, register, length)
        except OSError as e:
            logger.warning("I2C read error (reg 0x%02X): %s", register, e)
            return None

    def _write_register(self, register: int, data: bytes) -> bool:
        if self._bus is None:
            logger.error("I2C bus is not initialized")
            return False
        try:
            self._bus.write_i2c_block_data(self._device_address, register, data)
            return True
        except OSError as e:
            logger.warning("I2C write error (reg 0x%02X): %s", register, e)
            return False

    def _crc8(self, data: bytes) -> bool:
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc == 0x00

    def _wait_for_ready(self, timeout: float = 1.0) -> bool:
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            status = self._read_register(self.STATUS_REG, 1)
            if status is None:
                return False
            if not (status[0] & 0x80):
                return True
            time.sleep(0.08)
        logger.warning("DHT20 not ready within timeout")
        return False

    def _measure_once(self) -> Optional[bytes]:
        if not self._wait_for_ready():
            return None
        if not self._write_register(self.MEASURE_REG, b'\x00'):
            return None
        time.sleep(0.01)
        data = self._read_register(self.DATA_REG, 7)
        if data is None or len(data) < 7:
            logger.warning("Incomplete data read from DHT20")
            return None
        if not self._crc8(data[:6]):
            logger.warning("CRC mismatch from DHT20: 0x%02X", data[6])
            return None
        return data

    def get_temperature_and_humidity(self) -> Tuple[Optional[float], Optional[float], bool]:
        now = time.monotonic()
        if now - self._last_read_time < self._min_interval:
            logger.debug("Rate limiting: %.2f s elapsed since last read", now - self._last_read_time)
            return self._last_read_result if self._last_read_result else (None, None, True)
        self._last_read_time = now
        for attempt in range(5):
            data = self._measure_once()
            if data is None:
                time.sleep(0.01)
                continue
            humidity = (data[0] << 12) | (data[1] << 4) | ((data[2] & 0xF0) >> 4)
