import time
import json
import logging
import threading
import urllib.request
import urllib.error
import signal
import sys

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.")
    sys.exit(1)

# Configuration
DHT_PIN = 4
LED_PINS = {
    'red1': 17, 'green1': 22, 'blue1': 27,
    'red2': 5, 'green2': 6, 'blue2': 13,
    'red3': 19, 'green3': 26, 'blue3': 16
}
PWM_FREQUENCY = 1000
CLOUD_ENDPOINT = "http://example.com/api/data"
SAFE_TEMP_MIN = 18
SAFE_TEMP_MAX = 28
SAFE_HUMIDITY_MIN = 30
SAFE_HUMIDITY_MAX = 80
READ_INTERVAL = 5
UPLOAD_INTERVAL = 60
MAX_RETRIES = 3
RETRY_DELAY = 2

# Logging setup
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler("greenhouse.log"),
        logging.StreamHandler()
    ]
)

# Global state
temperature = None
humidity = None
last_temperature = None
last_humidity = None
running = True

# PWM objects
pwm_objects = {}


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global running
    logging.info(f"Received signal {signum}, shutting down...")
    running = False


def setup_gpio():
    """Initialize GPIO pins and PWM channels."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for name, pin in LED_PINS.items():
        GPIO.setup(pin, GPIO.OUT)
        pwm = GPIO.PWM(pin, PWM_FREQUENCY)
        pwm.start(0)
        pwm_objects[name] = pwm
    logging.info("GPIO setup complete.")


def set_led_color(red, green, blue):
    """Set RGB LED color using PWM duty cycles (0-100)."""
    pwm_objects['red1'].ChangeDutyCycle(max(0, min(100, red)))
    pwm_objects['green1'].ChangeDutyCycle(max(0, min(100, green)))
    pwm_objects['blue1'].ChangeDutyCycle(max(0, min(100, blue)))
    pwm_objects['red2'].ChangeDutyCycle(max(0, min(100, red)))
    pwm_objects['green2'].ChangeDutyCycle(max(0, min(100, green)))
    pwm_objects['blue2'].ChangeDutyCycle(max(0, min(100, blue)))
    pwm_objects['red3'].ChangeDutyCycle(max(0, min(100, red)))
    pwm_objects['green3'].ChangeDutyCycle(max(0, min(100, green)))
    pwm_objects['blue3'].ChangeDutyCycle(max(0, min(100, blue)))


def set_led_brightness(brightness):
    """Set LED brightness (0-100) on all channels."""
    set_led_color(brightness, brightness, brightness)


def read_dht22():
    """Read temperature and humidity from DHT22 with retries."""
    global temperature, humidity
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            import adafruit_dht
            sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
            temperature = sensor.temperature
            humidity = sensor.humidity
            sensor.exit()
            if temperature is not None and humidity is not None:
                logging.info(f"DHT22 read successful: Temp={temperature:.1f}C, Humidity={humidity:.1f}%")
                return True
            else:
                logging.warning(f"DHT22 read attempt {attempt} returned None values.")
        except RuntimeError as e:
            logging.warning(f"DHT22 read attempt {attempt} failed: {e}")
        except Exception as e:
            logging.error(f"Unexpected error reading DHT22: {e}")
        if attempt < MAX_RETRIES:
            time.sleep(RETRY_DELAY)
    logging.error("DHT22 read failed after all retries.")
    return False


def map_temperature_to_color(temp):
    """Map temperature to RGB color tuple (0-255)."""
    if temp is None:
        return (0, 0, 0)
    if temp <= SAFE_TEMP_MIN:
        return (255, 0, 0)   # Red - Cold
    elif temp >= SAFE_TEMP_MAX:
        return (0, 255, 0)   # Green - Hot
    else:
        return ((temp - SAFE_TEMP_MIN) * 255 / (SAFE_TEMP_MAX - SAFE_TEMP_MIN),
                (255 - ((temp - SAFE_TEMP_MIN) * 255 / (SAFE_TEMP_MAX - SAFE_TEMP_MIN))) * 2,
                0)


def map_humidity_to_brightness(humidity):
    """Map humidity to LED brightness (0-100)."""
    if humidity is None:
        return 0
    if humidity <= SAFE_HUMIDITY_MIN:
        return 0
    elif humidity >= SAFE_HUMIDITY_MAX:
        return 100
    else:
        return int((humidity - SAFE_HUMIDITY_MIN) * 100 / (SAFE_HUMIDITY_MAX - SAFE_HUMIDITY_MIN))


def check_alerts():
    """Determine alert status based on readings."""
    if temperature is None or humidity is None:
        return None
    if temperature > SAFE_TEMP_MAX:
        return "status: Temperature Alert"
    if temperature < SAFE_TEMP_MIN:
        return "status: Temperature Alert"
    if humidity < SAFE_HUMIDITY_MIN:
        return "status: Humidity Alert"
    if humidity > SAFE_HUMIDITY_MAX:
        return "status: Humidity Alert"
    return None


def upload_data():
    """Upload sensor data to cloud endpoint in a separate thread."""
    payload = {
        "temperature": temperature,
        "humidity": humidity,
        "color": map_temperature_to_color(temperature),
        "brightness": map_humidity_to_brightness(humidity),
        "alert": check_alerts()
    }
    try:
        data = json.dumps(payload).encode('utf-8')
        req = urllib.request.Request(
            CLOUD_ENDPOINT,
            data=data,
            headers={'Content-Type': 'application/json'}
        )
        with urllib.request.urlopen(req, timeout=10) as response:
            logging.info(f"Data uploaded. Status code: {response.status}")
    except urllib.error.URLError as e:
        logging.error(f"Network error uploading data: {e}")
    except Exception as e:
        logging.error(f"Unexpected error uploading data: {e}")


def cleanup():
    """Clean up GPIO resources."""
    logging.info("Cleaning up GPIO...")
    for pwm in pwm_objects.values():
        pwm.stop()
    GPIO.cleanup()
    logging.info("GPIO cleanup complete.")


def main():
    """Main program loop."""
    global last_temperature, last_humidity, running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        setup_gpio()
        while running:
            read_dht22()

            if temperature is not None and humidity is not None:
                last_temperature = temperature
                last_humidity = humidity
            else:
                temperature = last_temperature
                humidity = last_humidity

            set_led_color(*map_temperature_to_color(temperature))
            set_led_brightness(map_humidity_to_brightness(humidity))

            alert = check_alerts()
            if alert:
                logging.warning(alert)

            threading.Thread(target=upload_data, daemon=True).start()

            for _ in range(READ_INTERVAL):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        logging.error(f"Fatal error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

