    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

FAN_PIN = 17
PWM_FREQ = 25.0
TEMP_FILE = "/sys/class/thermal/thermal_zone0/temp"
HYSTERESIS = 1.0
POLL_INTERVAL = 1.0

running = True


def handle_signal(signum, frame):
    global running
    logger.info("Received signal %s, shutting down...", signum)
    running = False


def read_cpu_temp():
    try:
        with open(TEMP_FILE, "r") as f:
            return float(f.read().strip()) / 1000.0
    except (IOError, OSError, ValueError) as e:
        logger.error("Error reading CPU temperature: %s", e)
        return None


def compute_duty(temp):
    if temp <= 25.0:
        return 0.0
    if temp >= 35.0:
        return 100.0
    return (temp - 25.0) / (35.0 - 25.0) * 100.0


def main():
    global running

    signal.signal(signal.SIGTERM, handle_signal)
    signal.signal(signal.SIGINT, handle_signal)

    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except Exception as e:
        logger.error("Failed to initialize PWM on GPIO%d: %s", FAN_PIN, e)
        sys.exit(1)

    current_speed = 0.0

    try:
        while running:
            temp = read_cpu_temp()
            if temp is None:
                time.sleep(POLL_INTERVAL)
                continue

            logger.info("CPU Temperature: %.1f°C", temp)

            if temp < (current_speed - HYSTERESIS):
                current_speed = 0.0
            elif temp > (current_speed + HYSTERESIS):
                current_speed = 100.0

            if current_speed != fan.value * 100.0:
                fan.value = current_speed / 100.0
                logger.info("Fan speed set to %.0f%%", current_speed)

            time.sleep(POLL_INTERVAL)

    except Exception as e:
        logger.error("Unexpected error: %s", e)
    finally:
        try:
            fan.value = 0.0
            fan.close()
            logger.info("Fan stopped and GPIO released.")
        except Exception as e:
            logger.error("Error during cleanup: %s", e)


if __name__ == "__main__":
    main()

