import subprocess
import time
import signal
import sys
import logging

try:
    from gpiozero import PWMOutputDevice
except ImportError:
    print("gpiozero is required: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("fanctl")

FAN_PIN = 14
PWM_FREQ = 100.0
UPDATE_INTERVAL = 5.0
DEFAULT_DUTY = 100.0

_running = True


def _handle_signal(signum, frame):
    global _running
    log.info("Received signal %s, shutting down...", signum)
    _running = False


def get_cpu_temp():
    """Return CPU temperature in °C, or None on error."""
    try:
        result = subprocess.run(
            ["vcgencmd", "measure_temp"],
            capture_output=True,
            text=True,
            timeout=5,
        )
    except FileNotFoundError:
        log.error("vcgencmd not found on PATH.")
        return None
    except subprocess.TimeoutExpired:
        log.error("vcgencmd timed out.")
        return None
    except Exception as exc:
        log.error("Unexpected error invoking vcgencmd: %s", exc)
        return None

    if result.returncode != 0:
        log.error("vcgencmd failed (rc=%d): %s", result.returncode, result.stderr.strip())
        return None

    out = result.stdout.strip()
    if not out.startswith("temp="):
        log.error("Unexpected vcgencmd output: %r", out)
        return None

    try:
        temp_str = out.split("=", 1)[1].split("'")[0]
        return float(temp_str)
    except (IndexError, ValueError) as exc:
        log.error("Failed to parse temperature from: %r", out)
        return None


def duty_for_temp(temp_c):
    """Map temperature to a fan duty cycle (0.0–100.0 %)."""
    if temp_c is None:
        return DEFAULT_DUTY
    if temp_c <= 50.0:
        return 100.0
    if temp_c <= 60.0:
        return 85.0
    if temp_c <= 65.0:
        return 70.0
    if temp_c <= 70.0:
        return 55.0
    return 40.0


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except Exception as exc:
        log.error("Failed to initialize PWM on GPIO%d: %s", FAN_PIN, exc)
        sys.exit(1)

    current_duty = DEFAULT_DUTY

    try:
        while _running:
            temp = get_cpu_temp()
            duty = duty_for_temp(temp)

            if temp is not None:
                current_duty = duty
                log.info("CPU temp: %.1f °C -> fan duty: %.0f%%", temp, duty)
            else:
                log.warning(
                    "Temperature unavailable; retaining last duty cycle: %.0f%%",
                    current_duty,
                )

            try:
                fan.value = duty / 100.0
            except Exception as exc:
                log.error("Failed to update PWM duty cycle: %s", exc)

            time.sleep(UPDATE_INTERVAL)
    finally:
        try:
            fan.value = 0.0
            fan.close()
        except Exception:
            pass
        log.info("Fan control stopped; GPIO released.")


if __name__ == "__main__":
    main()

