import time
import signal
import sys
import logging
import subprocess
from functools import partial

try:
    from gpiozero import PWMOutputDevice
except ImportError:
    print("gpiozero is required. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s"
)


class PWMFanController:
    """
    Controls a 4-pin PWM fan on a Raspberry Pi based on CPU temperature.
    """

    def __init__(
        self,
        fan_pin: int = 14,
        pwm_frequency: int = 100,
        temp_check_interval: int = 5,
        temp_files: tuple = (vcgencmd_temp, sysfs_temp),
        temp_offset: float = 0.0,
    ):
        self.fan_pin = fan_pin
        self.pwm_frequency = pwm_frequency
        self.temp_check_interval = temp_check_interval
        self.temp_files = temp_files
        self.temp_offset = temp_offset
        self.fan_speed_steps = [
            (0, 40), (40, 60), (60, 80), (80, 100),
        ]
        self.fan_speed_increments = [
            (0, 10), (10, 20), (20, 30), (30, 40),
        ]
        self._running = True
        self.fan = None

        try:
            self.fan = PWMOutputDevice(
                pin=fan_pin,
                frequency=pwm_frequency,
                initial_value=0.0,
            )
            logging.info(
                f"PWM fan controller initialized on GPIO{fan_pin} "
                f"at {pwm_frequency} Hz."
            )
        except Exception as e:
            logging.error(f"Failed to initialize PWM on GPIO{fan_pin}: {e}")
            raise

    def _get_cpu_temperature(self) -> float:
        """Reads CPU temperature from available sources, handling errors."""
        for func in self.temp_files:
            try:
                temp = func()
                if temp is not None:
                    return float(temp) + self.temp_offset
            except Exception as e:
                logging.warning(f"Error reading temperature from {func.__name__}: {e}")
        return 0.0

    def _calculate_fan_speed(self, temperature: float) -> float:
        """Calculates the desired fan speed based on temperature."""
        if temperature < self.fan_speed_steps[0][0]:
            return 0.0

        for i in range(len(self.fan_speed_steps) - 1):
            if self.fan_speed_steps[i][0] <= temperature < self.fan_speed_steps[i + 1][0]:
                speed = self.fan_speed_steps[i + 1][1]
                increment = self.fan_speed_increments[i][1]
                return speed + (temperature - self.fan_speed_steps[i][0]) * increment / (self.fan_speed_steps[i + 1][0] - self.fan_speed_steps[i][0])

        return self.fan_speed_steps[-1][1]

    def set_fan_speed(self, speed: float):
        """Sets the fan speed safely."""
        if self.fan is not None:
            self.fan.value = speed / 100.0
            logging.debug(f"Fan speed set to: {speed:.2f}%")

    def stop(self):
        """Stops the fan and releases resources."""
        if self.fan is not None:
            try:
                self.fan.value = 0.0
                self.fan.close()
                logging.info("Fan stopped and GPIO released.")
            except Exception as e:
                logging.error(f"Error during cleanup: {e}")

    def run(self):
        """Runs the fan control loop."""
        logging.info("Starting fan control loop.")
        try:
            while self._running:
                temperature = self._get_cpu_temperature()
                fan_speed = self._calculate_fan_speed(temperature)
                self.set_fan_speed(fan_speed)
                logging.info(
                    f"Temperature: {temperature:.1f}°C, "
                    f"Fan Speed: {fan_speed:.1f}%"
                )
                time.sleep(self.temp_check_interval)
        except KeyboardInterrupt:
            logging.info("Fan control interrupted by keyboard.")
        except Exception as e:
            logging.error(f"An unexpected error occurred: {e}")
        finally:
            self.stop()


def vcgencmd_temp() -> str | None:
    """Reads CPU temperature using vcgencmd."""
    try:
        result = subprocess.run(
            ["vcgencmd", "measure_temp"],
            capture_output=True,
            text=True,
            check=True,
            timeout=5,
        )
        return result.stdout.strip().replace("temp=", "").replace("'C", "")
    except subprocess.CalledProcessError as e:
        logging.error(f"vcgencmd failed: {e.stderr}")
    except subprocess.TimeoutExpired:
        logging.error("vcgencmd timed out.")
    except FileNotFoundError:
        logging.error("vcgencmd not found. Is this running on a Raspberry Pi?")
    except Exception as e:
        logging.error(f"Unexpected error reading vcgencmd: {e}")
    return None


def sysfs_temp() -> str | None:
    """Reads CPU temperature from sysfs."""
    try:
        with open("/sys/class/thermal/thermal_zone0/temp", "r") as f:
            return f.read().strip()
    except FileNotFoundError:
        logging.error("Thermal zone file not found. Is this running on a Raspberry Pi?")
    except PermissionError:
        logging.error("Permission denied reading sysfs thermal zone.")
    except Exception as e:
        logging.error(f"Unexpected error reading sysfs: {e}")
    return None


def main():
    controller = None
    def signal_handler(signum, frame):
        logging.info(f"Signal {signum} received, shutting down.")
        if controller is not None:
            controller._running = False

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        controller = PWMFanController()
        controller.run()
    except Exception as e:
        logging.error(f"Failed to initialize fan controller: {e}")
        if controller is not None:
            controller.stop()
        sys.exit(1)


if __name__ == "__main__":
    main()

