import smbus
import time
import signal
import sys
from datetime import datetime

I2C_BUS = 1
I2C_ADDR = 0x5A

running = True

def signal_handler(sig, frame):
    global running
    running = False

def crc8(data):
    crc = 0xFF
    for byte in data:
        crc ^= byte
        for _ in range(8):
            if crc & 0x80:
                crc = ((crc << 1) ^ 0x31) & 0xFF
            else:
                crc = (crc << 1) & 0xFF
    return crc

def read_sensor(bus):
    try:
        bus.write_byte(I2C_ADDR, 0xAC)
        time.sleep(0.02)
        bus.write_byte(I2C_ADDR, 0x33)
        time.sleep(0.01)
        bus.write_byte(I2C_ADDR, 0x50)
        time.sleep(0.08)
        data = bus.read_i2c_block_data(I2C_ADDR, 0x00, 7)
        if len(data) != 7:
            raise IOError("Incomplete data read from sensor")
        status = data[0]
        if status & 0x18 != 0x18:
            raise IOError(f"Sensor not ready: status byte 0x{status:02X}")
        if crc8(data[:6]) != data[6]:
            raise IOError("CRC mismatch")
        temp_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
        hum_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF
        temp = temp_raw * 200.0 / 1048576.0 - 50.0
        hum = hum_raw * 100.0 / 1048576.0
        return temp, hum
    except IOError as e:
        raise IOError(f"Sensor read failed: {e}")
    except Exception as e:
        raise IOError(f"Unexpected error reading sensor: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    try:
        bus = smbus.SMBus(I2C_BUS)
    except IOError as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)
    try:
        while running:
            try:
                temp, hum = read_sensor(bus)
                ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                print(f"[{ts}] Temp: {temp:.2f}C / {temp * 9.0 / 5.0 + 32:.2f}F  Hum: {hum:.2f}%")
            except IOError as e:
                print(f"{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}  Error: {e}", file=sys.stderr)
            for _ in range(5):
                if not running:
                    break
                time.sleep(1)
    finally:
        bus.close()
        print("\nExited cleanly.")

if __name__ == "__main__":
    main()

