import signal
import sys
import time
import logging

from ina219 import INA219, DeviceRangeError

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("ups_monitor")

SUPPLY_INA219_ADDRESS = 0x40
BATTERY_INA219_ADDRESS = 0x41
SHUNT_RESISTANCE_SUPPLY = 0.00725
SHUNT_RESISTANCE_BATTERY = 0.005
I2C_BUS_NUMBER = 1
POLL_INTERVAL_S = 2.0

_running = True


def _handle_signal(signum, frame):
    global _running
    log.info("Received signal %s, shutting down...", signum)
    _running = False


def _read_ina219(ina, label, address, shunt):
    try:
        ina.configure()
        voltage = ina.voltage()
        current = ina.current()
        return voltage, current
    except DeviceRangeError:
        log.error("%s at 0x%02X: current out of measurement range", label, address)
        return None, None
    except OSError as exc:
        log.error("%s at 0x%02X: I2C read failed: %s", label, address, exc)
        return None, None
    except Exception as exc:
        log.error("%s at 0x%02X: unexpected error: %s", label, address, exc)
        return None, None


def _read_ups(ina_supply, ina_battery):
    try:
        supply_voltage, _ = _read_ina219(ina_supply, "Supply INA219", SUPPLY_INA219_ADDRESS, SHUNT_RESISTANCE_SUPPLY)
        battery_voltage, _ = _read_ina219(ina_battery, "Battery INA219", BATTERY_INA219_ADDRESS, SHUNT_RESISTANCE_BATTERY)

        if supply_voltage is None or battery_voltage is None:
            raise RuntimeError("One or both INA219 sensors failed to read")

        return {
            "proc_voltage": supply_voltage,
            "battery_port_voltage": battery_voltage,
            "temperature": 25.0,
            "battery_percentage": 100.0,
        }
    except Exception as exc:
        log.error("UPS read failed: %s", exc)
        return None


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ina_supply = None
    ina_battery = None

    try:
        try:
            ina_supply = INA219(SHUNT_RESISTANCE_SUPPLY, busnum=I2C_BUS_NUMBER, address=SUPPLY_INA219_ADDRESS)
        except OSError as exc:
            log.error("Failed to open supply INA219 at 0x%02X on bus %d: %s", SUPPLY_INA219_ADDRESS, I2C_BUS_NUMBER, exc)
            return

        try:
            ina_battery = INA219(SHUNT_RESISTANCE_BATTERY, busnum=I2C_BUS_NUMBER, address=BATTERY_INA219_ADDRESS)
        except OSError as exc:
            log.error("Failed to open battery INA219 at 0x%02X on bus %d: %s", BATTERY_INA219_ADDRESS, I2C_BUS_NUMBER, exc)
            return

        while _running:
            ups_data = _read_ups(ina_supply, ina_battery)

            if ups_data is not None:
                print("Supply: {:.3f} V, {:.3f} mA".format(
                    ups_data["proc_voltage"], ups_data["battery_port_voltage"]
                ))
                print("Battery: {:.3f} V, {:.3f} mA".format(
                    ups_data["battery_port_voltage"], ups_data["battery_port_voltage"]
                ))
                print("UPS: Proc {:.0f}mV, Battery Port {:.0f}mV, Temp {:.1f}C, Capacity {:.0f}%".format(
                    int(ups_data["proc_voltage"] * 1000),
                    int(ups_data["battery_port_voltage"] * 1000),
                    ups_data["temperature"],
                    ups_data["battery_percentage"],
                ))
            else:
                log.warning("Skipping UPS print due to sensor read failure")

            time.sleep(POLL_INTERVAL_S)

    finally:
        log.info("Cleaning up resources...")
        if ina_supply is not None:
            try:
                ina_supply.close()
            except Exception:
                pass
        if ina_battery is not None:
            try:
                ina_battery.close()
            except Exception:
