    print(f"\nReceived signal {signum}, exiting gracefully.")
    cleanup()
    sys.exit(0)

def read_temp():
    return random.randint(20, 40)

def main():
    global fan
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        fan = OutputDevice(FAN_PIN)
        print(f"Fan control initialized on GPIO{FAN_PIN} (BCM).")
        print("No physical temperature sensor is used. This program simulates readings.")
        print("Fan is driven HIGH when temperature > 30 C, LOW otherwise.")
        print("In a real deployment, drive the fan through a transistor or relay "
              "rather than sourcing it directly from the GPIO pin.")

        for i in range(NUM_READINGS):
            temp = read_temp()
            print(f"Reading {i + 1}/{NUM_READINGS}: {temp} C")

            if temp > TEMP_THRESHOLD:
