    from adafruit_bme280.constants import BME280_I2C_ADDR_PRIMARY
except ImportError:
    print("Missing dependencies. Install with:")
    print("  pip install adafruit-circuitpython-bme280")
    sys.exit(1)

I2C_BUS = 1
READ_INTERVAL_S = 2.0
NUM_READINGS = 5

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def band_for_humidity(humidity_percent):
    if humidity_percent < 30:
        return "too_dry"
    if humidity_percent < 40:
        return "dry"
    if humidity_percent < 60:
        return "comfortable"
    return "too_humid"

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c = None
    try:
        try:
            i2c = SMBus(I2C_BUS)
        except OSError as e:
            print(f"Error: cannot open I2C bus {I2C_BUS}: {e}")
            return

        try:
            sensor = Adafruit_BME280_I2C(i2c, address=BME280_I2C_ADDR_PRIMARY)
        except (OSError, ValueError) as e:
            print(f"Error: BME280 not found on bus {I2C_BUS}: {e}")
            return

        print("BME280 initialized. Starting humidity monitoring...")

        for i in range(NUM_READINGS):
            if not _running:
                print("Shutdown requested; stopping readings.")
                break

            try:
                humidity = sensor.humidity
            except OSError as e:
                print(f"Warning: I2C read error on iteration {i + 1}: {e}")
                time.sleep(READ_INTERVAL_S)
                continue

            band = band_for_humidity(humidity)
            ts = datetime.datetime.now().isoformat(timespec="seconds")
            print(f"[{ts}] Humidity: {humidity:.1f}%  Band: {band}")

            if i < NUM_READINGS - 1 and _running:
                time.sleep(READ_INTERVAL_S)

        print("Monitoring complete.")

    finally:
        if i2c is not None:
            try:
                i2c.close()
            except OSError:
                pass

if __name__ == "__main__":
    main()

