import subprocess
import time
import signal
import sys
import logging

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

FAN_PIN = 14
PWM_FREQ = 100
TEMP_CHECK_INTERVAL = 5

fan = None
running = True


def get_cpu_temp():
    """Reads the CPU temperature using vcgencmd.

    Returns:
        float: Temperature in degrees Celsius, or None on error.
    """
    try:
        result = subprocess.run(
            ["vcgencmd", "measure_temp"],
            capture_output=True,
            text=True,
            check=True,
            timeout=5,
        )
        temp_str = result.stdout.strip()
        return float(temp_str.split("=")[1].split("'")[0])
    except (subprocess.CalledProcessError, IndexError, ValueError, subprocess.TimeoutExpired) as e:
        logging.error(f"Error reading temperature: {e}")
        return None


def set_fan_speed(duty_cycle):
    """Sets the fan speed using PWM.

    Args:
        duty_cycle (float): Duty cycle (0.0 to 1.0).
    """
    global fan
    if fan is not None:
        try:
            fan.value = duty_cycle
            logging.info(f"Fan speed set to: {duty_cycle * 100:.1f}%")
        except GPIOZeroError as e:
            logging.error(f"Error setting fan speed: {e}")


def cleanup(signum=None, frame=None):
    """Clean up resources and exit."""
    global running, fan
    running = False
    if fan is not None:
        try:
            fan.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    """Main function to control the fan based on CPU temperature."""
    global fan

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
        logging.info(f"PWM initialized on GPIO{FAN_PIN} at {PWM_FREQ} Hz.")
    except GPIOZeroError as e:
        logging.warning(f"Failed to initialize PWM on GPIO{FAN_PIN}: {e}. Running in degraded mode.")
        fan = None

    last_temp = None

    while running:
        temp = get_cpu_temp()
        if temp is not None:
            last_temp = temp
            if temp > 60:
                set_fan_speed(0.5)
            elif temp > 50:
                set_fan_speed(0.3)
            elif temp > 40:
                set_fan_speed(0.2)
            else:
                set_fan_speed(0.1)
        else:
            logging.warning("Temperature reading failed. Maintaining last fan speed.")

        if last_temp is not None and fan is not None:
            logging.info(f"CPU Temp: {last_temp:.1f}°C")

        time.sleep(TEMP_CHECK_INTERVAL)

    cleanup()


if __name__ == "__main__":
    main()

