import RPi.GPIO as GPIO
import time
import sys

LED_PIN = 17

led_state = False

def cleanup():
    """Drive the LED low and release GPIO resources."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()

def main():
    global led_state

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            try:
                user_input = input("Enter 'on' or 'off': ").strip().lower()
            except EOFError:
                print("\nExiting program.")
                break

            if user_input == "on":
                led_state = True
            elif user_input == "off":
                led_state = False
            elif user_input == "exit":
                print("Exiting program.")
                break
            elif user_input == "":
                continue
            else:
                print("Invalid input.")

            try:
                GPIO.output(LED_PIN, GPIO.HIGH if led_state else GPIO.LOW)
            except Exception as e:
                print(f"Failed to write to GPIO: {e}", file=sys.stderr)
                break

            print(f"LED is now {'ON' if led_state else 'OFF'}")
            time.sleep(0.1)

    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

