import logging
import signal
import sys
import time

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

PULSE_PIN = 17
HIGH_DURATION = 0.2
LOW_DURATION = 0.2

_running = True


def _handle_signal(signum, frame):
    global _running
    logging.info("Received signal %s; initiating shutdown.", signum)
    _running = False


def setup_pin(pin: int) -> int:
    try:
        from gpiozero import OutputDevice
        from gpiozero.exc import GPIOZeroError, GPIODeviceError
    except ImportError:
        logging.error("gpiozero is not installed; cannot initialize pin %d.", pin)
        raise

    try:
        device = OutputDevice(pin)
        logging.info("GPIO pin %d initialized as output.", pin)
        return device
    except (GPIOZeroError, GPIODeviceError) as exc:
        logging.error("Failed to initialize GPIO pin %d: %s", pin, exc)
        raise
    except Exception as exc:
        logging.error("Unexpected error initializing GPIO pin %d: %s", pin, exc)
        raise


def generate_pulse(device, high_dur: float, low_dur: float) -> None:
    try:
        device.on()
        time.sleep(high_dur)
        device.off()
        time.sleep(low_dur)
    except Exception as exc:
        logging.error("Error generating pulse on pin %d: %s", device.pin, exc)
        raise


def cleanup_pin(device) -> None:
    if device is not None:
        try:
            device.off()
            logging.info("GPIO pin %d set to LOW during cleanup.", device.pin)
        except Exception as exc:
            logging.error("Error turning off GPIO pin %d during cleanup: %s", device.pin, exc)
        try:
            device.close()
            logging.info("GPIO pin %d closed.", device.pin)
        except Exception as exc:
            logging.error("Error closing GPIO pin %d: %s", device.pin, exc)


def main_loop(device, high_dur: float, low_dur: float) -> None:
    global _running
    while _running:
        try:
            generate_pulse(device, high_dur, low_dur)
        except Exception:
            logging.error("Error in main loop; continuing after delay.")
            time.sleep(0.5)


def main() -> int:
    signal.signal(signal.SIGTERM, _handle_signal)
    signal.signal(signal.SIGINT, _handle_signal)

    device = None
    try:
        device = setup_pin(PULSE_PIN)
        main_loop(device, HIGH_DURATION, LOW_DURATION)
    except KeyboardInterrupt:
        logging.info("Program terminated by user (KeyboardInterrupt).")
        return 0
    except Exception as exc:
        logging.error("Fatal error: %s", exc)
        return 1
    finally:
        if device is not None:
            cleanup_pin(device)
    return 0


if __name__ == "__main__":
    sys.exit(main())

