import signal
import sys
import threading
import time

try:
    import dog
except ImportError:
    print("Error: The 'dog' library is not installed. Install with: pip install dog")
    sys.exit(1)

# Global flag to control the main loop
running = True

# Global reference to the DOG instance for signal handler access
dog_instance = None


def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM to ensure clean shutdown."""
    global running, dog_instance
    print("\nShutting down gracefully...")
    running = False

    # Signal handler for SIGINT (Ctrl+C)
    if sig == signal.SIGINT:
        print("Interrupt received, stopping data logging.")
    # Signal handler for SIGTERM (e.g., systemd stop)
    elif sig == signal.SIGTERM:
        print("Termination signal received, stopping data logging.")

    # Stop the DOG API call if it's running
    if dog_instance is not None and dog_instance.is_running():
        try:
            dog_instance.stop()
        except Exception as e:
            print(f"Error stopping DOG API call: {e}")

    # Clean up GPIO resources
    try:
        dog_instance.cleanup()
    except Exception as e:
        print(f"Error during GPIO cleanup: {e}")

    sys.exit(0)


def log_data(data):
    """Appends received data to the log file."""
    try:
        with open(dog_instance.get_log_file(), "a") as log_file:
            log_file.write(str(data) + "\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")
    except Exception as e:
        print(f"Unexpected error during logging: {e}")


def receive_data():
    """Continuously receives data and logs it to the file."""
    global running
    while running:
        try:
            data = dog.receive()
            if data is not None:
                log_data(data)
        except Exception as e:
            print(f"Error receiving data: {e}")
            # Brief pause to prevent log flooding if the error is persistent
            time.sleep(0.1)
        time.sleep(0.1)


def start_logging(filename):
    """Starts the data logging process."""
    global dog_instance, running

    if running:
        print("Data logging is already running.")
        return

    try:
        dog_instance = dog.dog()
        dog_instance.start(filename)
        running = True
        print(f"Data logging started to {filename}")

        # Start a thread for receiving data
        receive_thread = threading.Thread(target=receive_data, daemon=True)
        receive_thread.start()

    except Exception as e:
        print(f"Error starting data logging: {e}")


def stop_logging():
    """Stops the data logging process."""
    global running, dog_instance
    if not running:
        print("Data logging is not running.")
        return

    running = False
    print("Data logging stopped.")

    # Signal the receive thread to stop
    if dog_instance is not None and dog_instance.is_running():
        try:
            dog_instance.stop()
        except Exception as e:
            print(f"Error stopping DOG API call: {e}")

    # Wait for the receive thread to finish
    if 'receive_thread' in globals() and receive_thread.is_alive():
        receive_thread.join(timeout=2.0)
        if receive_thread.is_alive():
            print("Warning: Receive thread did not terminate cleanly.")


def display_log():
    """Displays the contents of the log file."""
    try:
        with open(dog_instance.get_log_file(), "r") as log_file:
            print(log_file.read())
    except FileNotFoundError:
        print("Log file not found.")
    except IOError as e:
        print(f"Error reading log file: {e}")
    except Exception as e:
        print(f"Unexpected error displaying log: {e}")


def send_data(data):
    """Sends data using the DOG library."""
    try:
        dog_instance.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")


def write_to_log(data):
    """Writes data directly to the log file."""
    try:
        with open(dog_instance.get_log_file(), "a") as log_file:
            log_file.write(str(data) + "\n")
        print(f"Wrote to log: {data}")
    except IOError as e:
        print(f"Error writing to log file: {e}")
    except Exception as e:
        print(f"Unexpected error writing to log: {e}")


def help_command(command=None):
    """Displays help information for commands."""
    man = {
        "help": "Call 'help <command>' for details.\nCommands:\n\t-display\n\t-help\n\t-send\n\t-start\n\t-stop\n\t-write",
        "start": "Starts data logging to a file. Usage: start <filename>",
        "stop": "Stops data logging. Usage: stop",
        "display": "Displays log file contents. Usage: display",
        "send": "Sends data via DOG. Usage: send <data>",
        "write": "Writes data directly to the log file. Usage: write <data>",
    }

    if command:
        print(man.get(command, "No help found for this command."))
    else:
        print("Available commands:")
        for cmd in man:
            print(f"  -{cmd}")


def main():
    """Main function to handle user input and commands."""
    global dog_instance

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize DOG library
    try:
        dog_instance = dog.dog()
    except Exception as e:
        print(f"Error initializing DOG library: {e}")
        sys.exit(1)

    # Set up initial help message
    help_command()

    try:
        while True:
            try:
                command = input("JAYES@ROVER53:\t")
                args = command.split()
                if not args:
                    continue

                action = args[0].lower()

                if action == "help":
                    if len(args) == 2:
                        help_command(args[1])
                    else:
                        help_command()
                elif action == "start":
                    if len(args) == 2:
                        start_logging(args[1])
                    else:
                        print("Usage: start <filename>")
                elif action == "stop":
                    stop_logging()
                elif action == "display":
                    display_log()
                elif action == "send":
                    if len(args) == 2:
                        send_data(args[1])
                    else:
                        print("Usage: send <data>")
                elif action == "write":
                    if len(args) == 2:
                        write_to_log(args[1])
                    else:
                        print("Usage: write <data>")
                else:
                    print(f"Unknown command: {action}. Try 'help'.")

            except EOFError:
                print("\nEOF received. Exiting.")
                break
            except KeyboardInterrupt:
                # Catch Ctrl+C if it slips through signal handler
                print("\nInterrupted by user.")
                break
            except Exception as e:
                print(f"An unexpected error occurred: {e}")

    finally:
        # Ensure DOG API call is stopped and resources are cleaned up
        if dog_instance is not None:
            try:
                if dog_instance.is_running():
                    dog_instance.stop()
                dog_instance.cleanup()
            except Exception as e:
                print(f"Error during cleanup: {e}")


if __name__ == "__main__":
    main()

