DEFAULT_MODEL_FILE = "model.tflite"
DEFAULT_SENSITIVITY = 0.5
DEFAULT_KEYWORDS_FILE = "keywords.json"
DEFAULT_SENTIMENT_THRESHOLD = 0.1
DEFAULT_SENTIMENT_ALERT_PIN = 17
DEFAULT_HEARTBEAT_INTERVAL = 60
DEFAULT_CONFIG_CHECK_INTERVAL = 300
DEFAULT_LOG_INTERVAL = 60
DEFAULT_SAMPLING_RATE = 16000
DEFAULT_AUDIO_CHUNK_SIZE = 512
DEFAULT_AUDIO_FORMAT = "PCM_16"
DEFAULT_AUDIO_CHANNELS = 1

# Global state
config = None
running = True
heartbeat_event = threading.Event()
config_event = threading.Event()
log_event = threading.Event()

# Logging setup
logger = logging.getLogger(__name__)
logger.setLevel(logging.INFO)


def setup_logging(log_file):
    handler = logging.FileHandler(log_file)
    formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
    handler.setFormatter(formatter)
