def load_config(config_file):
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logger.error(f"Configuration file not found: {config_file}")
        return None
    except json.JSONDecodeError as e:
        logger.error(f"Invalid JSON in configuration file: {config_file}: {e}")
        return None


def save_config(config_file, config_data):
    try:
        with open(config_file, "w") as f:
            json.dump(config_data, f, indent=4)
        logger.info(f"Configuration saved to {config_file}")
    except IOError as e:
        logger.error(f"Error saving configuration: {e}")


def load_keywords(keywords_file):
    try:
        with open(keywords_file, "r") as f:
            return [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        logger.error(f"Keywords file not found: {keywords_file}")
        return []
    except IOError as e:
        logger.error(f"Error reading keywords file: {e}")
        return []


def trigger_alert(sentiment, alert_pin, config):
    if alert_pin is None:
        return
    if sentiment is not None and sentiment < config.get("sentiment_threshold", DEFAULT_SENTIMENT_THRESHOLD):
        logger.warning("Sentiment below threshold. Triggering alert.")
        if LED is not None:
            try:
                led = LED(alert_pin)
                led.on()
                time.sleep(1)
                led.off()
            except Exception as e:
                logger.error(f"Error controlling LED on pin {alert_pin}: {e}")
        else:
            logger.warning("LED control unavailable. Simulating alert.")


def send_cloud_alert(sentiment, config):
    if not config or not config.get("cloud_endpoint"):
        return
    if not config.get("api_key"):
        logger.warning("Cloud endpoint configured but no API key found.")
        return
    if not config.get("alert_topic"):
        logger.warning("Cloud endpoint configured but no alert topic found.")
        return
    if not config.get("sentiment_threshold") or sentiment is None:
        return
    if sentiment < config.get("sentiment_threshold"):
        logger.info("Sending cloud alert...")
        try:
            if requests is not None:
                headers = {"Authorization": f"Bearer {config['api_key']}"}
                data = {"sentiment": sentiment, "threshold": config.get("sentiment_threshold", DEFAULT_SENTIMENT_THRESHOLD)}
                requests.post(config["cloud_endpoint"], json=data, headers=headers, timeout=10)
                logger.info("Cloud alert sent successfully.")
            elif weaviate is not None:
                client = weaviate.Client(default_schema="sentiment", endpoint_url=config["cloud_endpoint"])
                client.update_instance(instance_id="default", set=["sentiment", sentiment], if_match="*")
                logger.info("Cloud alert sent via Weaviate.")
            else:
                logger.warning("No valid cloud alert sending mechanism found.")
        except requests.exceptions.RequestException as e:
            logger.error(f"Error sending cloud alert: {e}")
        except Exception as e:
            logger.error(f"Unexpected error sending cloud alert: {e}")


def process_audio(audio_data, config, model_file, sentiment_model_path, keywords, sentiment_threshold, alert_pin, cloud_config):
    try:
        if sr is None:
            logger.warning("SpeechRecognition library not available.")
            return None
        recognizer = sr.Recognizer()
        audio = sr.AudioData.from_bytes(audio_data, sample_rate=DEFAULT_SAMPLING_RATE)
        try:
            text = recognizer.recognize_sphinx(audio)
            logger.info(f"Recognized speech: {text}")
            return text.lower()
        except sr.UnknownValueError:
            logger.warning("Could not understand audio")
            return None
        except sr.RequestError as e:
            logger.error(f"Could not request results from SpeechRecognition service; {e}")
            return None
    except Exception as e:
        logger.error(f"Error processing audio: {e}")
        return None

    if not text:
        return None

    keywords_list = load_keywords(DEFAULT_KEYWORDS_FILE)
    if not keywords_list:
        return None

    keywords_set = set(keywords_list)
    if not keywords_set:
        return None

    if any(kw in text for kw in keywords_set):
        logger.info("Keyword detected!")
        return text
    return None


def analyze_sentiment(text, sentiment_model_path):
    if textblob is None:
        logger.warning("TextBlob library not available.")
        return None
    try:
        analysis = textblob.TextBlob(text)
        sentiment_value = analysis.sentiment.polarity
        return sentiment_value
    except Exception as e:
        logger.error(f"Error analyzing sentiment: {e}")
        return None


def capture_audio(sampling_rate, audio_format, audio_channels, audio_chunk_size, config):
    try:
        picam2 = Picamera2()
        audio_config = picam2.create_audio_configuration(
            sample_rate=sampling_rate,
            format=audio_format,
            channels=audio_channels
        )
        picam2.configure(audio_config)
        picam2.start()
        logger.info("Audio capture started.")
        while running:
            try:
                audio_data = picam2.capture_audio(audio_chunk_size)
                if audio_data:
                    heartbeat_event.set()
                    yield audio_data
            except Exception as e:
                logger.error(f"Error capturing audio: {e}")
                time.sleep(1)
    except Exception as e:
        logger.error(f"Failed to initialize audio capture: {e}")
        raise
    finally:
        try:
            picam2.stop()
            picam2.close()
        except Exception:
            pass


def main():
    global config, running, heartbeat_event, config_event, log_event

    parser = argparse.ArgumentParser(description="Voice-controlled robot for assistive technology.")
    parser.add_argument("--config", type=str, default=DEFAULT_CONFIG_FILE, help="Path to the configuration file.")
    parser.add_argument("--log", type=str, default=DEFAULT_LOG_FILE, help="Path to the log file.")
    parser.add_argument("--model", type=str, default=DEFAULT_MODEL_FILE, help="Path to the TensorFlow Lite model file.")
    parser.add_argument("--sensitivity", type=float, default=DEFAULT_SENSITIVITY, help="Sensitivity value for voice activity detection.")
    parser.add_argument("--keywords", type=str, default=DEFAULT_KEYWORDS_FILE, help="Path to the keywords file.")
    parser.add_argument("--threshold", type=float, default=DEFAULT_SENTIMENT_THRESHOLD, help="Sentiment threshold for alerts.")
    parser.add_argument("--alert_pin", type=int, default=DEFAULT_SENTIMENT_ALERT_PIN, help="GPIO pin for the alert LED.")
    parser.add_argument("--cloud_endpoint", type=str, help="URL of the cloud service endpoint.")
    parser.add_argument("--api_key", type=str, help="API key for the cloud service.")
    args = parser.parse_args()

    setup_logging(args.log)
    config = load_config(args.config)
    if config is None:
        logger.error("Failed to load configuration. Exiting.")
        sys.exit(1)

    sentiment_threshold = config.get("sentiment_threshold", DEFAULT_SENTIMENT_THRESHOLD)
    alert_pin = config.get("sentiment_alert_pin", DEFAULT_SENTIMENT_ALERT_PIN)
    cloud_config = {
        "cloud_endpoint": config.get("cloud_endpoint"),
        "api_key": config.get("api_key"),
        "alert_topic": config.get("alert_topic", "robot_alert")
    }

    model_file = config.get("model_file", DEFAULT_MODEL_FILE)
    keywords = load_keywords(args.keywords)

    if not os.path.exists(model_file):
        logger.error(f"Model file not found: {model_file}")
        sys.exit(1)

    try:
        interpreter = tflite.Interpreter(model_path=model_file)
        interpreter.allocate_tensors()
        input_details = interpreter.get_input_details()
        output_details = interpreter.get_output_details()
        logger.info("TensorFlow Lite model loaded successfully.")
    except Exception as e:
        logger.error(f"Failed to load TensorFlow Lite model: {e}")
        sys.exit(1)

    audio_generator = capture_audio(DEFAULT_SAMPLING_RATE, DEFAULT_AUDIO_FORMAT, DEFAULT_AUDIO_CHANNELS, DEFAULT_AUDIO_CHUNK_SIZE, config)

    def audio_callback(audio_data):
        if not running:
            return
        text = process_audio(audio_data, config, model_file, input_details, keywords, sentiment_threshold, alert_pin, cloud_config)
        if text:
            sentiment = analyze_sentiment(text, input_details[0]['quantization_params']['sparse_weights'])
            trigger_alert(sentiment, alert_pin, config)
