from gpiozero import Button, LED
from gpiozero.exc import GPIOZeroError

BUTTON_PIN = 4
LED_PIN = 17
POLL_DELAY = 0.1


def main() -> None:
    button = None
    led = None
    try:
        button = Button(BUTTON_PIN, pull_up=False)
        led = LED(LED_PIN)

        print(f"Polling button on GPIO{BUTTON_PIN} (pull-down); LED on GPIO{LED_PIN}. Press Ctrl+C to exit.")

        while True:
            if button.is_pressed:
                led.off()
            else:
                led.on()
            time.sleep(POLL_DELAY)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except GPIOZeroError as exc:
        print(f"GPIO error: {exc}", file=sys.stderr)
    finally:
        if led is not None:
            led.close()
        if button is not None:
            button.close()
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

