import logging
import signal
import time
import zmq

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)


class PIDHandler:
    """
    Handles PID controller updates and error signal output using ZeroMQ and RPi.GPIO.

    Attributes:
        error_pin (int): Physical pin number (BOARD) for the error signal.
        pwm_pin (int): Physical pin number (BOARD) for the PWM error signal.
        watchdog_timeout (float): Timeout in seconds for the watchdog.
        subscriptions (dict): Subscription list: {topic: [callback, ...]}.
        sub_list (list): List of subscription callbacks.
        global_err_state (bool): Global error state flag.
        last_msg (float): Timestamp of the last received message.
        zmq_socket (zmq.Socket): ZeroMQ socket for message reception.
        pwm_frequency (int): PWM frequency in Hz.
        pwm_duty_cycle (float): Initial PWM duty cycle.
        use_pwm (bool): Enable PWM output.
    """

    def __init__(self, error_pin=10, pwm_pin=12, watchdog_timeout=20.0,
                 pwm_frequency=1000, pwm_duty_cycle=0.0, use_pwm=False):
        self.error_pin = error_pin
        self.pwm_pin = pwm_pin
        self.watchdog_timeout = watchdog_timeout
        self.subscriptions = {}
        self.sub_list = []
        self.global_err_state = False
        self.last_msg = time.time()
        self.zmq_socket = None
        self.pwm_frequency = pwm_frequency
        self.pwm_duty_cycle = pwm_duty_cycle
        self.use_pwm = use_pwm

        if GPIO is not None:
            try:
                GPIO.setmode(GPIO.BOARD)
                GPIO.setwarnings(False)
                if self.use_pwm:
                    GPIO.setup(self.pwm_pin, GPIO.OUT)
                    self.pwm = GPIO.PWM(self.pwm_pin, self.pwm_frequency)
                    self.pwm.start(self.pwm_duty_cycle)
                else:
                    GPIO.setup(self.error_pin, GPIO.OUT)
                    GPIO.output(self.error_pin, GPIO.LOW)
                logging.info(
                    f"GPIO initialized: error_pin={self.error_pin}, "
                    f"pwm_pin={self.pwm_pin}, use_pwm={self.use_pwm}"
                )
            except Exception as e:
                logging.error(f"GPIO initialization failed: {e}")
                self.use_pwm = False
                self.pwm_pin = None
                self.pwm_frequency = 0
                self.pwm_duty_cycle = 0.0
        else:
            logging.warning("RPi.GPIO not available; running in simulation mode.")

        if self.zmq_socket is not None:
            try:
                self.zmq_socket.setsockopt(zmq.LINGER, 0)
            except Exception as e:
                logging.error(f"Failed to set ZMQ linger option: {e}")

    def update_error_output(self):
        """Sets the error output based on the global error state."""
        if GPIO is not None:
            try:
                if self.use_pwm:
                    GPIO.output(self.pwm_pin, GPIO.HIGH if self.global_err_state else GPIO.LOW)
                else:
                    GPIO.output(self.error_pin, GPIO.HIGH if self.global_err_state else GPIO.LOW)
            except Exception as e:
                logging.error(f"Error updating GPIO output: {e}")

    def set_error_output(self, state):
        """Sets the error output state directly."""
        if GPIO is not None:
            try:
                if self.use_pwm:
                    GPIO.output(self.pwm_pin, GPIO.HIGH if state else GPIO.LOW)
                else:
                    GPIO.output(self.error_pin, GPIO.HIGH if state else GPIO.LOW)
            except Exception as e:
                logging.error(f"Error setting GPIO output: {e}")

    def handle_message(self, message):
        """
        Processes incoming messages.

        Args:
            message (dict): The received message dictionary.
        """
        self.last_msg = time.time()
        topic = message.get('topic')
        try:
            if topic in self.subscriptions:
                for callback in self.subscriptions[topic]:
                    callback(message)
            else:
                logging.warning(f"Unknown topic: {topic}")
        except Exception as e:
            logging.error(f"Error handling message topic '{topic}': {e}")

    def subscribe(self, topic, callback):
        """Subscribes to a topic and registers a callback."""
        if topic not in self.subscriptions:
            self.subscriptions[topic] = []
        self.subscriptions[topic].append(callback)
        self.sub_list.append((topic, callback))

    def update_pwm_frequency(self, frequency):
        """Updates the PWM frequency."""
        if self.use_pwm and GPIO is not None:
            try:
                self.pwm.ChangeFrequency(frequency)
                logging.info(f"PWM frequency updated to {frequency} Hz")
