import time
import board
import busio
import adafruit_fingerprint

# --- Configuration -----------------------------------------------------------
I2C_SCL = board.SCL
I2C_SDA = board.SDA
RETRY_DELAY_S = 1.0

# --- Globals for cleanup -----------------------------------------------------
i2c_bus = None
sensor = None


def cleanup():
    """Release hardware resources on every exit path."""
    global i2c_bus, sensor
    if sensor is not None:
        try:
            sensor.deinit()
        except Exception:
            pass
        sensor = None
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        i2c_bus = None


def main():
    global i2c_bus, sensor

    # --- Initialize I2C bus --------------------------------------------------
    try:
        i2c_bus = busio.I2C(I2C_SCL, I2C_SDA)
    except Exception as exc:
        print(f"Error initializing I2C bus: {exc}")
        cleanup()
        return

    # --- Initialize fingerprint sensor --------------------------------------
    try:
        sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
    except ValueError as exc:
        print(f"ValueError initializing fingerprint sensor (I2C locked?): {exc}")
        cleanup()
        return
    except Exception as exc:
        print(f"Error initializing fingerprint sensor: {exc}")
        cleanup()
        return

    # --- Main authentication loop --------------------------------------------
    try:
        while True:
            try:
                # Wait one second between authentication attempts
                time.sleep(RETRY_DELAY_S)

                # Acquire an image from the sensor
                try:
                    result = sensor.get_image()
                except RuntimeError as exc:
                    print(f"Sensor read error (sensor absent or unresponsive): {exc}")
                    continue

                if result == adafruit_fingerprint.OK:
                    # Convert the image to a template
                    try:
                        sensor.image_2_tz(1)
                    except RuntimeError as exc:
                        print(f"Template conversion error: {exc}")
                        continue

                    # Search the fingerprint database
                    try:
                        sensor.finger_search()
                    except RuntimeError as exc:
                        print(f"Finger search error: {exc}")
                        continue

                    # Check if a match was found
                    if sensor.finger_id != 0:
                        print(f"Access Granted - ID: {sensor.finger_id}, Confidence: {sensor.confidence}")
                    else:
                        print("Access Denied - No match found.")

                # Handle the 'no finger' case gracefully
                elif result == adafruit_fingerprint.NOFINGER:
                    pass
                else:
                    print(f"Unexpected get_image() result: {result}")

            except KeyboardInterrupt:
                print("\nExiting program due to keyboard interrupt.")
                break

            except Exception as exc:
                # Catch any other unexpected errors and retry on next loop
                print(f"An unexpected error occurred: {exc}")

    finally:
        cleanup()
        print("Program finished.")


if __name__ == "__main__":
    main()

