    _log("INFO", f"Sending data: {data_string}")

    try:
        byte_lists = _string_to_byte_list(data_string)
        for byte in byte_lists:
            for bit in byte:
                _transmit_bit(bit)
        _transmit_bit(0)  # Send END_BYTE
        _log("INFO", "Data transmission complete.")
        return True
    except Exception as e:
        _log("ERROR", f"Error during data transmission: {e}")
        return False


def _receive_bit():
    """Receive a single bit (0 or 1) by detecting rising edges on the timer pin."""
    return GPIO.input(TIMER_IN)


def _receive_byte():
    """Receive a single byte (8 bits) from the GPIO pins."""
    byte = []
    for _ in range(8):
        # Wait for rising edge (timer goes LOW -> HIGH)
        while GPIO.input(TIMER_IN) == GPIO.LOW:
            if _shutdown_event.is_set():
                raise TimeoutError("Reception interrupted by shutdown signal.")
            time.sleep(0.00001)
        bit = _receive_bit()
        byte.append(bit)
    return byte


def receive_data(timeout=5.0):
    """Receive data over the GPIO pins using the defined bit-banged protocol."""
    if not isinstance(timeout, (int, float)) or timeout <= 0:
        _log("ERROR", "timeout must be a positive number.")
        return ""

    _log("INFO", f"Receiving data (timeout: {timeout}s)...")

    try:
        received_bytes = []
        start_time = time.time()

        # Register edge detection for rising edges on timer_in
        GPIO.add_event_detect(TIMER_IN, GPIO.RISING, callback=None, bouncetime=1)

        while True:
            if _shutdown_event.is_set():
                break

            if time.time() - start_time > timeout:
                _log("ERROR", "Timeout waiting for data start.")
                return ""

            try:
                received_byte = _receive_byte()
            except TimeoutError as e:
                _log("ERROR", str(e))
                return ""

            if received_byte == START_BYTE:
                received_bytes.append(received_byte)
                continue
            elif received_byte == END_BYTE:
                received_string = _byte_list_to_string(received_bytes)
                _log("INFO", f"Received data: {received_string}")
                return received_string
            else:
                received_bytes.append(received_byte)

    except Exception as e:
        _log("ERROR", f"Error during data reception: {e}")
        return ""
    finally:
        # Clean up event detection
        try:
            GPIO.remove_event_detect(TIMER_IN)
        except Exception:
            pass


def api_call(url, data=None):
    """Send a data string via the GPIO bit-banged protocol and invoke the library's API."""
    if not send_data(data):
        _log("ERROR", "Failed to send data via GPIO.")
        return None

    try:
        import api  # Import the library's API module
        response = api.call(url, data)
        _log("INFO", f"API call completed. Response: {response}")
        return response
    except Exception as e:
        _log("ERROR", f"Error in API call: {e}")
        return None


def main():
    """Main entry point: set up GPIO, register signal handlers, and demonstrate usage."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _setup_gpio()
        _log("INFO", "GPIO setup complete.")

        # Example usage
        api_call("http://example.com", "key=value")
        api_call("http://example.com", "key=value")

    except Exception as e:
        _log("ERROR", f"Fatal error during initialization: {e}")
    finally:
        _cleanup_gpio()
        _log("INFO", "GPIO cleanup complete.")


if __name__ == "__main__":
    main()

