import signal
import sys
import time

import smbus2

I2C_BUS = 1
BH1750_ADDR = 0x23
BH1750_POWER_ON = 0x01
BH1750_CONTINUOUS_HIGH_RES_MODE = 0x10

_running = True


def _handle_sigint(signum, frame):
    global _running
    _running = False


def _init_bus(bus_num):
    try:
        return smbus2.SMBus(bus_num)
    except FileNotFoundError:
        print(f"Error: I2C bus {bus_num} not found. Enable I2C with 'sudo raspi-config'.")
        return None
    except OSError as e:
        print(f"Error: cannot open I2C bus {bus_num}: {e}")
        return None


def _write_cmd(bus, addr, cmd):
    bus.write_byte(addr, cmd)


def _read_lux(bus, addr):
    _write_cmd(bus, addr, BH1750_CONTINUOUS_HIGH_RES_MODE)
    time.sleep(0.182)  # max conversion time for high-res mode
    data = bus.read_i2c_block_data(addr, 0x00, 2)
    raw = (data[0] << 8) | data[1]
    return raw / 1.2


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_sigint)

    bus = _init_bus(I2C_BUS)
    if bus is None:
        sys.exit(1)

    try:
        _write_cmd(bus, BH1750_ADDR, BH1750_POWER_ON)
        time.sleep(0.01)

        while _running:
            try:
                lux = _read_lux(bus, BH1750_ADDR)
                print(f"Ambient Light: {lux:.2f} lux")
            except OSError as e:
                print(f"Warning: I2C read error ({e}). Retrying...")
            except Exception as e:
                print(f"Warning: unexpected error reading sensor ({e}). Retrying...")

            for _ in range(10):
                if not _running:
                    break
                time.sleep(0.1)
    finally:
        try:
            bus.close()
        except Exception:
            pass
        print("\nProgram terminated. Exiting...")


if __name__ == "__main__":
    main()

