import sys
import time
import signal

try:
    import gpio_ch
except RuntimeError as exc:
    print(f"Error: unable to import gpio_ch library: {exc}", file=sys.stderr)
    sys.exit(1)

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def get_raspi_model():
    """Return a human-readable model string from the board revision code."""
    models = {
        1: "Raspberry Pi 1 Model B",
        2: "Raspberry Pi 1 Model B+",
        3: "Raspberry Pi 2 Model B",
        4: "Raspberry Pi 3 Model B",
        5: "Raspberry Pi 3 Model B+",
        6: "Raspberry Pi 4 Model B",
        7: "Raspberry Pi 5",
    }
    rev = gpio_ch.get_raspi_revision()
    return models.get(rev, "unknown")

def get_gpio_num():
    """Return the number of GPIO pins supported by this board revision."""
    return 17 if gpio_ch.get_raspi_revision() <= 1 else 26

def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    model = get_raspi_model()
    gpio_count = get_gpio_num()
    print(f"Model: {model}")
    print(f"GPIO count: {gpio_count}")
    print("Monitoring...")

    debounce = 200
    if len(sys.argv) > 1:
        try:
            debounce = int(sys.argv[1])
        except ValueError:
            print("Error: --debounce must be an integer.", file=sys.stderr)
            sys.exit(1)

    gpio_ch.set_debounce_time(debounce)

    gpio_pins = gpio_ch.gpio_ch
    for pin in gpio_pins:
        gpio_ch.setup(pin, gpio_ch.IN)

    gpio_ch.call(lambda x, y, z, w: None)

    try:
        while _running:
            time.sleep(0.5)
    finally:
        try:
            gpio_ch.call(None)
        except Exception:
            pass

if __name__ == "__main__":
    main()

