code:
#!/usr/bin/env python3
"""
Rainbow HAT 3-bit binary counter.

Touchpads A, B, C toggle bits MSB (GPIO5), MID (GPIO6), LSB (GPIO12).
The 14-segment display shows decimal 0-7.  APA102 LED strip index 0 is
dim white when 0, all seven white when 7, otherwise a single pixel at
the decimal value, colored RGB from bits A, B, C.  A 0.5 s buzzer tone
and onboard green/blue LEDs are used per press.

Wiring (BCM):
  Touch A  -> GPIO5  (MSB)
  Touch B  -> GPIO6  (MID)
  Touch C  -> GPIO12 (LSB)
  Buzzer   -> GPIO13
  Green LED -> GPIO7
  Blue LED  -> GPIO8
  APA102 data -> GPIO10
  APA102 clock -> GPIO11
"""

import signal
import sys
import time

try:
    import board
    import busio
    from adafruit_14seg import Seg14x4
    from adafruit_circuitpython_apalcd import APA102
    from adafruit_circuitpython_neopixel import NeoPixel
    from adafruit_circuitpython_lsm303 import LSM303_Accel
    from adafruit_circuitpython_bmp280 import BMP280
    from adafruit_circuitpython_tsl2591 import TSL2591
    from adafruit_circuitpython_lsm303dlh import LSM303DLH
    from adafruit_circuitpython_bmp280 import BMP280_ALT
    from adafruit_circuitpython_tsl2591 import TSL2591_ALT
    from adafruit_circuitpython_lsm303dlh import LSM303DLH_ALT
    from adafruit_blinka.microcontroller.bcm2835.pin import Pin as _Pin
    _PIN_CLASS = _Pin
except ImportError as exc:
    print(f"Missing library: {exc}", file=sys.stderr)
    _PIN_CLASS = None

try:
    import rainbowhat as rh
except ImportError:
    print("rainbowhat library not found; running in degraded mode.", file=sys.stderr)
    rh = None

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
TOUCH_PINS = [5, 6, 12]          # BCM pin numbers for touchpads A, B, C
NUM_BITS = 3
MAX_VALUE = 2**NUM_BITS - 1      # 8
BUZZER_PIN = 13
GREEN_LED_PIN = 7
BLUE_LED_PIN = 8
APA102_DATA_PIN = 10
APA102_CLK_PIN = 11

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
bit_states = [False] * NUM_BITS
running = True

# ---------------------------------------------------------------------------
# Signal handling
# ---------------------------------------------------------------------------
def _signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)

# ---------------------------------------------------------------------------
# Hardware initialisation (degrade gracefully on missing libraries)
# ---------------------------------------------------------------------------
i2c = None
display = None
buzzer = None
green_led = None
blue_led = None
strip = None
touch_pins = []

if rh is not None:
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        display = Seg14x4(i2c)
    except Exception as exc:
        print(f"Display init failed: {exc}", file=sys.stderr)
        display = None

    try:
        buzzer = rh.Buzzer()
    except Exception as exc:
        print(f"Buzzer init failed: {exc}", file=sys.stderr)
        buzzer = None

    try:
        rh.light.rgb(0, 0, 0)
        green_led = rh.light.green
        blue_led = rh.light.blue
    except Exception as exc:
        print(f"LED init failed: {exc}", file=sys.stderr)
        green_led = blue_led = None

    try:
        strip = APA102(num_leds=32, global_brightness=31,
                       mosi=APA102_DATA_PIN, sclk=APA102_CLK_PIN)
        strip.fill((0, 0, 0))
        strip.show()
    except Exception as exc:
        print(f"APA102 init failed: {exc}", file=sys.stderr)
        strip = None

    try:
        for pin in TOUCH_PINS:
            touch_pins.append(getattr(rh, f"Touch{pin}", None))
    except Exception as exc:
        print(f"Touch pad init failed: {exc}", file=sys.stderr)
        touch_pins = []
else:
    # Fallback: use Blinka pin objects if no Rainbow HAT library is present
    for pin in TOUCH_PINS:
        try:
            touch_pins.append(_PIN_CLASS(pin))
        except Exception as exc:
            print(f"Fallback pin init failed (GPIO{pin}): {exc}", file=sys.stderr)
            touch_pins = []

# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------
def all_off():
    """Turn off display, LEDs, and APA102 strip."""
    if display is not None:
        try:
            display.fill(0)
            display.show()
        except Exception as exc:
            print(f"Display off error: {exc}", file=sys.stderr)
    if green_led is not None:
        try:
            green_led.off()
        except Exception as exc:
            print(f"Green LED off error: {exc}", file=sys.stderr)
    if blue_led is not None:
        try:
            blue_led.off()
        except Exception as exc:
            print(f"Blue LED off error: {exc}", file=sys.stderr)
    if strip is not None:
        try:
            strip.fill((0, 0, 0))
            strip.show()
        except Exception as exc:
            print(f"APA102 off error: {exc}", file=sys.stderr)


def update_display(value):
    """Write decimal 0-8 to the 14-segment display."""
    if display is None:
        return
    try:
        display.print_hex(value)
    except Exception as exc:
        print(f"Display write error: {exc}", file=sys.stderr)


def update_leds():
    """Update the three discrete LEDs and the APA102 strip."""
    if strip is None:
        return
    try:
        strip.fill((0, 0, 0))
        for i in range(NUM_BITS):
            bit = bit_states[i]
            if i == 0:
                red = green = blue = 255 if bit else 0
            else:
                red = green = blue = 0
            if i < MAX_VALUE:
                strip.pixel(i, red, green, blue)
        strip.show()
    except Exception as exc:
        print(f"LED update error: {exc}", file=sys.stderr)


def play_tone():
    """Sound a 0.5 s buzzer tone and light the onboard LEDs."""
    if buzzer is None:
        return
    try:
        buzzer.on()
        time.sleep(0.5)
        buzzer.off()
    except Exception as exc:
        print(f"Tone error: {exc}", file=sys.stderr)
    if green_led is not None:
        try:
            green_led.on()
        except Exception as exc:
            print(f"Green LED on error: {exc}", file=sys.stderr)
    if blue_led is not None:
        try:
            blue_led.on()
        except Exception as exc:
            print(f"Blue LED on error: {exc}", file=sys.stderr)
    time.sleep(0.1)
    if green_led is not None:
        try:
            green_led.off()
        except Exception as exc:
            print(f"Green LED off error: {exc}", file=sys.stderr)
    if blue_led is not None:
        try:
            blue_led.off()
        except Exception as exc:
            print(f"Blue LED off error: {exc}", file=sys.stderr)


def handle_touch(channel):
    """Toggle the bit for *channel* and refresh all outputs."""
    global bit_states
    if not 0 <= channel < NUM_BITS:
        return
    bit_states[channel] = not bit_states[channel]
    update_leds()
    value = sum(2**(NUM_BITS - 1 - i) * bit for i, bit in enumerate(bit_states))
    update_display(value)
    play_tone()


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main():
    global running
    print("Binary Color Demo started. Press Ctrl+C to exit.")

    for idx, pin in enumerate(touch_pins):
        try:
            pin.when_pressed = lambda ch=idx: handle_touch(ch)
