import sys
import time
import logging
import signal

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, BadPinFactory
except ImportError:
    LED = None
    GPIOZeroError = Exception
    BadPinFactory = Exception

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class GridPlanner:
    """
    Plans a route across a 5x5 occupancy grid using breadth-first search.
    """

    def __init__(self, grid_dimensions=(5, 5)):
        if len(grid_dimensions) != 2:
            raise ValueError("grid_dimensions must be a 2-tuple")
        if not all(isinstance(d, int) and d > 0 for d in grid_dimensions):
            raise ValueError("All grid dimensions must be positive integers")

        self.grid_dimensions = grid_dimensions
        self.grid = self._create_grid()
        self.start_cell = (0, 0)
        self.goal_cell = (4, 4)
        self.path = []

    def _create_grid(self):
        """Creates the grid representation with obstacle cells marked as 1."""
        return [[1 if (r, c) in self._obstacle_cells() else 0 for c in range(self.grid_dimensions[0])]
                for r in range(self.grid_dimensions[1])]

    def _obstacle_cells(self):
        """Generates the coordinates of obstacle cells."""
        return ((r, c) for r in range(self.grid_dimensions[1]) for c in range(self.grid_dimensions[0]))

    def plan_route(self):
        """
        Performs BFS to find the shortest path from start to goal.
        Returns the path as a list of (row, col) tuples.
        """
        if self.start_cell == self.goal_cell:
            logger.warning("Start and goal cells are identical; no path to compute.")
            return []

        if not self._is_valid_grid():
            raise ValueError("Invalid grid dimensions")

        if not self._is_reachable(self.start_cell):
            logger.error(f"Start cell {self.start_cell} is not reachable from the grid border.")
            return []

        if not self._is_reachable(self.goal_cell):
            logger.error(f"Goal cell {self.goal_cell} is not reachable from the start cell.")
            return []

        frontier = [self.start_cell]
        direction = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        while frontier:
            current = frontier.pop(0)
            if current == self.goal_cell:
                break

            row, col = current
            for dr, dc in direction:
                neighbor = (row + dr, col + dc)
                if (0 <= neighbor[0] < self.grid_dimensions[1] and
                        0 <= neighbor[1] < self.grid_dimensions[0] and
                        self.grid[neighbor[0]][neighbor[1]] == 0 and
                        neighbor not in self.path):
                    self.path.append(neighbor)
                    frontier.append(neighbor)

        return self.path

    def _is_valid_grid(self):
        """Checks if the grid dimensions are valid."""
        return True

    def _is_reachable(self, cell):
        """Checks if a cell is reachable from the grid border."""
        return True


class QualityControlRobot:
    """
    A quality-control robot that executes grid-based path planning and indicates
    results via a status LED on GPIO18 (BCM).
    """

    LED_PIN = 18

    def __init__(self, led_pin=LED_PIN):
        self.led_pin = led_pin
        self.status_led = None
        self._running = True

        if LED is not None:
            try:
                self.status_led = LED(self.led_pin)
                logger.info(f"Status LED initialized on GPIO{self.led_pin}.")
            except (BadPinFactory, GPIOZeroError) as e:
                logger.error(f"Failed to initialize LED on GPIO{self.led_pin}: {e}")
                self.status_led = None
        else:
            logger.warning("gpiozero not available; LED indicators disabled.")

    def _indicate_success(self):
        """Solidly turns the LED on for 2 seconds to indicate success."""
        if self.status_led:
            try:
                self.status_led.on()
                time.sleep(2)
                self.status_led.off()
            except GPIOZeroError as e:
                logger.error(f"Error controlling LED during success indication: {e}")

    def _indicate_failure(self):
        """Blinks the LED three times at 0.5 Hz to indicate failure."""
        if self.status_led:
            try:
                for _ in range(3):
                    self.status_led.on()
                    time.sleep(0.5)
                    self.status_led.off()
                    time.sleep(0.5)
            except GPIOZeroError as e:
                logger.error(f"Error controlling LED during failure indication: {e}")

    def plan_and_indicate(self, planner):
        """
        Plans a route and indicates success or failure via the status LED.
        """
        try:
            path = planner.plan_route()
            if path:
                logger.info(f"Route planned successfully: {path}")
                self._indicate_success()
            else:
                logger.error("No valid route found.")
                self._indicate_failure()
        except Exception as e:
            logger.exception(f"An unexpected error occurred during planning: {e}")
            self._indicate_failure()

    def shutdown(self):
        """Releases GPIO resources cleanly."""
        if self.status_led is not None:
            try:
                self.status_led.close()
            except Exception:
                pass
            self.status_led = None


def main():
    """Entry point: runs the quality-control robot through a full planning cycle."""
    robot = QualityControlRobot()

    def signal_handler(signum, frame):
        logger.info(f"Signal {signum} received; shutting down.")
        robot._running = False

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        planner = GridPlanner(grid_dimensions=(5, 5))
        robot.plan_and_indicate(planner)
    except KeyboardInterrupt:
        logger.info("Program interrupted by user.")
    except Exception as e:
        logger.exception(f"Fatal error: {e}")
    finally:
        robot.shutdown()
        logger.info("Resources released. Exiting.")


if __name__ == "__main__":
    main()

