import signal
import sys
import time

LED_PIN = 25


class LEDController:
    """
    Controls an LED on a Raspberry Pi via gpiozero.

    Attributes:
        pin (int): BCM GPIO pin number (2-27).
        led (gpiozero.LED | None): gpiozero LED object or None if uninitialized.
    """

    def __init__(self, pin: int):
        if not isinstance(pin, int) or not (2 <= pin <= 27):
            raise ValueError(f"Invalid GPIO pin number: {pin!r}. Must be an integer in 2-27.")

        self.pin = pin
        self.led = None

        try:
            from gpiozero import LED
            self.led = LED(pin)
        except Exception as exc:
            raise RuntimeError(f"Failed to initialize GPIO{pin} as LED: {exc}") from exc

    def on(self):
        if self.led is None:
            raise RuntimeError("LED object is not initialized.")
        self.led.on()

    def off(self):
        if self.led is None:
            raise RuntimeError("LED object is not initialized.")
        self.led.off()

    def blink(self, on_duration: float, off_duration: float):
        if not isinstance(on_duration, (int, float)) or on_duration < 0:
            raise ValueError(f"on_duration must be a non-negative number, got {on_duration!r}.")
        if not isinstance(off_duration, (int, float)) or off_duration < 0:
            raise ValueError(f"off_duration must be a non-negative number, got {off_duration!r}.")

        self.on()
        time.sleep(on_duration)
        self.off()
        time.sleep(off_duration)

    def cleanup(self):
        """Turn the LED off and release the gpiozero resource."""
        if self.led is not None:
            try:
                self.led.off()
            except Exception:
                pass
            try:
                self.led.close()
            except Exception:
                pass
            self.led = None


def main():
    controller = None
    try:
        controller = LEDController(LED_PIN)
        print(f"LEDController initialized on GPIO{LED_PIN} (BCM).")

        while True:
            controller.blink(1.0, 0.5)

    except ValueError as exc:
        print(f"Configuration error: {exc}", file=sys.stderr)
    except RuntimeError as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
    except KeyboardInterrupt:
        print("\nInterrupted by user.", file=sys.stderr)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        if controller is not None:
            controller.cleanup()
            print("LED turned off and GPIO released.")


if __name__ == "__main__":
    main()

