import signal
import sys
import time

try:
    from gpiozero import PWMOutputDevice
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

SERVO_PIN = 18
MIN_ANGLE = 0
MAX_ANGLE = 180
MIN_DUTY = 2.5
MAX_DUTY = 12.5
HEART_RATE_VALUES = [62, 75, 88, 110, 95]
PAUSE_SECONDS = 0.8

servo = None
running = True


def signal_handler(signum, frame):
    global running
    running = False


def angle_to_duty(angle):
    return (angle / 180.0) * (MAX_DUTY - MIN_DUTY) + MIN_DUTY


def main():
    global servo

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        servo = PWMOutputDevice(SERVO_PIN, frequency=50, initial_value=0)
    except Exception as e:
        print(f"Error: Failed to initialize PWM on GPIO{SERVO_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        for heart_rate in HEART_RATE_VALUES:
            if not running:
                break

            angle = (heart_rate - 60) * (MAX_ANGLE - MIN_ANGLE) / 60 + MIN_ANGLE
            duty = angle_to_duty(angle)

            try:
                servo.value = duty / 100.0
            except Exception as e:
                print(f"Warning: Failed to set servo duty cycle: {e}", file=sys.stderr)

            print(f"Heart Rate: {heart_rate} bpm, Servo Angle: {angle:.2f} degrees")
            time.sleep(PAUSE_SECONDS)

    except Exception as e:
        print(f"Error: An unexpected error occurred: {e}", file=sys.stderr)

    finally:
        if servo is not None:
            try:
                servo.value = 0
                servo.close()
            except Exception:
                pass
        print("GPIO cleanup complete.")


if __name__ == "__main__":
    main()

