import argparse
import datetime
import json
import logging
import os
import threading
import time
from collections import deque
from pathlib import Path

try:
    from gzip import compress, decompress
    from shutil import move
except ImportError:
    raise ImportError("Required libraries (gzip, shutil) are not installed. Install with: pip install gzip shutil")

# Constants
DEFAULT_LOG_FILE = "energy_log.json"
DEFAULT_LOG_FILE_PERMISSIONS = 0o600
DEFAULT_LOG_FILE_SIZE_LIMIT = 1 * 1024 * 1024  # 1 MB
DEFAULT_SENSOR_COUNT = 3
SENSOR_DATA_MIN = {
    "active_power": 50,
    "voltage": 220,
    "current": 0.2,
    "frequency": 59.5,
    "power_factor": 0.8,
}
SENSOR_DATA_MAX = {
    "active_power": 200,
    "voltage": 240,
    "current": 1.0,
    "frequency": 60.5,
    "power_factor": 1.0,
}
SENSOR_DATA_AVG = {
    "active_power": 125,
    "voltage": 230,
    "current": 0.6,
    "frequency": 60.0,
    "power_factor": 0.95,
}

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


class EnergyMonitor:
    """
    Simulates MCP39F511N power monitoring sensors and logs data to a JSON file.
    Provides a command-line interface for viewing data, retrieving logs, and managing settings.
    """

    def __init__(self, sensor_count=DEFAULT_SENSOR_COUNT):
        self.sensor_count = sensor_count
        self.log_file_name = DEFAULT_LOG_FILE
        self.log_file_permissions = DEFAULT_LOG_FILE_PERMISSIONS
        self.log_file_size_limit = DEFAULT_LOG_FILE_SIZE_LIMIT
        self.data_buffer = deque(maxlen=1000)
        self.stop_event = threading.Event()
        self.lock = threading.Lock()
        self.log_file_path = None
        self.current_date = None
        self.running = True

        self.sensors = [
            {"id": 1, "active_power": SENSOR_DATA_MIN["active_power"], "voltage": SENSOR_DATA_MIN["voltage"],
             "current": SENSOR_DATA_MIN["current"], "frequency": SENSOR_DATA_MIN["frequency"],
             "power_factor": SENSOR_DATA_MIN["power_factor"]},
            {"id": 2, "active_power": SENSOR_DATA_MAX["active_power"], "voltage": SENSOR_DATA_MAX["voltage"],
             "current": SENSOR_DATA_MAX["current"], "frequency": SENSOR_DATA_MAX["frequency"],
             "power_factor": SENSOR_DATA_MAX["power_factor"]},
            {"id": 3, "active_power": SENSOR_DATA_AVG["active_power"], "voltage": SENSOR_DATA_AVG["voltage"],
             "current": SENSOR_DATA_AVG["current"], "frequency": SENSOR_DATA_AVG["frequency"],
             "power_factor": SENSOR_DATA_AVG["power_factor"]},
        ]

    def initialize(self):
        """Initializes the log file and starts the data acquisition thread."""
        try:
            self.log_file_path = self._get_log_file_path()
            if not os.path.exists(os.path.dirname(self.log_file_path)):
                os.makedirs(os.path.dirname(self.log_file_path), exist_ok=True)

            self._rotate_log_if_needed()
            self.current_date = datetime.date.today()
            self.log_file_name = f"energy_log_{self.current_date.strftime('%Y-%m-%d')}.json"
            self.log_file_path = self._get_log_file_path()

            self.stop_event.clear()
            self.running = True
            self.data_acquisition_thread = threading.Thread(target=self._acquire_data, daemon=True)
            self.data_acquisition_thread.start()
            logger.info("Energy monitor initialized successfully.")
        except Exception as e:
            logger.error(f"Error initializing energy monitor: {e}")
            raise

    def _get_log_file_path(self):
        return Path(self.log_file_name).resolve()

    def _rotate_log_if_needed(self):
        if not self.log_file_path:
            return
        try:
            if os.path.exists(self.log_file_path) and os.path.getsize(self.log_file_path) > self.log_file_size_limit:
                self._rotate_log_file()
        except Exception as e:
            logger.error(f"Error checking log file size: {e}")

    def _rotate_log_file(self):
        try:
            compressed_file_name = f"{self.log_file_path.stem}_{self.log_file_path.suffix}_" \
                                   f"{self.log_file_path.stat().st_mtime.strftime('%H%M%S')}.json.gz"
            compressed_path = self.log_file_path.with_suffix(compressed_file_name)

            with open(self.log_file_path, "rb") as f:
                compressed_data = compress(f.read())

            move(str(self.log_file_path), str(compressed_path))
            os.rename(str(compressed_path), str(self.log_file_path))
            logger.info("Log file rotated successfully.")
        except Exception as e:
            logger.error(f"Error rotating log file: {e}")

    def _acquire_data(self):
        """Acquires sensor data in a loop and logs it to the file."""
        while not self.stop_event.is_set():
            try:
                with self.lock:
                    current_time = time.time()
                    timestamp = datetime.datetime.fromtimestamp(current_time).strftime("%Y-%m-%d %H:%M:%S")

                    for sensor in self.sensors:
                        sensor["timestamp"] = timestamp
                        sensor["id"] = sensor["id"]

                    self.data_buffer.append(self.sensors.copy())

                    if self.data_buffer:
                        self._write_log_entry(self.data_buffer.popleft())

                self.stop_event.wait(5)
            except Exception as e:
                logger.error(f"Error acquiring data: {e}")
                time.sleep(1)

    def _write_log_entry(self, data):
        """Writes a single log entry to the file."""
        try:
            with open(self.log_file_path, "a") as log_file:
                log_file.write(json.dumps(data) + "\n")
                log_file.flush()
                os.fsync(log_file.fileno())
        except Exception as e:
            logger.error(f"Error writing to log file: {e}")

    def view_current_readings(self):
        """Displays the current readings for all sensors."""
        try:
            with self.lock:
                if self.data_buffer:
                    latest_data = self.data_buffer[-1]
                    print("\nCurrent Readings:")
                    for sensor in latest_data:
                        print(f"  Sensor {sensor['id']}: {sensor}")
                else:
                    print("No data available yet.")
        except Exception as e:
            logger.error(f"Error viewing current readings: {e}")

    def get_data_today(self):
        """Retrieves all data logged today."""
        try:
            with self.lock:
                if self.data_buffer:
                    today_data = []
                    for data in self.data_buffer:
                        if data["timestamp"] == self.current_date.strftime("%Y-%m-%d"):
                            today_data.append(data)

                    if today_data:
                        print("\nToday's Data:")
                        for data in today_data:
                            print(f"  Sensor {data['id']}: {data}")
                    else:
                        print("No data logged today.")
                else:
                    print("No data available yet.")
        except Exception as e:
            logger.error(f"Error retrieving today's data: {e}")

    def get_data_by_date(self):
        """Retrieves data for a specific date."""
        try:
            date_str = input("Enter the date (YYYY-MM-DD): ").strip()
            if not date_str:
                print("Invalid date format.")
                return

            date = datetime.datetime.strptime(date_str, "%Y-%m-%d").date()

            with self.lock:
                if self.data_buffer:
                    date_data = []
                    for data in self.data_buffer:
                        if data["timestamp"] == date.strftime("%Y-%m-%d"):
                            date_data.append(data)

                    if date_data:
                        print("\nData for", date.strftime("%B %d, %Y"), ":")
                        for data in date_data:
                            print(f"  Sensor {data['id']}: {data}")
                    else:
                        print("No data found for this date.")
                else:
                    print("No data available yet.")
        except ValueError:
            print("Invalid date format.")
        except Exception as e:
            logger.error(f"Error retrieving data by date: {e}")

    def get_min_max_avg(self):
        """Calculates and displays the minimum, maximum, and average active power for each sensor."""
        try:
            with self.lock:
                if self.data_buffer:
                    date_str = input("Enter the date (YYYY-MM-DD): ").strip()
                    if not date_str:
                        print("Invalid date format.")
                        return

                    date = datetime.datetime.strptime(date_str, "%Y-%m-%d").date()

                    sensor_ids = set()
                    for data in self.data_buffer:
                        if data["timestamp"] == date.strftime("%Y-%m-%d"):
                            sensor_ids.add(data["id"])

                    if not sensor_ids:
                        print("No data found for this date.")
                        return

                    min_powers = {sid: float('inf') for sid in sensor_ids}
                    max_powers = {sid: float('-inf') for sid in sensor_ids}
                    total_power = 0.0
                    count = 0

                    for data in self.data_buffer:
                        if data["timestamp"] == date.strftime("%Y-%m-%d"):
                            if data["id"] in min_powers:
                                min_powers[data["id"]] = min(min_powers[data["id"]], data["active_power"])
                                max_powers[data["id"]] = max(max_powers[data["id"]], data["active_power"])
                                total_power += data["active_power"]
                                count += 1

                    if count == 0:
                        print("No data to calculate statistics.")
                        return

                    avg_power = total_power / count

                    print("\nMinimum Active Power:")
                    for sid in sensor_ids:
                        print(f"  Sensor {sid}: {min_powers[sid]} W")

                    print("\nMaximum Active Power:")
                    for sid in sensor_ids:
                        print(f"  Sensor {sid}: {max_powers[sid]} W")

                    print("\nAverage Active Power:")
                    for sid in sensor_ids:
                        print(f"  Sensor {sid}: {avg_power:.2f} W")
                else:
                    print("No data available yet.")
        except ValueError:
            print("Invalid date format.")
        except Exception as e:
            logger.error(f"Error calculating min/max/avg: {e}")

    def shutdown(self):
        """Stops the data acquisition thread and cleans up resources."""
        if not self.running:
            return
        self.running = False
        self.stop_event.set()
        if self.data_acquisition_thread.is_alive():
            self.data_acquisition_thread.join(timeout=5)
        logger.info("Energy monitor stopped.")


def main():
    parser = argparse.ArgumentParser(description="Raspberry Pi Energy Monitoring System")
    parser.add_argument("--init", action="store_true", help="Initialize the energy monitor")
    parser.add_argument("--view", action="store_true", help="View current sensor readings")
    parser.add_argument("--today", action="store_true", help="Display today's data")
    parser.add_argument("--date", action="store_true", help="Get data by a specific date")
    parser.add_argument("--minmaxavg", action="store_true", help="Calculate min/max/avg power")
    parser.add_argument("--shutdown", action="store_true", help="Stop the energy monitor")
    args = parser.parse_args()

    try:
        monitor = EnergyMonitor()
        if args.init:
            monitor.initialize()

        if args.view:
            monitor.view_current_readings()

        if args.today:
            monitor.get_data_today()

        if args.date:
            monitor.get_data_by_date()

        if args.minmaxavg:
            monitor.get_min_max_avg()

        if args.shutdown:
            monitor.shutdown()

    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")


if __name__ == "__main__":
    main()

