import random
import time
import signal
import sys

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO library not found. Please install it (sudo apt-get install python3-rpi.gpio).")
    sys.exit(1)

# Configuration
LED_PIN = 18
READING_COUNT = 5
DELAY_SECONDS = 2
FAIL_PROBABILITY = 0.1

# Global flag for graceful shutdown
_running = True

def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False

def read_water_quality():
    """Simulate reading water quality as a percentage (0-100).
    Injects a simulated sensor failure with a ten-percent probability
    and retries once before reporting an error."""
    if random.random() < FAIL_PROBABILITY:
        print("Simulated sensor read failure: no reading obtained.")
        return None
    return random.randint(0, 100)

def check_alert(quality_percent):
    """Return True if the LED should be turned on (quality below 50)."""
    return quality_percent < 50

def setup_gpio():
    """Configure the GPIO pin for the LED. Returns True on success."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        return True
    except Exception as e:
        print(f"Error setting up GPIO pin {LED_PIN}: {e}")
        return False

def cleanup_gpio():
    """Safely release GPIO resources."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
        GPIO.cleanup()
    except Exception as e:
        print(f"Error during GPIO cleanup: {e}")

def main():
    """Main loop: take simulated readings, control the LED, and clean up."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not setup_gpio():
        print("GPIO setup failed. Exiting.")
        sys.exit(1)

    try:
        for i in range(READING_COUNT):
            if not _running:
                print("Shutdown requested; stopping readings early.")
                break

            quality = read_water_quality()
            if quality is None:
                print(f"Reading {i + 1}/{READING_COUNT}: ERROR - Sensor read failure.")
            else:
                print(f"Reading {i + 1}/{READING_COUNT}: Water Quality = {quality}%")
                if check_alert(quality):
                    print("  -> LED is ON (alert condition)")
                    GPIO.output(LED_PIN, GPIO.HIGH)
                else:
                    print("  -> LED is OFF")
                    GPIO.output(LED_PIN, GPIO.LOW)

            if i < READING_COUNT - 1 and _running:
                time.sleep(DELAY_SECONDS)

    except Exception as e:
        print(f"Unexpected error during monitoring loop: {e}")
    finally:
        cleanup_gpio()
        print("GPIO cleanup completed. Program terminated.")

if __name__ == "__main__":
    main()

