import csv
import time
import signal
import sys
import logging
import math

try:
    import smbus2 as smbus
except ImportError:
    import smbus

import RPi.GPIO as GPIO

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
I2C_BUS = 1
MPU6050_ADDR = 0x68
WHO_AM_I = 0x75

ACCEL_SCALE = 16384.0  # LSB/g for +/-2g range
IMPACT_THRESHOLD_G = 3.0   # 29.43 m/s^2
WEIGHTLESS_THRESHOLD_G = 0.5  # 4.905 m/s^2
SAMPLE_RATE_HZ = 25
FLUSH_INTERVAL_S = 5.0
ALERT_GPIO = 17
ALERT_DURATION_S = 2.0

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("fall_detection")

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_bus = None
_csv_file = None


def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received – shutting down.", signum)
    _running = False


def _cleanup():
    global _bus, _csv_file
    if _csv_file is not None:
        try:
            _csv_file.flush()
            _csv_file.close()
        except Exception:
            pass
        _csv_file = None
    if _bus is not None:
        try:
            _bus.close()
        except Exception:
            pass
        _bus = None
    try:
        GPIO.output(ALERT_GPIO, GPIO.LOW)
    except Exception:
        pass
    try:
        GPIO.cleanup()
    except Exception:
        pass


def _read_word(bus, reg):
    """Read a 16-bit signed big-endian value from two consecutive registers."""
    try:
        high = bus.read_byte_data(MPU6050_ADDR, reg)
        low = bus.read_byte_data(MPU6050_ADDR, reg + 1)
    except OSError as exc:
        log.warning("I2C read error at reg 0x%02X: %s", reg, exc)
        raise
    raw = (high << 8) | low
    if raw >= 0x8000:
        raw -= 0x10000
    return raw


def _init_sensor():
    """Verify the MPU6050 with WHO_AM_I before opening the I2C bus."""
    try:
        who = _read_word(None, WHO_AM_I)
    except OSError:
        log.warning("No MPU6050 detected at address 0x%02X on bus %d.", MPU6050_ADDR, I2C_BUS)
        return False
    if who != 0x68:
        log.warning("WHO_AM_I mismatch: got 0x%02X, expected 0x68.", who)
        return False
    return True


def _init_i2c():
    global _bus
    try:
        _bus = smbus.SMBus(I2C_BUS)
    except OSError as exc:
        log.warning("Cannot open I2C bus %d: %s", I2C_BUS, exc)
        return False
    return True


def _init_csv(path):
    global _csv_file
    try:
        _csv_file = open(path, "w", newline="")
    except OSError as exc:
        log.warning("Cannot open CSV file %s: %s", path, exc)
        return False
    try:
        writer = csv.writer(_csv_file)
        writer.writerow(["Timestamp", "X", "Y", "Z", "FallDetected"])
    except OSError as exc:
        log.warning("Cannot write CSV header: %s", exc)
        try:
            _csv_file.close()
        except Exception:
            pass
        _csv_file = None
        return False
    return True


def _read_accel():
    """Return (x, y, z) in g, or None on error."""
    try:
        x = _read_word(_bus, 0x3B) / ACCEL_SCALE
        y = _read_word(_bus, 0x3D) / ACCEL_SCALE
        z = _read_word(_bus, 0x39) / ACCEL_SCALE
    except OSError:
        return None
    except Exception as exc:
        log.warning("Unexpected read error: %s", exc)
        return None
    return x, y, z


def _moving_average(data, window=3):
    if len(data) < window:
        return 0.0
    return sum(data[-window:]) / window


def _detect_fall(accel_history):
    if len(accel_history) < 2:
        return False
    magnitude = math.sqrt(sum(v * v for v in accel_history))
    if magnitude > IMPACT_THRESHOLD_G:
        return False
    # Weightlessness window: magnitude must stay below weightlessness threshold
    window = [h for h in accel_history if magnitude <= WEIGHTLESS_THRESHOLD_G]
    if not window:
        return False
    return (time.time() - window[-1][0]) < 1.0


def _trigger_alert():
    try:
        GPIO.output(ALERT_GPIO, GPIO.HIGH)
    except Exception as exc:
        log.warning("Failed to set alert GPIO HIGH: %s", exc)
    time.sleep(ALERT_DURATION_S)
    try:
        GPIO.output(ALERT_GPIO, GPIO.LOW)
    except Exception as exc:
        log.warning("Failed to set alert GPIO LOW: %s", exc)


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setup(ALERT_GPIO, GPIO.OUT, initial=GPIO.LOW)

    if not _init_sensor():
        _cleanup()
        sys.exit(0)

    if not _init_i2c():
        _cleanup()
        sys.exit(0)

    csv_path = "accel_data.csv"
    if not _init_csv(csv_path):
        _cleanup()
        sys.exit(0)

    accel_history = []
    log.info("Fall detection started (I2C bus %d, GPIO%d).", I2C_BUS, ALERT_GPIO)

    try:
        while _running:
            loop_start = time.monotonic()

            accel = _read_accel()
            if accel is None:
                log.warning("Sensor read failed – skipping sample.")
            else:
                accel_history.append(accel)
                x, y, z = accel
                timestamp = time.monotonic()
                fall = _detect_fall(accel_history)
                try:
                    writer = csv.writer(_csv_file)
                    writer.writerow([timestamp, x, y, z, fall])
                    _csv_file.flush()
                except OSError as exc:
                    log.warning("CSV write error: %s", exc)

                if fall:
                    log.warning("Fall detected!")
                    _trigger_alert()

            elapsed = time.monotonic() - loop_start
            remaining = FLUSH_INTERVAL_S - elapsed
            if remaining > 0:
                time.sleep(remaining)
    finally:
        _cleanup()
        log.info("Program terminated.")


if __name__ == "__main__":
    main()

