import socket
import json
import time
import signal
import sys
import random

try:
    import board
    import busio
    import adafruit_gps
except ImportError:
    print("Missing dependencies. Install with: pip install adafruit-circuitpython-gps", file=sys.stderr)
    sys.exit(1)

HOST = '127.0.0.1'
PORT = 9099

running = True
gps = None
uart = None


def signal_handler(signum, frame):
    global running
    running = False


def read_gps_position():
    global gps, uart
    if gps is not None:
        try:
            if gps.data_ready():
                return gps.latitude, gps.longitude
        except Exception as e:
            print(f"GPS read error: {e}", file=sys.stderr)
    return None, None


def handle_command(command):
    if command == "start":
        return True
    elif command == "stop":
        return False
    elif command == "report":
        lat, lon = read_gps_position()
        if lat is not None and lon is not None:
            return {"lat": lat, "lon": lon}
        return None
    return None


def main():
    global gps, uart
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        uart = busio.UART(board.UART1, baudrate=9600)
        try:
            gps = adafruit_gps.GPS(uart)
            gps.data_ready_event = None
        except Exception as e:
            print(f"GPS init failed: {e}", file=sys.stderr)
            gps = None
    except Exception as e:
        print(f"UART init failed: {e}", file=sys.stderr)
        gps = None

    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        s.bind((HOST, PORT))
        s.listen(1)
        s.settimeout(1.0)
        print(f"Listening on {HOST}:{PORT}")

    try:
        while running:
            try:
                conn, addr = s.accept()
            except socket.timeout:
                continue
            except OSError:
                break

            with conn:
                data = conn.recv(1024)
                if not data:
                    continue
                command = data.decode('utf-8', errors='ignore').strip()
                if not command:
                    continue

                try:
                    result = handle_command(command)
                    if result is not None:
                        conn.sendall(json.dumps(result).encode('utf-8'))
                except Exception as e:
                    print(f"Command error: {e}", file=sys.stderr)
                    conn.sendall(b"error")
    finally:
        if uart is not None:
            try:
                uart.deinit()
            except Exception:
                pass
        print("Shutdown complete.")


if __name__ == "__main__":
    main()

