import signal
import sys
import time

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install it with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

LED1_PIN = 18
LED2_PIN = 23
led1 = None
led2 = None
running = True

def cleanup():
    global led1, led2
    for led in (led1, led2):
        if led is not None:
            try:
                led.close()
            except Exception:
                pass
    led1 = None
    led2 = None

def signal_handler(sig, frame):
    global running
    running = False

def control_leds(state):
    if led1 is None or led2 is None:
        return
    try:
        if state:
            led1.on()
            led2.on()
        else:
            led1.off()
            led2.off()
    except (GPIODeviceError, GPIOZeroError) as e:
        print(f"Error controlling LEDs: {e}", file=sys.stderr)

def main():
    global led1, led2
    try:
        led1 = LED(LED1_PIN)
        led2 = LED(LED2_PIN)
    except (GPIODeviceError, GPIOZeroError) as e:
        print(f"Error initializing GPIO pins {LED1_PIN} and {LED2_PIN}: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    signal.signal(signal.SIGINT, signal_handler)

    try:
        for i in range(5):
            if not running:
                break
            control_leds(True)
            time.sleep(1)
            if not running:
                break
            control_leds(False)
            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error during LED control: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

