            if i < NUM_CHECKS - 1:
                time.sleep(CHECK_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user. Exiting gracefully...")
    finally:
        # Ensure the LED is off before the program exits.
        alert_led.off()
        alert_led.close()


