import smbus
import time
import signal
import sys

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1
LIS3DH_ADDR = 0x1C

LED_PIN = 21
BUZZER_PIN = 20

X_THRESHOLD_G = 0.3
CRITICAL_THRESHOLD_G = 0.7

SAMPLE_INTERVAL_S = 1.0
SAMPLE_DELAY_S = 0.1

# --- Globals for cleanup -----------------------------------------------------
_bus = None
_led_on = False
_buzzer_on = False
_running = True


def _cleanup():
    """Turn off outputs and close the I2C bus on any exit path."""
    global _bus, _led_on, _buzzer_on
    try:
        if _led_on:
            try:
                _bus.write_byte_data(LIS3DH_ADDR, 0x06, 0x00)
            except OSError:
                pass
            _led_on = False
    except OSError:
        pass
    try:
        if _buzzer_on:
            try:
                _bus.write_byte_data(LIS3DH_ADDR, 0x0E, 0x00)
            except OSError:
                pass
            _buzzer_on = False
    except OSError:
        pass
    if _bus is not None:
        try:
            _bus.close()
        except OSError:
            pass
        _bus = None


def _signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for clean shutdown."""
    global _running
    _running = False


def _write_reg(bus, reg, value):
    """Write a single byte to a register with a short delay after the write."""
    bus.write_byte_data(LIS3DH_ADDR, reg, value)
    time.sleep(0.01)


def _read_signed_word(bus):
    """Read two bytes from the accelerometer and return a signed 16-bit value."""
    data = bus.read_i2c_block_data(LIS3DH_ADDR, 0x00, 2)
    raw = (data[0] << 8) | data[1]
    if raw >= 0x8000:
        raw -= 0x10000
    return raw


def main():
    global _bus, _led_on, _buzzer_on, _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGTERM, _signal_handler)

    # --- GPIO setup ----------------------------------------------------------
    try:
        from gpiozero import LED, OutputDevice
    except ImportError:
        print("Error: gpiozero is required. Install with: pip install gpiozero", file=sys.stderr)
        sys.exit(1)

    try:
        led = LED(LED_PIN)
        buzzer = OutputDevice(BUZZER_PIN)
    except Exception as e:
        print(f"Error: Failed to initialize GPIO pins: {e}", file=sys.stderr)
        sys.exit(1)

    _led_on = False
    _buzzer_on = False

    # --- I2C setup -----------------------------------------------------------
    try:
        _bus = smbus.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: Cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    # --- LIS3DH verification ------------------------------------------------
    try:
        who = _bus.read_byte_data(LIS3DH_ADDR, 0x0F)
    except OSError as e:
        print(f"Error: Cannot read WHO_AM_I from LIS3DH at 0x{LIS3DH_ADDR:02X}: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    if who != 0x3D:
        print(f"Error: Unexpected WHO_AM_I value 0x{who:02X} (expected 0x3D). "
              "Not a LIS3DH or a wrong address.", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    print("LIS3DH detected. Starting acceleration monitoring...")

    # --- Main loop -----------------------------------------------------------
    try:
        while _running:
            try:
                x = _read_signed_word(_bus)
            except OSError as e:
                print(f"Warning: I2C read error: {e}", file=sys.stderr)
                # Safety: turn off outputs on any I2C error
                _led_on = False
                _buzzer_on = False
                continue

            print(f"Accel X: {x / 100.0:.2f} g")

            if abs(x) > CRITICAL_THRESHOLD_G:
                if not _buzzer_on:
                    _write_reg(_bus, 0x0E, 0x01)
                    _buzzer_on = True
                if not _led_on:
                    _write_reg(_bus, 0x06, 0x01)
                    _led_on = True
            elif abs(x) > X_THRESHOLD_G:
                if _led_on:
                    _write_reg(_bus, 0x06, 0x00)
                    _led_on = False
            else:
                if _led_on:
                    _write_reg(_bus, 0x06, 0x00)
                    _led_on = False
                if _buzzer_on:
                    _write_reg(_bus, 0x0E, 0x00)
                    _buzzer_on = False

            time.sleep(SAMPLE_DELAY_S)

    except KeyboardInterrupt:
        print("\nKeyboardInterrupt received. Shutting down...")
    finally:
        _cleanup()
        print("Exited cleanly.")


if __name__ == "__main__":
    main()

