import smbus
import time
import threading
import signal
import sys

# MPU-6050 constants
MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
GYRO_XOUT_H = 0x43
GYRO_YOUT_H = 0x45
GYRO_ZOUT_H = 0x47

# GPIO pins for motor control (BCM numbering)
MOTOR_PINS = {1: 17, 2: 18, 3: 27}

# PWM frequency (Hz)
PWM_FREQ = 50

# Log file
LOG_FILE = "log.txt"

# Global state
running = True
kp = {1: 1.0, 2: 1.0, 3: 1.0}
pwm_instances = {}
bus = None


def log_data(motor, pwm_value, angle):
    """Append a line to the log file."""
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    line = f"{timestamp}, Motor {motor}, Angle: {angle:.2f}, PWM: {pwm_value:.2f}\n"
    try:
        with open(LOG_FILE, "a") as f:
            f.write(line)
    except IOError as e:
        print(f"Error writing to log file: {e}")


def read_raw_data(register):
    """Read a signed 16-bit value from two consecutive registers."""
    try:
        high = bus.read_byte_data(MPU6050_ADDR, register)
        low = bus.read_byte_data(MPU6050_ADDR, register + 1)
        value = (high << 8) | low
        if value >= 0x8000:
            value -= 0x10000
        return value
    except IOError as e:
        print(f"I2C read error at register 0x{register:02X}: {e}")
        return 0


def get_gyro_data():
    """Return (gx, gy, gz) or (0, 0, 0) if the sensor is unavailable."""
    try:
        gx = read_raw_data(GYRO_XOUT_H)
        gy = read_raw_data(GYRO_YOUT_H)
        gz = read_raw_data(GYRO_ZOUT_H)
        return gx / 131.0, gy / 131.0, gz / 131.0
    except IOError:
        return 0.0, 0.0, 0.0


def set_pwm(motor, pwm_value):
    """Set PWM duty cycle and direction for a motor."""
    pin = MOTOR_PINS[motor]
    pwm_instances[motor].ChangeDutyCycle(pwm_value)
    if pwm_value > 0:
        threading.Thread(target=lambda: _set_pin(pin, 1), daemon=True).start()
    elif pwm_value < 0:
        threading.Thread(target=lambda: _set_pin(pin, 0), daemon=True).start()


def _set_pin(pin, state):
    try:
        import RPi.GPIO as GPIO
        GPIO.output(pin, state)
    except Exception as e:
        print(f"GPIO output error on pin {pin}: {e}")


def integrate_angle(angle, velocity, dt):
    """Integrate velocity over dt to obtain angle."""
    return angle + velocity * dt


