import math
import time
import signal
import sys
import logging
import numpy as np

try:
    import smbus2
except ImportError:
    import smbus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
ACCEL_XOUT_H = 0x3B
ACCEL_SCALE = 16384.0 / 2.0  # ±2 g range, 16384 LSB/g

_running = True

def _signal_handler(signum, frame):
    global _running
    logger.info(f"Received signal {signum}, shutting down...")
    _running = False

def init_mpu6050(bus):
    try:
        bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0x00)
        time.sleep(0.1)
        return True
    except OSError as e:
        logger.error(f"Failed to initialize MPU6050: {e}")
        return False

def read_acceleration(bus):
    try:
        data = bus.read_i2c_block_data(MPU6050_ADDR, ACCEL_XOUT_H, 6)
        x = (data[0] << 8) | data[1]
        y = (data[2] << 8) | data[3]
        z = (data[4] << 8) | data[5]
        x -= 65536 if x >= 32768 else 0
        y -= 65536 if y >= 32768 else 0
        z -= 65536 if z >= 32768 else 0
        return x / ACCEL_SCALE, y / ACCEL_SCALE, z / ACCEL_SCALE
    except OSError as e:
        logger.error(f"I2C read error: {e}")
        return None, None, None

def extract_features(x_vals, threshold=2.5, variance_threshold=0.4):
    if not x_vals:
        return None, None
    magnitude = math.sqrt(sum(v * v for v in x_vals))
    variance = np.var(x_vals)
    return magnitude > threshold or variance > variance_threshold, magnitude, variance

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = None
    try:
        bus = smbus2.SMBus(1)
    except OSError as e:
        logger.error(f"Cannot open I2C bus 1: {e}")
        return

    if not init_mpu6050(bus):
        logger.error("MPU6050 not detected or initialization failed.")
        return

    try:
        while _running:
            x_vals = []
            for _ in range(8):
                if not _running:
                    break
                x, y, z = read_acceleration(bus)
                if x is None:
                    logger.warning("Sensor read failed, skipping sample.")
                    continue
                x_vals.append(x)
                time.sleep(0.01)

            if not x_vals:
                logger.warning("No valid samples collected.")
                continue

            is_defective, magnitude, variance = extract_features(x_vals)
            if is_defective:
                logger.warning(f"Defective part: magnitude={magnitude:.2f}g, variance={variance:.2f}")
            else:
                logger.info(f"Pass: magnitude={magnitude:.2f}g, variance={variance:.2f}")

    except Exception as e:
        logger.error(f"Unexpected error: {e}")
    finally:
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass
        logger.info("Resources released. Exiting.")

if __name__ == "__main__":
    main()

