try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)


LED_PIN = 17
CYCLES = 5
DELAY_SECONDS = 2
LIGHT_MIN = 0
LIGHT_MAX = 100


def read_light_level() -> int:
    """Simulate an ambient light sensor reading (0-100 %)."""
    return random.randint(LIGHT_MIN, LIGHT_MAX)


def control_led(led: LED, light_level: int) -> None:
    """Print the light level and drive the LED accordingly."""
    if light_level < 50:
        led.on()
        print(f"LED ON  (ambient light: {light_level}% < 50% threshold)")
    else:
        led.off()
        print(f"LED OFF (ambient light: {light_level}% >= 50% threshold)")


def main() -> None:
    """Run the simulated ambient-light LED controller."""
    led = None
    try:
        led = LED(LED_PIN)
        for cycle in range(1, CYCLES + 1):
            light = read_light_level()
            print(f"Cycle {cycle}/{CYCLES}: ambient light = {light}%")
            control_led(led, light)
            if cycle < CYCLES:
                time.sleep(DELAY_SECONDS)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user (Ctrl+C).")
    except GPIOZeroError as exc:
        print(f"GPIO error: {exc}")
    except Exception as exc:
        print(f"Unexpected error: {exc}")
    finally:
        if led is not None:
            led.off()
            led.close()
        print("GPIO cleanup completed.")


