import time
import sys
import signal

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("RPi.GPIO not available. Install with: pip install RPi.GPIO", file=sys.stderr)
    sys.exit(1)


class Laser:
    """Controls a laser module via a digital GPIO pin."""

    def __init__(self, pin=17):
        self.pin = pin
        self._initialized = False

    def setup(self):
        """Configure the GPIO pin as an output and ensure it starts LOW."""
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            GPIO.setup(self.pin, GPIO.OUT, initial=GPIO.LOW)
            self._initialized = True
        except Exception as exc:
            raise RuntimeError(f"Failed to initialise GPIO{self.pin}: {exc}") from exc

    def on(self):
        """Turn the laser ON."""
        if not self._initialized:
            raise RuntimeError("Laser not initialised; call setup() first.")
        GPIO.output(self.pin, GPIO.HIGH)

    def off(self):
        """Turn the laser OFF."""
        if not self._initialized:
            raise RuntimeError("Laser not initialised; call setup() first.")
        GPIO.output(self.pin, GPIO.LOW)

    def close(self):
        """Release the GPIO resource assigned to this laser."""
        if self._initialized:
            try:
                GPIO.output(self.pin, GPIO.LOW)
            except Exception:
                pass
            self._initialized = False


class Aim:
    """Controls a laser-aiming system with two servo-driven axes."""

    def __init__(self, ld, sd, hp, vp):
        if not (isinstance(ld, (int, float)) and isinstance(sd, (int, float))):
            raise TypeError("ld and sd must be numeric.")
        if not isinstance(hp, (list, tuple)) or len(hp) != 10:
            raise ValueError("hp must be a list/tuple of 10 pulse widths.")
        if not isinstance(vp, (list, tuple)) or len(vp) != 10:
            raise ValueError("vp must be a list/tuple of 10 pulse widths.")
        self.ld = float(ld)
        self.sd = float(sd)
        self.hp = hp
        self.vp = vp
        self.laser = Laser()
        self.laser.setup()

    def _move_servo(self, servo, index):
        """Move a servo to the position indexed by index (0-based)."""
        if not (0 <= index < len(servo)):
            raise ValueError(f"Index {index} out of range for servo array of length {len(servo)}.")
        pulse_width = servo[index]
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            GPIO.setup(servo['pin'], GPIO.OUT)
            GPIO.output(servo['pin'], GPIO.HIGH if pulse_width > 0.5 else GPIO.LOW)
            time.sleep(pulse_width)
            GPIO.output(servo['pin'], GPIO.LOW)
        except Exception as exc:
            raise RuntimeError(f"Failed to move servo on pin {servo['pin']}: {exc}") from exc

    def aim(self, target):
        """Aim and fire the laser at the given target index (1-based)."""
        if not isinstance(target, (list, tuple)):
            raise TypeError("target must be a list/tuple of target indices.")
        if not all(isinstance(t, int) and 1 <= t <= len(self.hp) for t in target):
            raise ValueError("All target indices must be 1-based integers within the servo range.")

        for t in target:
            idx = t - 1
            print(f"Aiming at target {t} (index {idx}).")
            self._move_servo(self.h, idx)
            self.laser.on()
            time.sleep(self.ld)
            self.laser.off()
            self._move_servo(self.h, 10)
            self._move_servo(self.v, idx)
            time.sleep(self.sd / 2)
            self._move_servo(self.v, 10)

    def cleanup(self):
        """Release all GPIO resources."""
        self.laser.off()
        self.laser.close()
        try:
            GPIO.cleanup()
        except Exception:
            pass


def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, exiting.")
    raise SystemExit(0)


def main():
    signal.signal(signal.SIGTERM, _signal_handler)
    signal.signal(signal.SIGINT, _signal_handler)

    try:
        aim = Aim(ld=0.5, sd=1.0, hp=[0.5] * 10, vp=[0.5] * 10)
        aim.aim([2, 3])
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
    finally:
        try:
            aim.cleanup()
        except NameError:
            pass


if __name__ == "__main__":
    main()

