import logging

try:
    import smbus2 as smbus
except ImportError:
    import smbus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

PCA9685_ADDRESS = 0x40
PCA9685_MODE1 = 0x00
PCA9685_PRESCALE = 0xFE
PCA9685_LED0_ON_L = 0x06
PCA9685_LED0_ON_H = 0x07
PCA9685_LED0_OFF_L = 0x08
PCA9685_LED0_OFF_H = 0x09

SERVO_MIN_PULSE = 500
SERVO_MAX_PULSE = 2500
DEFAULT_PRESCALE = 100


class PCA9685:
    def __init__(self, bus_num=1, address=PCA9685_ADDRESS):
        self.address = address
        self.bus = None
        self._running = True
        try:
            self.bus = smbus.SMBus(bus_num)
            self._init_pca9685()
            logger.info("PCA9685 initialized successfully on bus %d at address 0x%02X", bus_num, address)
        except FileNotFoundError:
            logger.error("I2C bus %d not found. Please enable I2C in raspi-config.", bus_num)
            raise
        except OSError as e:
            logger.error("Failed to communicate with PCA9685 at address 0x%02X: %s", address, e)
            raise
        except Exception as e:
            logger.error("Error initializing PCA9685: %s", e)
            raise

    def _write_byte(self, register, value):
        try:
            self.bus.write_byte_data(self.address, register, value)
        except OSError as e:
            logger.error("I2C write error to register 0x%02X: %s", register, e)
            raise

    def _read_byte(self, register):
        try:
            return self.bus.read_byte_data(self.address, register)
        except OSError as e:
            logger.error("I2C read error from register 0x%02X: %s", register, e)
            raise

    def _init_pca9685(self):
        try:
            self._write_byte(PCA9685_MODE1, 0x00)
            self._write_byte(PCA9685_PRESCALE, DEFAULT_PRESCALE)
            old_mode = self._read_byte(PCA9685_MODE1)
            self._write_byte(PCA9685_MODE1, (old_mode & 0x7F) | 0x10)
            time.sleep(0.005)
            self._write_byte(PCA9685_MODE1, old_mode)
        except Exception as e:
            logger.error("Error initializing PCA9685 registers: %s", e)
            raise

    def set_pwm(self, channel, on, off):
        if not 0 <= channel <= 15:
            raise ValueError("Channel must be between 0 and 15")
        reg = PCA9685_LED0_ON_L + 4 * channel
        try:
            self._write_byte(reg, on & 0xFF)
            self._write_byte(reg + 1, on >> 8)
            self._write_byte(reg + 2, off & 0xFF)
            self._write_byte(reg + 3, off >> 8)
        except Exception as e:
            logger.error("Error setting PWM for channel %d: %s", channel, e)
            raise

    def set_all_pwm(self, on, off):
        try:
            self._write_byte(PCA9685_MODE1, (self._read_byte(PCA9685_MODE1) & 0x7F) | 0x10)
            for i in range(16):
                reg = PCA9685_LED0_ON_L + 4 * i
                self._write_byte(reg, on & 0xFF)
                self._write_byte(reg + 1, on >> 8)
                self._write_byte(reg + 2, off & 0xFF)
                self._write_byte(reg + 3, off >> 8)
            self._write_byte(PCA9685_MODE1, self._read_byte(PCA9685_MODE1) & 0x7F)
        except Exception as e:
            logger.error("Error setting all PWM: %s", e)
            raise

    def cleanup(self):
        if self.bus is not None:
            try:
                self.set_all_pwm(0, 0)
            except Exception:
                pass
            try:
                self.bus.close()
            except Exception:
                pass
            self.bus = None


class ServoController:
    BASE_CHANNEL = 0
    DROP_CHANNEL = 1
    SEEK_CHANNEL = 2
    GRAB_CHANNEL = 4

    DROP_ANGLES = {
        "METAL": 135,
        "PLASTIC": 180,
        "PAPER": 90,
    }

    def __init__(self, pca, channels=16):
        if not isinstance(channels, int) or channels <= 0 or channels > 16:
            raise ValueError("Invalid number of channels. Must be an integer between 1 and 16.")
        self.pca = pca
        self.channels = channels
        self.current_angle = {ch: 90 for ch in range(self.channels)}

    def _validate_channel(self, channel):
        if not isinstance(channel, int) or not 0 <= channel < self.channels:
            raise ValueError(f"Invalid channel: {channel}. Must be 0-{self.channels - 1}.")

    def _validate_angle(self, angle):
        if not isinstance(angle, (int, float)) or not 0 <= angle <= 180:
            raise ValueError(f"Invalid angle: {angle}. Must be 0-180.")

    def move_servo(self, channel, target_angle, step_size=5, delay=0.04):
        self._validate_channel(channel)
        self._validate_angle(target_angle)
        if step_size <= 0:
            raise ValueError("step_size must be positive")
        if delay < 0:
            raise ValueError("delay must be non-negative")

        self._validate_channel(channel)
        self._validate_angle(target_angle)

        try:
            self._move_servo(channel, target_angle, step_size, delay)
        except Exception as e:
            logger.error("Error moving servo on channel %d: %s", channel, e)
            raise

    def _move_servo(self, channel, target_angle, step_size, delay):
        self._validate_channel(channel)
        self._validate_angle(target_angle)
        if step_size <= 0:
            raise ValueError("step_size must be positive")
        if delay < 0:
            raise ValueError("delay must be non-negative")

        current_pulse = SERVO_MIN_PULSE + (self.current_angle[channel] / 180.0) * (SERVO_MAX_PULSE - SERVO_MIN_PPULSE)
        target_pulse = SERVO_MIN_PULSE + (target_angle / 180.0) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE)

        if current_pulse < target_pulse:
            steps = int((target_pulse - current_pulse) / step_size) + 1
        else:
            steps = int((current_pulse - target_pulse) / step_size) + 1

        for i in range(steps):
            if not self._running:
                break
