import time
import signal
import sys

try:
    from adafruit_servokit import ServoKit
except ImportError:
    ServoKit = None

PCA9685_ADDRESS = 0x40
NUM_CHANNELS = 16
STEP_DEGREES = 5
STEP_DELAY = 0.04
MIN_CHANNEL = 0
MAX_CHANNEL = 15
MIN_ANGLE = 0
MAX_ANGLE = 180

_kit = None


def _cleanup(signum=None, frame=None):
    global _kit
    if _kit is not None:
        try:
            for ch in range(NUM_CHANNELS):
                _kit.servo[ch].angle = None
        except Exception:
            pass
        _kit = None
    if signum is not None:
        sys.exit(0)


def initialize_servokit():
    global _kit
    if ServoKit is None:
        print("Error: adafruit_servokit library not installed.")
        return None
    try:
        _kit = ServoKit(channels=NUM_CHANNELS, address=PCA9685_ADDRESS)
        return _kit
    except OSError as e:
        print(f"Error initializing ServoKit on I2C bus 1 at 0x{PCA9685_ADDRESS:02X}: {e}")
        _kit = None
        return None
    except ValueError as e:
        print(f"Error initializing ServoKit: {e}")
        _kit = None
        return None
    except Exception as e:
        print(f"Unexpected error initializing ServoKit: {e}")
        _kit = None
        return None


def validate_channel(channel):
    if not isinstance(channel, int):
        raise ValueError(f"Channel must be an integer, got {type(channel).__name__}")
    if not (MIN_CHANNEL <= channel <= MAX_CHANNEL):
        raise ValueError(
            f"Channel must be between {MIN_CHANNEL} and {MAX_CHANNEL}, got {channel}"
        )


def validate_angle(angle):
    if not isinstance(angle, (int, float)):
        raise ValueError(f"Angle must be a number, got {type(angle).__name__}")
    if not (MIN_ANGLE <= angle <= MAX_ANGLE):
        raise ValueError(
            f"Angle must be between {MIN_ANGLE} and {MAX_ANGLE}, got {angle}"
        )


def move_servo(kit, servo_call, target_angle):
    if kit is None:
        print("Error: ServoKit not initialized.")
        return False
    try:
        validate_channel(servo_call)
        validate_angle(target_angle)
        current_angle = kit.servo[servo_call].angle
        if current_angle is None:
            current_angle = MIN_ANGLE
        step = STEP_DEGREES if target_angle > current_angle else -STEP_DEGREES
        angle = current_angle
        while (
            abs(angle - target_angle) > STEP_DEGREES
            and angle != target_angle
        ):
            angle += step
            if angle < MIN_ANGLE:
                angle = MIN_ANGLE
            elif angle > MAX_ANGLE:
                angle = MAX_ANGLE
            kit.servo[servo_call].angle = angle
            time.sleep(STEP_DELAY)
        kit.servo[servo_call].angle = target_angle
        return True
    except OSError as e:
        print(f"I2C/OSError moving servo {servo_call}: {e}")
        return False
    except ValueError as e:
        print(f"ValueError moving servo {servo_call}: {e}")
        return False
    except Exception as e:
        print(f"Unexpected error moving servo {servo_call}: {e}")
        return False


def grab_object(kit, servo_call=0):
    return move_servo(kit, servo_call, 90)


def release_object(kit, servo_call=0):
    return move_servo(kit, servo_call, 150)


def main():
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)
    kit = initialize_servokit()
    if kit is None:
        print("Failed to initialize ServoKit. Exiting.")
        sys.exit(1)
    try:
        grab_object(kit, 0)
        time.sleep(1)
        release_object(kit, 0)
        time.sleep(1)
        move_servo(kit, 0, 45)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

