import time
import logging
import signal
import sys
import paho.mqtt.client as mqtt

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

KEYWORD_CLASSIFIER = {
    "noise": {"noise": 1},
    "traffic": {"traffic": 1},
    "other": {"other": 1},
}

TRAFFIC_KEYWORDS = {"car", "bus", "truck", "train", "road"}


def classify_report(report_text):
    """Classifies a given report text into 'noise', 'traffic', or 'other'."""
    if not report_text:
        return "noise"
    if "traffic" in report_text.lower() and any(kw in report_text.lower() for kw in TRAFFIC_KEYWORDS):
        return "traffic"
    return "other"


def handle_message(mqtt_client, userdata, message):
    """Handles incoming MQTT messages, classifies the report, and updates counts."""
    try:
        payload = message.payload.decode("utf-8")
        report_text = payload
        category = classify_report(report_text)
        logging.info(f"Received report: {report_text}, Category: {category}")

        if category == "traffic":
            userdata["traffic_count"] += 1
        elif category == "noise":
            userdata["noise_count"] += 1
        else:
            userdata["other_count"] += 1

        logging.info(f"Classification counts - Traffic: {userdata['traffic_count']}, Noise: {userdata['noise_count']}, Other: {userdata['other_count']}")
    except UnicodeDecodeError:
        logging.error(f"Failed to decode payload: {message.payload}")
    except Exception as e:
        logging.error(f"Error processing message: {e}")


def on_connect(mqtt_client, userdata, flags, reason_code, properties):
    """Callback for when the client connects to the broker."""
    if reason_code == 0:
        logging.info("Connected to MQTT broker successfully.")
        mqtt_client.subscribe("city/reports", qos=1)
    else:
        logging.error(f"Failed to connect to MQTT broker. Reason code: {reason_code}")


def on_disconnect(mqtt_client, userdata, flags, reason_code, properties):
    """Callback for when the client disconnects from the broker."""
    logging.info(f"Disconnected from MQTT broker. Reason code: {reason_code}")


def signal_handler(sig, frame):
    """Handles interrupt signals for graceful shutdown."""
    logging.info("Interrupt received, shutting down...")
    sys.exit(0)


def main():
    """Main function to set up and run the MQTT client."""
    signal.signal(signal.SIGINT, signal_handler)

    mqtt_client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2)
    mqtt_client.user_data_set({
        "traffic_count": 0,
        "noise_count": 0,
        "other_count": 0,
    })

    mqtt_client.on_connect = on_connect
    mqtt_client.on_disconnect = on_disconnect
    mqtt_client.on_message = handle_message

    try:
        mqtt_client.connect("localhost", 1883, 60)
        mqtt_client.loop_start()
        time.sleep(5)
    except ConnectionRefusedError:
        logging.error("Connection refused. Ensure the MQTT broker is running.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        logging.info("Stopping MQTT loop and disconnecting...")
        mqtt_client.loop_stop()
        mqtt_client.disconnect()
        logging.info(f"Final classification counts - Traffic: {userdata['traffic_count']}, Noise: {userdata['noise_count']}, Other: {userdata['other_count']}")


if __name__ == "__main__":
    main()

