    logger.info(f"Signal {signum} received, shutting down...")
    running = False


def read_supply_data(ina):
    try:
        ina.read_supply_voltage()
        ina.read_shunt_voltage()
        return ina.get_bus_voltage(), ina.get_shunt_voltage()
    except DeviceRangeError:
        logger.warning("Supply data out of range for the INA219 sensor.")
        return None, None
    except OSError as e:
        logger.error(f"I2C error reading supply data: {e}")
        return None, None
    except Exception as e:
        logger.error(f"Unexpected error reading supply data: {e}")
        return None, None


def configure_ina219(ina, name, supply_voltage, shunt_resistor):
    try:
        ina.configure()
        ina.set_supply_voltage(supply_voltage)
        ina.set_shunt_resistor(shunt_resistor)
        ina.set_calibration_data(4096)
        ina.set_current_limit(1000)
        logger.info(f"{name} configured successfully.")
    except OSError as e:
        logger.error(f"I2C error configuring {name}: {e}")
    except Exception as e:
