        logger.info(f"I2C bus {I2C_BUS} initialized.")

        supply_ina = INA219(bus, address=0x40)
        configure_ina219(supply_ina, "Supply INA219", SUPPLY_VOLTAGE, SHUNT_RESISTOR)

        battery_ina = INA219(bus, address=0x41)
        configure_ina219(battery_ina, "Battery INA219", BATTERY_VOLTAGE, BATTERY_SHUNT_RESISTOR)

        logger.info("Starting monitoring loop (5-second interval).")

        while running:
            supply_v, supply_shunt = read_supply_data(supply_ina)
            if supply_v is not None and supply_shunt is not None:
                logger.info(f"Supply Voltage: {supply_v:.3f} V, Shunt Voltage: {supply_shunt:.3f} mV")

            battery_v, battery_shunt = read_battery_data(battery_ina)
            if battery_v is not None and battery_shunt is not None:
                logger.info(f"Battery Voltage: {battery_v:.3f} V, Shunt Voltage: {battery_shunt:.3f} mV")

            time.sleep(5)

    except FileNotFoundError:
        logger.error(f"I2C bus {I2C_BUS} not found. Check your Raspberry Pi configuration.")
