import serial
import time
import signal
import sys

OK_STATUS = b"OK"
ERROR_STATUS = b"ERROR"
FAIL_STATUS = b"FAIL"

DEFAULT_TIMEOUT = 1.0


class ESP8266Error(Exception):
    """Custom exception for ESP8266 communication errors."""
    pass


class ESP8266:
    """
    A class for interacting with the ESP8266 WiFi module via AT commands over UART.
    """

    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=DEFAULT_TIMEOUT):
        self._port = port
        self._baud_rate = baud_rate
        self._timeout = timeout
        self._uart = None
        self._running = False

        try:
            self._uart = serial.Serial(
                port=self._port,
                baudrate=self._baud_rate,
                timeout=self._timeout
            )
            if not self._uart.is_open:
                raise ESP8266Error(f"Failed to open UART port {self._port}")
        except serial.SerialException as e:
            raise ESP8266Error(f"Error initializing UART: {e}") from e

    def _send_command(self, command, wait_for_reply=True, timeout=None):
        """
        Sends an AT command to the ESP8266 and reads the response.

        Args:
            command (bytes): The AT command to send.
            wait_for_reply (bool): Whether to wait for a reply from the ESP8266.
            timeout (float): Override timeout for this specific command.

        Returns:
            bytes: The response from the ESP8266, or None if an error occurred or no reply was expected.
        """
        if self._uart is None or not self._uart.is_open:
            raise ESP8266Error("UART port is not open.")

        try:
            self._uart.reset_input_buffer()
            self._uart.write(command)
            self._uart.flush()

            if wait_for_reply:
                if timeout is None:
                    timeout = self._timeout
                end_time = time.time() + timeout
                response = b""
                while time.time() < end_time:
                    if self._uart.in_waiting > 0:
                        response += self._uart.read(self._uart.in_waiting)
                    if OK_STATUS in response or ERROR_STATUS in response or FAIL_STATUS in response:
                        break
                    time.sleep(0.01)
                return response if OK_STATUS in response or ERROR_STATUS in response or FAIL_STATUS in response else None
            return b""
        except serial.SerialException as e:
            raise ESP8266Error(f"Serial communication error: {e}") from e

    def test_connection(self):
        """Tests the connection to the ESP8266."""
        try:
            response = self._send_command(b"AT\r\n")
            return bool(response)
        except ESP8266Error:
            return False

    def restart(self):
        """Restarts the ESP8266 module."""
        try:
            response = self._send_command(b"AT+RST\r\n", wait_for_reply=True, timeout=10.0)
            if response is not None and OK_STATUS in response:
                time.sleep(2.0)
                return self.test_connection()
            return False
        except ESP8266Error:
            return False

    def connect_wifi(self, ssid, password):
        """Connects to a WiFi network."""
        try:
            command = f'AT+CWJAP="{ssid}","{password}"\r\n'.encode()
            response = self._send_command(command, wait_for_reply=True, timeout=10.0)
            return bool(response)
        except ESP8266Error:
            return False

    def disconnect_wifi(self):
        """Disconnects from the WiFi network."""
        try:
            response = self._send_command(b"AT+CWQAP\r\n", wait_for_reply=True, timeout=5.0)
            return bool(response)
        except ESP8266Error:
            return False

    def get_ip(self):
        """Retrieves the IP address of the ESP8266."""
        try:
            response = self._send_command(b"AT+CIFSR\r\n", wait_for_reply=True, timeout=10.0)
            if response is not None and b"STAIP" in response:
                try:
                    ip_start = response.find(b"STAIP:") + 5
                    ip_end = response.find(b",\r\n", ip_start)
                    if ip_end != -1:
                        return response[ip_start:ip_end].decode().strip()
                except ValueError:
                    pass
            return None
        except ESP8266Error:
            return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        """Sends an HTTP request to a server."""
        if headers is None:
            headers = {}
        request = (
            f"{method} {url} HTTP/1.1\r\n"
            f"Host: {host}\r\n"
        )
        for key, value in headers.items():
            request += f"{key}: {value}\r\n"
        request += f"Content-Length: {len(data)}\r\n\r\n"
        if data:
            request += data
        request += "\r\n"

        try:
            response = self._send_command(
                (b"AT+CIPSTART=\"TCP\",\"" + host.encode() + b"\",")
                + port.encode() + b"\r\n",
                wait_for_reply=True,
                timeout=10.0
            )
            if response is None or b"OK" not in response:
                return None

            response = self._send_command(
                b"AT+CIPSEND=" + str(len(request)).encode() + b"\r\n",
                wait_for_reply=True,
                timeout=5.0
            )
            if response is None or b">" not in response:
                self._send_command(b"AT+CIPCLOSE\r\n", wait_for_reply=True, timeout=5.0)
                return None

            response = self._send_command(request.encode(), wait_for_reply=True, timeout=10.0)
            if response is None:
                self._send_command(b"AT+CIPCLOSE\r\n", wait_for_reply=True, timeout=5.0)
                return None

            self._send_command(b"AT+CIPCLOSE\r\n", wait_for_reply=True, timeout=5.0)
            return response
        except ESP8266Error:
            return None

    def receive_http_response(self, timeout=5.0):
        """Receives the HTTP response from the server."""
        try:
            response = b""
            end_time = time.time() + timeout
            while time.time() < end_time:
                if self._uart.in_waiting > 0:
                    response += self._uart.read(self._uart.in_waiting)
                    if b"+IPD," in response:
                        break
                time.sleep(0.01)
            return response if b"+IPD," in response else None
        except serial.SerialException as e:
            raise ESP8266Error(f"Serial communication error: {e}") from e


_esp = None


def _cleanup(signum=None, frame=None):
    global _esp
    if _esp is not None:
        try:
            if hasattr(_esp, 'close'):
                _esp.close()
        except Exception:
            pass
        _esp = None
    if signum is not None:
        sys.exit(0)


def main():
    global _esp
    signal.signal(signal.SIGTERM, _cleanup)
    signal.signal(signal.SIGINT, _cleanup)

    try:
        _esp = ESP8266(port='/dev/serial0', baud_rate=115200, timeout=DEFAULT_TIMEOUT)
        _esp._running = True

        if not _esp.test_connection():
            print("Failed to connect to ESP8266. Check wiring and UART settings.")
            return

        print("ESP8266 connection tested successfully.")

        if not _esp.restart():
            print("Failed to restart ESP8266.")
            return

        print("ESP8266 restarted successfully.")

        if not _esp.connect_wifi("SSID", "PASSWORD"):
            print("Failed to connect to WiFi.")
            return

        print("Connected to WiFi.")

        ip = _esp.get_ip()
        print(f"IP Address: {ip}")

    except ESP8266Error as e:
        print(f"Error: {e}")
    finally:
        _cleanup()


if __name__ == '__main__':
    main()

