import serial
import time
import signal
import sys

PORT = "/dev/serial0"
BAUD = 9600
TIMEOUT = 1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def nmea_to_decimal(raw, hemi):
    if not raw or not hemi:
        raise ValueError("Empty coordinate field")
    dot = raw.find(".")
    if dot < 0:
        raise ValueError("Malformed coordinate")
    deg_len = dot - 2
    if deg_len <= 0:
        raise ValueError("Malformed coordinate")
    degrees = float(raw[:deg_len])
    minutes = float(raw[deg_len:])
    decimal = degrees + minutes / 60.0
    if hemi in ("S", "W"):
        decimal = -decimal
    return decimal

def parse_gprmc(line):
    if not line.startswith("$GPRMC"):
        return None, None
    fields = line.split(",")
    if len(fields) < 10:
        return None, None
    if fields[2] != "A":
        return None, None
    lat = fields[3]
    lat_hemi = fields[4]
    lon = fields[5]
    lon_hemi = fields[6]
    try:
        lat_dec = nmea_to_decimal(lat, lat_hemi)
        lon_dec = nmea_to_decimal(lon, lon_hemi)
    except (ValueError, IndexError):
        return None, None
    return lat_dec, lon_dec

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    ser = None
    try:
        ser = serial.Serial(PORT, BAUD, timeout=TIMEOUT)
        print(f"Opened {PORT} @ {BAUD} baud. Waiting for GPS fix...")
        while _running:
            try:
                raw = ser.readline()
                if not raw:
                    continue
                line = raw.decode("ascii", errors="replace").strip()
                if not line:
                    continue
                lat, lon = parse_gprmc(line)
                if lat is not None and lon is not None:
                    print(f"Lat: {lat:.6f}, Lon: {lon:.6f}")
            except serial.SerialException as e:
                print(f"Serial error: {e}", file=sys.stderr)
                break
            except Exception as e:
                print(f"Unexpected error: {e}", file=sys.stderr)
            time.sleep(1)
    except serial.SerialException as e:
        print(f"Failed to open {PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Fatal error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

