import serial
import time
import pynmea2
import signal
import sys

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'gps_coordinates_log.txt'

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    """Handle SIGINT for graceful shutdown."""
    global running
    running = False

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection with error handling."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        print(f"Serial port {port} opened successfully.")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing serial port: {e}")
        return None

def read_gps_data(serial_port):
    """Reads a line of GPS data from the serial port."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        return line
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error reading from serial port: {e}")
        return None

def parse_gps_data(gps_data):
    """Parses the GPS data and extracts coordinates."""
    try:
        msg = pynmea2.parse(gps_data)
        # Check if the GPS data is valid (fix quality == 1)
        if msg.gps_qual == '1':
            return msg.latitude, msg.longitude, msg.altitude
        else:
            return None, None, None
    except pynmea2.ParseError as e:
        print(f"Error parsing GPS data: {e}")
        return None, None, None
    except Exception as e:
        print(f"Unexpected error parsing GPS data: {e}")
        return None, None, None

def log_coordinates(latitude, longitude, altitude, log_file):
    """Logs the coordinates to a file with a timestamp."""
    timestamp = time.strftime('%Y-%m-%dT%H:%M:%S')
    log_entry = f'{timestamp} - Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude}\n'
    try:
        with open(log_file, 'a') as file:
            file.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file: {e}")
    except Exception as e:
        print(f"Unexpected error writing to log file: {e}")

def display_coordinates(latitude, longitude, altitude):
    """Prints the coordinates to the console."""
    if latitude is not None and longitude is not None and altitude is not None:
        print(f'Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude} m')

def main():
    """Main function to read, parse, and log GPS data."""
    global running

    # Register signal handler for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        sys.exit(1)

    try:
        while running:
            gps_data = read_gps_data(serial_connection)

            if gps_data:
                latitude, longitude, altitude = parse_gps_data(gps_data)

                if latitude is not None and longitude is not None and altitude is not None:
                    display_coordinates(latitude, longitude, altitude)
                    log_coordinates(latitude, longitude, altitude, LOG_FILE)

            time.sleep(0.1)  # Small delay to prevent excessive CPU usage

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")
        print("Program terminated.")

if __name__ == "__main__":
    main()

