    print("pyserial is required: pip install pyserial", file=sys.stderr)
    sys.exit(1)

app = Flask(__name__)

# ---------------------------------------------------------------------------
# UART connection manager (thread-safe, idempotent, deterministic cleanup)
# ---------------------------------------------------------------------------
_uart_lock = threading.Lock()
_uart_port: Optional[serial.Serial] = None


def _open_uart(port: str = "/dev/ttyUSB0", baudrate: int = 9600,
               timeout: float = 1.0) -> Optional[serial.Serial]:
    """Open a UART port; return the Serial object or None on failure."""
    global _uart_port
    with _uart_lock:
        if _uart_port is not None and _uart_port.is_open:
            return _uart_port
        try:
            _uart_port = serial.Serial(
                port=port,
                baudrate=baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=timeout,
            )
            _uart_port.reset_input_buffer()
            _uart_port.reset_output_buffer()
            return _uart_port
        except SerialException as exc:
            print(f"[UART] Failed to open {port}: {exc}", file=sys.stderr)
            _uart_port = None
            return None


def _close_uart() -> None:
    """Close the UART port if open; reset the reference."""
    global _uart_port
    with _uart_lock:
        if _uart_port is not None:
            try:
                if _uart_port.is_open:
                    _uart_port.close()
            except SerialException as exc:
                print(f"[UART] Error closing port: {exc}", file=sys.stderr)
            finally:
                _uart_port = None


# ---------------------------------------------------------------------------
# Web API
# ---------------------------------------------------------------------------
DATA_STORE: List[Dict[str, Any]] = [
    {"id": 1, "name": "Power Supply A", "done": False},
    {"id": 2, "name": "Power Supply B", "done": False},
]


@app.route("/version", methods=["GET"])
def version() -> Response:
    """Query the instrument identity via *IDN? over UART."""
    port = _open_uart()
    if port is None:
        return Response(
            "500 Internal Server Error: cannot open UART",
            status=500,
            mimetype="text/plain",
        )
    try:
        # Send command as raw bytes; flush to ensure it leaves the buffer promptly
        port.write(b"*IDN?\n")
        port.flush()

        # Read one line (up to timeout)
        raw = port.readline()
        if not raw:
            return Response(
                "504 Gateway Timeout: no response from instrument",
                status=504,
                mimetype="text/plain",
            )
        response = raw.decode("ascii", errors="replace").strip()
        return Response(response, status=200, mimetype="text/plain")
    except SerialException as exc:
        print(f"[UART] Communication error: {exc}", file=sys.stderr)
        return Response(
            f"504 Gateway Timeout: {exc}",
            status=504,
            mimetype="text/plain",
        )
    finally:
        _close_uart()


@app.route("/data", methods=["GET"])
def get_all_data() -> Response:
    """Return all data items as JSON array."""
    return jsonify(DATA_STORE)


@app.route("/data/<int:item_id>", methods=["GET"])
def get_data_item(item_id: int) -> Response:
    """Return a single data item or 404."""
    item = next((it for it in DATA_STORE if it["id"] == item_id), None)
    if item is None:
        return jsonify({"error": "Item not found"}), 404
    return jsonify(item)


@app.route("/data", methods=["POST"])
def create_data_item() -> Response:
    """Create a new data item from incoming JSON."""
    try:
        new_item = request.get_json(silent=True)
    except Exception as exc:
        print(f"[API] Failed to parse JSON body: {exc}", file=sys.stderr)
        return jsonify({"error": "Invalid JSON body"}), 400

    if not isinstance(new_item, dict):
        return jsonify({"error": "Request body must be a JSON object"}), 400

    required_keys = ("name", "done")
    missing = [k for k in required_keys if k not in new_item]
    if missing:
        return jsonify({"error": f"Missing required keys: {missing}"}), 400

    new_id = (DATA_STORE[-1]["id"] + 1) if DATA_STORE else 1
    new_item["id"] = new_id
    DATA_STORE.append(new_item)

    return jsonify(new_item), 201


# ---------------------------------------------------------------------------
# Graceful shutdown
# ---------------------------------------------------------------------------
_shutdown_requested = threading.Event()


def _signal_handler(signum, _frame):
    print(f"\n[Main] Signal {signum} received, shutting down...")
    _shutdown_requested.set()
    # Force a teardown of the web server
    import threading
    threading.Thread(target=lambda: sys.exit(0), daemon=True).start()


def _install_signal_handlers():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)


# ---------------------------------------------------------------------------
# Main entry point
# ---------------------------------------------------------------------------
if __name__ == "__main__":
    _install_signal_handlers()
    try:
        app.run(host="0.0.0.0", port=5000, debug=False)
    finally:
        _close_uart()

