import serial
import time
import sys

PORT = '/dev/ttyUSB0'
BAUD = 9600
TIMEOUT_S = 1


def parse_and_print(line: str) -> None:
    """Parse a comma-separated line into heart_rate and spo2 fields.

    Raises ValueError if the line does not have exactly two fields.
    """
    parts = line.split(',')
    if len(parts) != 2:
        raise ValueError(f"Expected 2 fields, got {len(parts)}: {line!r}")
    heart_rate, spo2 = parts
    print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2} %")


def main() -> int:
    try:
        ser = serial.Serial(
            port=PORT,
            baudrate=BAUD,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT_S,
        )
    except serial.SerialException as exc:
        print(f"Error opening serial port {PORT}: {exc}", file=sys.stderr)
        return 1

    try:
        while True:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f"Error reading from serial port: {exc}", file=sys.stderr)
                break

            if not raw:
                # Timeout with no data; loop and retry.
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                parse_and_print(line)
            except ValueError as exc:
                print(f"Error parsing data: {exc}", file=sys.stderr)
                print(f"  Offending data: {line!r}", file=sys.stderr)

            time.sleep(1)

    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        if ser.is_open:
            ser.close()
            print("Serial port closed.")

    return 0


if __name__ == '__main__':
    sys.exit(main())

