import serial
import serial.tools.list_ports
import time
import sys
from datetime import datetime

# Configuration
SERIAL_PORT = '/dev/serial0'   # Pi 3/4/5 primary UART (GPIO 14/15)
BAUD_RATE = 9600
TIMEOUT = 1                     # seconds
LOG_FILE = 'power_consumption.log'


def parse_power(raw: str) -> float:
    """Parse a raw meter line and return the power in watts as a float."""
    try:
        return float(raw)
    except ValueError:
        raise ValueError(f"Invalid data received from meter: {raw!r}")


def log_power(power: float) -> None:
    """Append a timestamped power reading to the log file."""
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    line = f"{timestamp} – Power: {power} W\n"
    try:
        with open(LOG_FILE, 'a', encoding='utf-8') as fh:
            fh.write(line)
    except OSError as exc:
        print(f"Warning: could not write to log file '{LOG_FILE}': {exc}", file=sys.stderr)


def main() -> None:
    """Open the UART port, read meter lines, and log parsed power values."""
    # Verify the port exists before attempting to open it
    available = [p.device for p in serial.tools.list_ports.comports()]
    if SERIAL_PORT not in available:
        print(
            f"Warning: {SERIAL_PORT} not among available serial ports: {available}",
            file=sys.stderr,
        )

    try:
        with serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        ) as meter_link:
            print(f"Connected to {SERIAL_PORT} @ {BAUD_RATE} baud. Reading meter data...")
            while True:
                try:
                    raw_line = meter_link.readline()
                except serial.SerialException as exc:
                    print(f"Serial read error: {exc}", file=sys.stderr)
                    break

                if not raw_line:
                    # Timeout elapsed with no data
                    continue

                try:
                    power = parse_power(raw_line.decode('ascii', errors='replace').strip())
                except ValueError as exc:
                    print(f"Warning: {exc}", file=sys.stderr)
                    continue

                log_power(power)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except OSError as exc:
        print(f"Error: could not open or read {SERIAL_PORT}: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        print("UART port closed.")


if __name__ == "__main__":
    main()

