import http.server
import socketserver
import json
import time
import serial
import signal
import sys

PORT = 8080
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_DELAY = 0.1

data_store = [
    {"id": 1, "name": "CHIPS", "done": False},
    {"id": 2, "name": "garden", "done": False},
]

serial_connection = None


def init_serial():
    global serial_connection
    try:
        serial_connection = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1.0,
        )
        print(f"Serial port {SERIAL_PORT} opened at {BAUD_RATE} baud.")
    except serial.SerialException as exc:
        print(f"Error opening serial port {SERIAL_PORT}: {exc}")
        serial_connection = None


def close_serial():
    global serial_connection
    if serial_connection is not None:
        try:
            if serial_connection.is_open:
                serial_connection.close()
                print("Serial port closed.")
        except serial.SerialException as exc:
            print(f"Error closing serial port: {exc}")
        finally:
            serial_connection = None


def get_data(request_line):
    if not request_line.startswith('/getdata'):
        return json.dumps({"error": "Not found"})
    return json.dumps(data_store)


def get_item(request_line):
    if not request_line.startswith('/getset/'):
        return json.dumps({"error": "Not found"})
    try:
        item_id = int(request_line.split('/')[2])
    except (ValueError, IndexError):
        return json.dumps({"error": "Bad request"})
    for item in data_store:
        if item['id'] == item_id:
            return json.dumps(item)
    return json.dumps({"error": "Not found"})


def post_item(request_line):
    if not request_line.startswith('/getpost/'):
        return json.dumps({"error": "Not found"})
    try:
        item_id = int(request_line.split('/')[2])
        item_name = request_line.split('/')[3]
    except (ValueError, IndexError):
        return json.dumps({"error": "Bad request"})
    new_id = data_store[-1]['id'] + 1 if data_store else 1
    data_store.append({"id": new_id, "name": item_name, "done": False})
    return json.dumps(data_store)


def post_json_data(request_line):
    if not request_line.startswith('/postjson'):
        return json.dumps({"error": "Not found"})
    length = request_line.split(' ')[0]
    body = request_line.replace(f"{length} ", '')
    try:
        if 'application/json' in request_line:
            data = json.loads(body)
        else:
            data = json.loads(body, strict=False)
    except (json.JSONDecodeError, ValueError) as exc:
        return json.dumps({"error": f"Invalid JSON: {exc}"})
    new_id = data_store[-1]['id'] + 1 if data_store else 1
    data['id'] = new_id
    if 'name' in data:
        data['name'] = str(data['name'])
    if 'done' in data:
        data['done'] = bool(data['done'])
    data_store.append(data)
    return json.dumps(data_store)


class WebhookHandler(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == '/':
            self.send_response(301)
            self.send_header('Location', '/index.html')
            self.end_headers()
        elif self.path.endswith('/'):
            self.send_response(301)
            self.send_header('Location', self.path + 'index.html')
            self.end_headers()
        elif self.path == '/index.html':
            content = b'<html><body><h1>Welcome to the webhook endpoint!</h1><a href="/getdata">Get data</a></body></html>'
            self.send_response(200)
            self.send_header('Content-Type', 'text/html')
            self.send_header('Content-Length', str(len(content)))
            self.end_headers()
            self.wfile.write(content)
        elif self.path == '/style.css':
            self.send_response(200)
            self.send_header('Content-Type', 'text/css')
            self.send_header('Content-Length', '22')
            self.end_headers()
            self.wfile.write(b'.h1 { color: red; }')
        else:
            handler_map = {
                '/getdata': get_data,
                '/getset/<int:item_id>': get_item,
                '/getpost/<int:item_id>/<name>': post_item,
            }
            handler = handler_map.get(self.path)
            if handler:
                result = handler(self.path)
                self.send_response(200)
                self.send_header('Content-Type', 'application/json')
                self.send_header('Content-Length', str(len(result)))
                self.end_headers()
                self.wfile.write(result.encode('utf-8'))
            else:
                self.send_response(404)
                self.end_headers()

    def do_POST(self):
        if self.path == '/postjson':
            length = self.headers.get('Content-Length')
            if length and int(length) > 1024 * 1024:
                self.send_response(413)
                self.end_headers()
                self.wfile.write(b'Request too large')
                return
            body = self.rfile.read(int(length) if length else 1024).decode('utf-8', errors='replace')
            handler = post_json_data
        else:
            length = self.headers.get('Content-Length')
            if length and int(length) > 1024 * 1024:
                self.send_response(413)
                self.end_headers()
                self.wfile.write(b'Request too large')
                return
            body = self.rfile.read(int(length) if length else 1024).decode('utf-8', errors='replace')
            handler = post_item
        try:
            if 'application/json' in self.headers.get('Content-Type', ''):
                data = json.loads(body)
            else:
                data = json.loads(body, strict=False)
        except (json.JSONDecodeError, ValueError) as exc:
            self.send_response(400)
            self.end_headers()
            self.wfile.write(f'Invalid JSON: {exc}'.encode('utf-8'))
            return
        result = handler(self.path)
        self.send_response(201)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(result)))
        self.end_headers()
        self.wfile.write(result.encode('utf-8'))

    def log_message(self, format, *args):
        print(f"{self.client_address[0]} - {format % args}")


def main():
    init_serial()
    signal.signal(signal.SIGINT, lambda *_: (_ for _ in ()).throw(SystemExit(0)))
    signal.signal(signal.SIGTERM, lambda *_: (_ for _ in ()).throw(SystemExit(0)))
    with socketserver.TCPServer(("0.0.0.0", PORT), WebhookHandler) as httpd:
        print(f"Serving at port {PORT}")
        try:
            httpd.serve_forever()
        except KeyboardInterrupt:
            pass
        finally:
            close_serial()
            httpd.server_close()
            print("Server stopped.")


if __name__ == '__main__':
    main()

