import time
import signal
import sys
import bluetooth

BLUETOOTH_DEVICE = "00:11:22:33:44:55"
BLUETOOTH_PORT = "0"
BAUD_RATE = 38400

running = True

def signal_handler(signum, frame):
    global running
    running = False

def send_command(conn, command):
    try:
        conn.send(command)
        time.sleep(0.1)
    except Exception as e:
        raise RuntimeError(f"Failed to send command '{command}': {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        conn = bluetooth.BluetoothSocket(
            bluetooth.RFCOMM,
            address=BLUETOOTH_DEVICE,
            port=int(BLUETOOTH_PORT),
            baudrate=BAUD_RATE
        )
        conn.connect()
        print(f"Connected to {BLUETOOTH_DEVICE}:{BLUETOOTH_PORT} at {BAUD_RATE} baud.")

        while running:
            try:
                user_command = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_command.strip().lower() == "exit":
                break

            command_with_prefix = f"X{user_command}\n"
            try:
                send_command(conn, command_with_prefix)
            except RuntimeError as e:
                print(f"Error: {e}")
                break

    except bluetooth.BluetoothError as e:
        print(f"Bluetooth error: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
        sys.exit(1)
    finally:
        if 'conn' in locals() and conn.isconnected():
            conn.close()
            print("Disconnected from Bluetooth device.")

if __name__ == "__main__":
    main()

